-- 0. CẬP NHẬT RÀNG BUỘC DUY NHẤT THEO (jlpt_level, character) & LÀM SẠCH DỮ LIỆU N1 CŨ
ALTER TABLE kanjis DROP CONSTRAINT IF EXISTS uq_kanjis_character;
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint WHERE conname = 'uq_kanjis_level_character'
    ) THEN
        ALTER TABLE kanjis ADD CONSTRAINT uq_kanjis_level_character UNIQUE (jlpt_level, character);
    END IF;
END $$;
ALTER TABLE kanji_chapter_vocab ALTER COLUMN meaning_vi TYPE TEXT;
ALTER TABLE kanji_chapter_vocab ALTER COLUMN meaning_en TYPE TEXT;
DELETE FROM kanjis WHERE jlpt_level = 'N1';

