    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('塗', 'トリ, ト', 'ぬ.る, ぬ.り', 'nuru', 'ĐỒ, TRÀ', 'Sơn, Thuốc bôi', 17, '亻 -> 土 -> 氵', '亻', 'ペンキを塗る (ペンキをぬる: Sơn)、塗り薬 (ぬりぐすり: Thuốc bôi)、塗料 (とりょう: Sơn)、塗装 (とそう: Sơn ngoài)', 'ペンキを塗る（ペンキをぬる）', 'penkionuru', 'Sơn', 'N1', 'Chiết tự Hán Việt: ĐỒ, TRÀ (塗)', 'Ngày xưa người ta thường đổ DƯ một chút NƯỚC vào ĐẤT cho nhão ra rồi đem chát, bôi vào ĐÔ sứ để tạo mầu', '✋', v_ch1_id, 16, '/assets/kanji/n1/illustrations/chap1_intro.webp', NOW())
