    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('聴', 'チョウ', '', 'chou', 'THÍNH', 'Bài tập nghe, Thính giác', 17, '耳 -> 目 -> 忄', '耳', '聴解問題 (ちょうかいもんだい: Bài tập nghe)、聴覚 (ちょうかく: Thính giác)、聴講生 (ちょうこうせい: Thính giả)、聴診器 (ちょうしんき: Ông nghe khám bệnh)', '聴解問題（ちょうかいもんだい）', 'choukaimondai', 'Bài tập nghe', 'N1', 'Chiết tự Hán Việt: THÍNH (聴)', 'Tai muốn nghe THÍNH phải tập trung bằng cả trái tim và 10 con mắt', '✋', v_ch1_id, 20, '/assets/kanji/n1/illustrations/chap1_intro.webp', NOW())
