    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('眺', 'チョウ', 'なが.める', 'nagameru', 'THIẾU', 'Ngắm, Tầm nhìn', 14, '兆 -> 目', '兆', '眺める (ながめる: Ngắm, nhìn)、眺望 (ちょうぼう: Tầm nhìn, tầm quan sát)', '眺める（ながめる）', 'nagameru', 'Ngắm, nhìn', 'N1', 'Chiết tự Hán Việt: THIẾU (眺)', 'Ông trời có TRIỆU (兆) con MẮT (目) nên TẦM nhìn (眺) không THIẾU sót một nơi nào', '✋', v_ch1_id, 21, '/assets/kanji/n1/illustrations/chap1_intro.webp', NOW())
