    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('隠', 'イン', 'かく.れる, かく.す', 'kakureru', 'ẨN', 'Mặt trăng ẩn nấp sau làn mây, Giấu mình', 14, '忄 -> 隠', '忄', '月が雲に隠れる (つきがくもにかくれる: Mặt trăng ẩn nấp sau làn mây)、姿を隠す (すがたをかくす: Giấu mình)、隠居する (いんきょする: Ẩn cư, về hưu)', '月が雲に隠れる（つきがくもにかくれる）', 'tsukigakumonikakureru', 'Mặt trăng ẩn nấp sau làn mây', 'N1', 'Chiết tự Hán Việt: ẨN (隠)', 'BỐ sống nội TÂM nên ĐƯƠNG nhiên sẽ hướng về Ở ẨN', '✋', v_ch1_id, 22, '/assets/kanji/n1/illustrations/chap1_intro.webp', NOW())
