    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('添', 'テン', 'そ.う, そ.える', 'sou', 'THIÊM', 'Kèm theo nguyện vọng, Thêm vào', 14, '灬 -> 扌', '灬', '希望に添う (きぼうにそう: Kèm theo nguyện vọng)、添える (そえる: Thêm vào, đính kèm)、添付する (てんぷする: Gắn thêm, đính thêm)、食品添加物 (しょくひんてんかぶつ: Chất phụ gia)', '希望に添う（きぼうにそう）', 'kibounisou', 'Kèm theo nguyện vọng', 'N1', 'Chiết tự Hán Việt: THIÊM (添)', 'Đổ thêm dầu vào lửa đốt cháy trời thủ THIÊM', '✋', v_ch1_id, 23, '/assets/kanji/n1/illustrations/chap1_intro.webp', NOW())
