    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('伴', 'バン', 'ともな.って, ともな.う', 'tomonatte', 'BẠN', 'Đi công tác cùng cấp dưới, Công việc có tính chất nguy hiểm', 14, '亻 -> 伴', '亻', '部下を伴って出張する (ぶかをともなってしゅっちょうする: Đi công tác cùng cấp dưới)、危険を伴う仕事 (きけんをともなうしごと: Công việc có tính chất nguy hiểm)、言動が伴わない (げんどうがともなわない: Lời nói và hành động không đi đôi với nhau)、伴奏 (ばんそう: Đệm nhạc)', '部下を伴って出張する（ぶかをともなってしゅっちょうする）', 'bukaotomonatteshucchousuru', 'Đi công tác cùng cấp dưới', 'N1', 'Chiết tự Hán Việt: BẠN (伴)', '1 Nửa của bản thân chính là người BẠN đời', '✋', v_ch1_id, 31, '/assets/kanji/n1/illustrations/chap1_intro.webp', NOW())
