    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('尽', 'ジン', 'つ.きた, つ.きない', 'tsukita', 'TẬN', 'Cạn kiệt cả nước uông và đồ ăn, Nói không hết chuyện', 14, '力 -> 尽', '力', '水も食料も尽きた (みずもしょくりょうもつきた: Cạn kiệt cả nước uông và đồ ăn)、話が尽きない (はなしがつきない: Nói không hết chuyện)、愛想を尽かす (あいそをつかす: Cạn tình, hết yêu)、尽力 (じんりょく: Dốc toàn lực)', '水も食料も尽きた（みずもしょくりょうもつきた）', 'mizumoshokuryoumotsukita', 'Cạn kiệt cả nước uông và đồ ăn', 'N1', 'Chiết tự Hán Việt: TẬN (尽)', 'TẬN sức phá Xích Băng', '✋', v_ch1_id, 33, '/assets/kanji/n1/illustrations/chap1_intro.webp', NOW())
