    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('耐', 'タイ', 'た.える', 'taeru', 'NẠI', 'nhẫn nại, tính bền', 14, '亻 -> 耐', '亻', '耐える (たえる: nhẫn nại, chịu đựng)、耐久性 (たいきゅうせい: tính bền)、耐震構造 (たいしんこうぞう: cấu tạo chống động đất)、耐燃ガラス (たいねんガラス: thủy tinh chịu nhiệt)', '耐える（たえる）', 'taeru', 'nhẫn nại, chịu đựng', 'N1', 'Chiết tự Hán Việt: NẠI (耐)', '4 người xếp hàng tuy thốn nhưng vẫn nhẫn NẠI', '✋', v_ch1_id, 38, '/assets/kanji/n1/illustrations/chap1_intro.webp', NOW())
