    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('陥', 'カン', 'おちい.る, おとしい.れる', 'ochiiru', 'HÃM', 'rơi vào tình trạng chán ghét bản thân, lâm vào bất hạnh', 14, '氵 -> 陥', '氵', '自己嫌悪に陥る (じこけんおにおちいる: rơi vào tình trạng chán ghét bản thân)、不幸に陥れる (ふこうにおとしいれる: lâm vào bất hạnh)、商品に欠陥がある (しょうひんにけっかんがある: sản phẩm có lỗi)', '自己嫌悪に陥る（じこけんおにおちいる）', 'jikokenoniochiiru', 'rơi vào tình trạng chán ghét bản thân', 'N1', 'Chiết tự Hán Việt: HÃM (陥)', 'Vào một ngày bờ sông bị vây HÃM  quanh các góc giác', '🔄', v_ch2_id, 5, '/assets/kanji/n1/illustrations/chap2_intro.webp', NOW())
