    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('迫', 'ハク, パク', 'せま.る', 'semaru', 'BÁCH', 'thời hạn trả nợ đang tới gàn, bị đe dọa', 14, '一 -> 迫', '迫', '借金の返済期限が迫る (しゃっきんのへんさいきげんがせまる: thời hạn trả nợ đang tới gàn)、脅迫される (きょうはくされる: bị đe dọa)、迫害を受ける (はくがいをうける: bị khủng bố)、胸を圧迫される (むねをあっぱくされる: bị tức ngực)', '借金の返済期限が迫る（しゃっきんのへんさいきげんがせまる）', 'shakkinnohensaikigengasemaru', 'thời hạn trả nợ đang tới gàn', 'N1', 'Chiết tự Hán Việt: BÁCH (迫)', 'Đường dẫn màu trắng thì có cảm giác bức BÁCH', '🔄', v_ch2_id, 6, '/assets/kanji/n1/illustrations/chap2_intro.webp', NOW())
