    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('免', 'メン', '', 'men', 'MIỄN', 'trốn tránh trách nhiệm, bằng', 14, '一 -> 免', '免', '責任を免れる (せきにんを免れる: trốn tránh trách nhiệm)、免許 (めんきょ: bằng)、免除 (めんじょ: miễn trừ)、免税品 (めんぜいひん: sản phẩm miễn thuế)', '責任を免れる（せきにんを免れる）', 'sekinino免reru', 'trốn tránh trách nhiệm', 'N1', 'Chiết tự Hán Việt: MIỄN (免)', 'MIỄN học phí cho trẻ bị cận', '🔄', v_ch2_id, 19, '/assets/kanji/n1/illustrations/chap2_intro.webp', NOW())
