    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('劣', 'レツ', 'おと.る', 'otoru', 'LIỆT', 'hiệu suất kém, cách làm hèn hạ', 14, '力 -> 劣', '力', '性能が劣る (せいのうがおとる: hiệu suất kém)、卑劣なやり方 (ひれつなやりかた: cách làm hèn hạ)、劣悪な環境 (れつあくなかんきょう: môi trường tồi tàn,kém)、劣等感 (れっとうかん: cảm giác thấp kém, yếu thế)', '性能が劣る（せいのうがおとる）', 'seinougaotoru', 'hiệu suất kém', 'N1', 'Chiết tự Hán Việt: LIỆT (劣)', 'Thiếu Lực bị LIỆT vào hàng YẾU KÉM', '🔄', v_ch2_id, 22, '/assets/kanji/n1/illustrations/chap2_intro.webp', NOW())
