    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('奮', 'フン', 'ふる.う', 'furuu', 'PHẤN', 'khuyến khích, hưng phấn', 17, '金 -> 田 -> 隹', '金', '勇気を奮う (ゆうきをふるう: khuyến khích, cổ vũ)、興奮する (こうふんする: hưng phấn)、一人で奮闘する (ひとりでふんとうする: một mình cố gắng)、奮発する (ふんぱつする: hào phóng)', '勇気を奮う（ゆうきをふるう）', 'yuukiofuruu', 'khuyến khích, cổ vũ', 'N1', 'Chiết tự Hán Việt: PHẤN (奮)', 'Trên đồng (田) thấy chú chim (隹) to (大) Đột nhiên PHẤN(奮) khởi âu lo chẳng còn', '🔄', v_ch2_id, 30, '/assets/kanji/n1/illustrations/chap2_intro.webp', NOW())
