    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('辱', 'ジョク', 'はずかし.め', 'hazukashime', 'NHỤC', 'chịu xấu hổ trước mặt mọi người, lời nói và hành động lăng mạ', 14, '一 -> 辱', '辱', '人前で辱めを受ける (ひとまえではずかしめをうける: chịu xấu hổ trước mặt mọi người)、侮辱的な言動 (ぶじょくてきなげんどう: lời nói và hành động lăng mạ)、雪辱を果たす (せつじょくをはたす: lấy lại danh dự)', '人前で辱めを受ける（ひとまえではずかしめをうける）', 'hitomaedehazukashimeoukeru', 'chịu xấu hổ trước mặt mọi người', 'N1', 'Chiết tự Hán Việt: NHỤC (辱)', 'Thần mà bị thốn thì đúng là NHỤC', '🔄', v_ch2_id, 38, '/assets/kanji/n1/illustrations/chap2_intro.webp', NOW())
