    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('貴', 'キチ, キ', 'とうと.ぶ, とうと.い', 'toutobu', 'QUÝ', 'quý trọng sinh mệnh, tôn trọng sự thật', 14, '一 -> 貴', '貴', '生命を貴ぶ (せいめいをとうとぶ: quý trọng sinh mệnh)、真実を貴ぶ (しんじつをとうとぶ: tôn trọng sự thật)、貴い命 (とうといいのち: mạng sống quý giá)、貴い身分の方 (とうといみぶんのほう: người có địa vị cao quý)', '生命を貴ぶ（せいめいをとうとぶ）', 'seimeiotoutobu', 'quý trọng sinh mệnh', 'N1', 'Chiết tự Hán Việt: QUÝ (貴)', 'con sâu rất QUÝ trọng con sò', '👥', v_ch3_id, 16, '/assets/kanji/n1/illustrations/chap3_intro.webp', NOW())
