    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('己', 'オノ', 'おのれ', 'onore', 'KỶ', 'làm tròn  trách nhiệm của bản thân, trách nhiệm bản thân', 14, '亻 -> 己', '亻', '己の責任を果たす (おのれのせきにんをはたす: làm tròn  trách nhiệm của bản thân)、自己責任 (じこせきにん: trách nhiệm bản thân)、利己主義 (りこしゅぎ: chủ nghĩa cá nhân)、２０年来の知己 (２０ねんらいのちき: bạn tri kỉ từ 20 năm)', '己の責任を果たす（おのれのせきにんをはたす）', 'onorenosekininohatasu', 'làm tròn  trách nhiệm của bản thân', 'N1', 'Chiết tự Hán Việt: KỶ (己)', 'Vì mày ích KỶ nên bị phạt quỳ gối (hình tượng người đang quỳ gối', '👥', v_ch3_id, 29, '/assets/kanji/n1/illustrations/chap3_intro.webp', NOW())
