    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('葬', 'ソウ', 'ほうむ.る', 'houmuru', 'TÁNG', 'chôn lấp, lễ tang', 17, '艹 -> 忄 -> 扌', '艹', '葬る (ほうむる: chôn lấp, an táng)、葬式 (そうしき: lễ tang)、葬儀 (そうぎ: lễ ma chay)、冠婚葬祭 (かんこんそうさい: 4 nghi lễ lớn của đời người (冠成人式 Lễ thành nhân, lễ trưởng thành, 婚 結婚式 Lễ cưới, 葬 葬式 Đám tang, 祭 法事 Giỗ))', '葬る（ほうむる）', 'houmuru', 'chôn lấp, an táng', 'N1', 'Chiết tự Hán Việt: TÁNG (葬)', 'Chữ TÁNG hay thật. Bộ THẢO, bộ TỬ, bộ CỦNG (chắp tay). An TÁNG người CHẾT rồi thể hiện lòng thương tiếc nên người ta CHẮP tay cúi đầu', '👥', v_ch3_id, 34, '/assets/kanji/n1/illustrations/chap3_intro.webp', NOW())
