    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('忌', 'キ', 'い.み, い.まわしい', 'imi', 'KỊ', 'rất ghét, quá khứ tồi tệ', 14, '忄 -> 忌', '忄', '忌み嫌う (いみきらう: rất ghét)、忌まわしい過去 (いまわしいかこ: quá khứ tồi tệ)、忌引を取る (きびきをとる: nghỉ học vì nhà có tang)、一周忌 (いっしゅうき: giỗ đầu)', '忌み嫌う（いみきらう）', 'imikirau', 'rất ghét', 'N1', 'Chiết tự Hán Việt: KỊ (忌)', 'TÂM ích KỈ luôn đố KỊ', '👥', v_ch3_id, 35, '/assets/kanji/n1/illustrations/chap3_intro.webp', NOW())
