    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('墓', 'ハカ, ボ', '', 'haka', 'MỘ', 'đi thăm mộ, nghĩa địa', 14, '艹 -> 土', '艹', '墓参りをする (はかまいりをする: đi thăm mộ)、墓地 (ぼち: nghĩa địa)、墓穴を掘る (ぼけつをほる: đào mộ, đào huyệt)', '墓参りをする（はかまいりをする）', 'hakamairiosuru', 'đi thăm mộ', 'N1', 'Chiết tự Hán Việt: MỘ (墓)', 'Trên là cỏ hoa mặt trời chiếu dưới có mái đất che là ngội MỘ', '👥', v_ch3_id, 37, '/assets/kanji/n1/illustrations/chap3_intro.webp', NOW())
