    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('故', 'フル, コ', 'ゆえ', 'yue', 'CỐ', 'vì, nhớ quê hương', 14, '一 -> 故', '故', '故に ゆえに (ゆえに ゆえに: vì, do...)、故郷を懐かしむ (ふるさとをなつかしむ: nhớ quê hương)、故人をしのぶ (こじんをしのぶ: nhớ về bạn cũ)、交通事故 (こうつうじこ: tai nạn giao thông)', '故に ゆえに（ゆえに ゆえに）', 'yueni yueni', 'vì, do...', 'N1', 'Chiết tự Hán Việt: CỐ (故)', 'Đập nát đồ CỔ là sự CỐ lớn', '👥', v_ch3_id, 38, '/assets/kanji/n1/illustrations/chap3_intro.webp', NOW())
