    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('魂', 'コン', 'たましい', 'tamashii', 'HỒN', 'linh hồn người chết, bộ dạng như mất hồn', 14, '雨 -> 魂', '雨', '死者の魂 (ししゃのたましい: linh hồn người chết)、魂が抜けたような姿 (たましいがぬけたようなすがた: bộ dạng như mất hồn)、精魂込めた仕事 (せいこんこめたしごと: công việc đã dốc hết tâm huyết)、商魂 (しょうこん: nung nấu ý tưởng về buôn bán)', '死者の魂（ししゃのたましい）', 'shishanotamashii', 'linh hồn người chết', 'N1', 'Chiết tự Hán Việt: HỒN (魂)', 'Linh HỒN của Quỷ ẩn phía sau đám mây', '👥', v_ch3_id, 39, '/assets/kanji/n1/illustrations/chap3_intro.webp', NOW())
