    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('芋', 'モ', 'いも', 'imo', 'DỤ', 'khoai tây, củ mài', 14, '艹 -> 芋', '艹', 'じゃが芋 (じゃがいも: khoai tây)、山芋 (やまいも: củ mài, củ từ)、里芋 (さといも: khoai môn)、芋を洗うような人込み (いもをあらうようなひとごみ: người đông như trẩy hội)', 'じゃが芋（じゃがいも）', 'jagaimo', 'khoai tây', 'N1', 'Chiết tự Hán Việt: DỤ (芋)', 'Trên hoa dưới bốn rễ phụ một rễ cọc là củ khoai', '🍲', v_ch4_id, 3, '/assets/kanji/n1/illustrations/chap4_intro.webp', NOW())
