    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('栗', 'グリ', '', 'guri', 'LẬT', 'bóc vỏ hạt dẻ, mọi thứ đều cần có thời gian', 14, '西 -> 木', '西', '甘栗をむく (あまぐりをむく: bóc vỏ hạt dẻ)、桃栗三年柿八年 (ももくりさんねんかきはちねん: mọi thứ đều cần có thời gian)', '甘栗をむく（あまぐりをむく）', 'amaguriomuku', 'bóc vỏ hạt dẻ', 'N1', 'Chiết tự Hán Việt: LẬT (栗)', 'TÂY (西) trèo CÂY (木) dẻ run như con LẬT đật', '🍲', v_ch4_id, 4, '/assets/kanji/n1/illustrations/chap4_intro.webp', NOW())
