    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('腐', 'フ, フシ', 'くさ.る, くさ.れる', 'kusaru', 'HỦ', 'đồ ăn bị hư hại, hờn dỗi', 17, '月 -> 宀 -> 目', '月', '食べ物が腐る (たべものがくさる: đồ ăn bị hư hại)、ふて腐れる (ふてくされる: hờn dỗi, làm nững)、牛乳を腐らせる (ぎゅうにゅうをくさらせる: sữa bị hỏng)、腐敗 (ふはい: mục nát)', '食べ物が腐る（たべものがくさる）', 'tabemonogakusaru', 'đồ ăn bị hư hại', 'N1', 'Chiết tự Hán Việt: HỦ (腐)', 'Trong nhà gắn thịt lâu ngày thì bị mục rữa', '🍲', v_ch4_id, 5, '/assets/kanji/n1/illustrations/chap4_intro.webp', NOW())
