    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('沸', 'ユガ', 'わ.く, わ.かす', 'waku', 'PHÍ', 'nước sôi, đun nước sôi', 14, '弓 -> 氵', '弓', '湯が沸く (ゆがわく: nước sôi)、湯を沸かす (ゆをわかす: đun nước sôi)、会場がどっと沸く (かいじょうがどっとわく: hội trường mất chọt trở nên sôi động)、沸点 (沸点: mức sôi)', '湯が沸く（ゆがわく）', 'yugawaku', 'nước sôi', 'N1', 'Chiết tự Hán Việt: PHÍ (沸)', 'bỏ hai CUNG tên để đun NƯỚC thì quá PHÍ', '🍲', v_ch4_id, 9, '/assets/kanji/n1/illustrations/chap4_intro.webp', NOW())
