    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('騰', 'トウ', '', 'tou', 'ĐẰNG', 'nước sôi, tăng vọt', 17, '車 -> 月 -> 灬', '車', '沸騰する (ふっとうする: nước sôi)、高騰する (こうとうする: tăng vọt)、株価が急騰する (かぶかがきゅうとうする: giá cổ phiếu đột ngột tăng)', '沸騰する（ふっとうする）', 'futtousuru', 'nước sôi', 'N1', 'Chiết tự Hán Việt: ĐẰNG (騰)', 'Nguyệt cầm 2 ngọn lửa cưỡi lên ngựa đi về ĐẰNG xa', '🍲', v_ch4_id, 10, '/assets/kanji/n1/illustrations/chap4_intro.webp', NOW())
