    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('刃', 'ハ, ジン', 'は', 'ha', 'NHẬN', 'lưỡi dao sắc, lưỡi dao cạo', 14, '刂 -> 刃', '刂', '刃が鋭い (はがするどい: lưỡi dao sắc)、かみそりの刃 (かみそりのは: lưỡi dao cạo)、刃物 (はもの: dao kéo)、凶刃に倒れる (きょうじんにたおれる: bị ám sát)', '刃が鋭い（はがするどい）', 'hagasurudoi', 'lưỡi dao sắc', 'N1', 'Chiết tự Hán Việt: NHẬN (刃)', 'ĐAO đã có CHỦ , NHẬN vơ là CHÉM', '🍲', v_ch4_id, 31, '/assets/kanji/n1/illustrations/chap4_intro.webp', NOW())
