    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('暇', 'カ', 'ひま', 'hima', 'HẠ', 'rảnh rỗi, quá rảnh rỗi', 14, '一 -> 暇', '暇', '暇な (ひまな: rảnh rỗi)、暇を持て余す (ひまをもてあます: quá rảnh rỗi)、休暇 (きゅうか: kỳ nghỉ)、余暇 (よか: thời gian rảnh rỗi)', '暇な（ひまな）', 'himana', 'rảnh rỗi', 'N1', 'Chiết tự Hán Việt: HẠ (暇)', '1 ngày đi Lại nhàn HẠ trên cầu thang', '⚖️', v_ch5_id, 2, '/assets/kanji/n1/illustrations/chap5_intro.webp', NOW())
