    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('徴', 'チョウ', '', 'chou', 'TRƯNG', 'trưng thu, biểu tượng', 17, '王 -> 山 -> 口', '王', '徴収する (ちょうしゅうする: trưng thu)、象徴 (しょうちょう: biểu tượng, tượng trưng)、特徴 (とくちょう: đặc trưng)', '徴収する（ちょうしゅうする）', 'choushuusuru', 'trưng thu', 'N1', 'Chiết tự Hán Việt: TRƯNG (徴)', 'Đặc TRƯNG của vua là đội vương miệng giống quả NÚI, hai bên quan võ cầm XÍCH, quan văn cầm PHỘC', '⚖️', v_ch5_id, 8, '/assets/kanji/n1/illustrations/chap5_intro.webp', NOW())
