    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('稚', 'チ', '', 'chi', 'TRĨ', 'trường mầm non, suy nghĩ trẻ con', 17, '鳥 -> 隹 -> 禾', '鳥', '幼稚園 (ようちえん: trường mầm non)、幼稚な考え (ようちなかんがえ: suy nghĩ trẻ con)、稚魚を放流する (ちぎょをほうりゅうする: thả cá con)、稚児 ちご (ちご ちご: đứa bé)', '幼稚園（ようちえん）', 'youchien', 'trường mầm non', 'N1', 'Chiết tự Hán Việt: TRĨ (稚)', 'con Chim (隹) TRĨ (稚) đang ăn Lúa (禾) non', '⚖️', v_ch5_id, 10, '/assets/kanji/n1/illustrations/chap5_intro.webp', NOW())
