    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('猛', 'モウ', '', 'mou', 'MÃNH', 'thú dữ, chiến đấu 1 cách mãnh liệt', 17, '犭 -> 犬 -> 子', '犭', '猛獣 (もうじゅう: thú dữ)、猛然と戦う (もうぜんとたたかう: chiến đấu 1 cách mãnh liệt)、猛暑 (もうしょ: nắng nóng gay gắt)', '猛獣（もうじゅう）', 'moujuu', 'thú dữ', 'N1', 'Chiết tự Hán Việt: MÃNH (猛)', 'chó (犬) con (子) liếm đĩa cháo (皿) dũng MÃNH (猛) lạ thường', '⚖️', v_ch5_id, 11, '/assets/kanji/n1/illustrations/chap5_intro.webp', NOW())
