    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('壮', 'ソウ', '', 'sou', 'TRÁNG', 'thời kỳ đỉnh cao, hùng tráng', 14, '一 -> 壮', '壮', '壮年 (そうねん: thời kỳ đỉnh cao)、勇壮な (ゆうそうな: hùng tráng)、壮絶な (そうぜつな: vĩ đại)、壮行会 (そうこうかい: tiệc chia tay)', '壮年（そうねん）', 'sounen', 'thời kỳ đỉnh cao', 'N1', 'Chiết tự Hán Việt: TRÁNG (壮)', 'TRÁNG sĩ đứng dựa tường', '⚖️', v_ch5_id, 14, '/assets/kanji/n1/illustrations/chap5_intro.webp', NOW())
