    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('陰', 'カゲ, イン', 'かげ.る, かげ.り', 'kageru', 'ÂM', 'ngày u ám, nhìn thấy nét mặt u ám', 17, '言 -> 阝 -> 今', '言', '日が陰る (ひがかげる: ngày u ám)、顔に陰りが見える (かおにかげりがみえる: nhìn thấy nét mặt u ám)、木陰で涼をとる (こかげでりょうをとる: hóng mát dưới tán cây)、日陰 (ひかげ: bóng râm)', '日が陰る（ひがかげる）', 'higakageru', 'ngày u ám', 'N1', 'Chiết tự Hán Việt: ÂM (陰)', 'Vùng Đất (阝) Hiện Tại (今) phát ra lời Nói (云) từ người ÂM(陰)', '⚖️', v_ch5_id, 15, '/assets/kanji/n1/illustrations/chap5_intro.webp', NOW())
