    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('膨', 'ボウ', 'ふく.らむ, ふく.らませる', 'fukuramu', 'BÀNH', 'nụ hoa nở, tràn đầy hy vọng', 14, '月 -> 土', '月', 'つぼみが膨らむ (つぼみがふくらむ: nụ hoa nở)、希望に胸を膨らませる (きぼうにむねをふくらませる: tràn đầy hy vọng)、借金が膨れ上がる (しゃっきんがふくれあがる: nợ nần chồng chất)、膨大な (ぼうだいな: lớn, nhiều, khổng lồ)', 'つぼみが膨らむ（つぼみがふくらむ）', 'tsubomigafukuramu', 'nụ hoa nở', 'N1', 'Chiết tự Hán Việt: BÀNH (膨)', 'Dưới ánh TRĂNG, nằm dưới mặt ĐẤT, hạt ĐẬU đang mọc TÓC và BÀNH trướng và to lớn ra', '⚖️', v_ch5_id, 16, '/assets/kanji/n1/illustrations/chap5_intro.webp', NOW())
