    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('奇', 'キ', '', 'ki', 'KÌ', 'trang phục mới lạ, kỳ tích xảy ra', 14, '一 -> 奇', '奇', '奇抜な服装 (きばつなふくそう: trang phục mới lạ)、奇跡が起きる (きせきがおきる: kỳ tích xảy ra)、数奇な運命 (すうきなうんめい: số phận bất hạn)、奇数―偶数 (きすう―ーぐうすう: số lẻ- số chẵn)', '奇抜な服装（きばつなふくそう）', 'kibatsunafukusou', 'trang phục mới lạ', 'N1', 'Chiết tự Hán Việt: KÌ (奇)', 'Cái gì to mà khả dụng thì rất là KÌ diệu', '⚖️', v_ch5_id, 17, '/assets/kanji/n1/illustrations/chap5_intro.webp', NOW())
