    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('妙', 'ミョウ, ョウ', 'みょう', 'myou', 'DIỆU', 'hợp nhau với a  ấy 1 cách kỳ lạ, kỹ thuật tuyệt vời', 17, '亻 -> 女 -> 少', '亻', '彼と妙に気が合う (かれとみょうにきがあう: hợp nhau với a  ấy 1 cách kỳ lạ)、絶妙な技 (ぜつみょうなわざ: kỹ thuật tuyệt vời)、奇妙な現象 (きみょうなげんしょう: hiện tượng kỳ lạ)', '彼と妙に気が合う（かれとみょうにきがあう）', 'karetomyounikigaau', 'hợp nhau với a  ấy 1 cách kỳ lạ', 'N1', 'Chiết tự Hán Việt: DIỆU (妙)', 'Người phụ nữ ( 女) mà nói ít (少) thì đó là điều kì DIỆU', '⚖️', v_ch5_id, 18, '/assets/kanji/n1/illustrations/chap5_intro.webp', NOW())
