    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('微', 'ビシ, ビリ', '', 'bishi', 'VI', 'cười mỉm, lượng nhỏ', 17, '足 -> 彳 -> 山', '足', '微笑 (びしょう: cười mỉm)、微量 (びりょう: lượng nhỏ)、微々たる (びびたる: không đáng kể, ít)、微妙な (びみょうな: không rõ ràng)', '微笑（びしょう）', 'bishou', 'cười mỉm', 'N1', 'Chiết tự Hán Việt: VI (微)', 'Con đường 彳 lên núi 山 còn sót lại dấu chân 兀 NHỎ sau trận đánh 攵 nhau hôm qua', '⚖️', v_ch5_id, 19, '/assets/kanji/n1/illustrations/chap5_intro.webp', NOW())
