    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('凡', 'ボン, ハン', '', 'bon', 'PHÀM', 'bình thường, tài năng phi phàm', 14, '糸 -> 凡', '糸', '平凡な (へいぼんな: bình thường)、非凡な才能 (ひぼんなさいのう: tài năng phi phàm)、凡人 (ぼんじん: người bình thường)、凡例 (はんれい: chú thích, chú giải)', '平凡な（へいぼんな）', 'heibonna', 'bình thường', 'N1', 'Chiết tự Hán Việt: PHÀM (凡)', 'kẻ PHÀM phu tục tử thì chỉ được ngồi ghế đẩu thôi', '⚖️', v_ch5_id, 21, '/assets/kanji/n1/illustrations/chap5_intro.webp', NOW())
