    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('乙', 'オツ, オ', 'おつ', 'otsu', 'ẤT', 'mùi vị lạ, khó phân định', 14, '金 -> 乙', '金', '乙な味 (おつなあじ: mùi vị lạ)、甲乙つけがたい (こうおつつけがたい: khó phân định, 1 chín 1 mười)、乙女 (おとめ: thiếu nữ)', '乙な味（おつなあじ）', 'otsunaaji', 'mùi vị lạ', 'N1', 'Chiết tự Hán Việt: ẤT (乙)', 'Hợp đồng của tiểu ẤT là bên B', '⚖️', v_ch5_id, 23, '/assets/kanji/n1/illustrations/chap5_intro.webp', NOW())
