    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('瞬', 'シュン', 'またた.いている, またた.く', 'matataiteiru', 'THUẤN', 'ngôi sao lấp lánh, thời gian trôi qua trong nháy mắt', 14, '目 -> 瞬', '目', '星が瞬いている (ほしがまたたいている: ngôi sao lấp lánh)、瞬く間に時間が経つ (またたくまにじかんがたつ: thời gian trôi qua trong nháy mắt)、一瞬の出来事 (いっしゅんのできごと: việc có thể làm được trong chốc lát)、瞬間 (しゅんかん: khoảnh khắc)', '星が瞬いている（ほしがまたたいている）', 'hoshigamatataiteiru', 'ngôi sao lấp lánh', 'N1', 'Chiết tự Hán Việt: THUẤN (瞬)', 'thời gian trôi nhanh THUẤN nháy mắt 3 lần đã đến chiều tối cuối năm', '⚖️', v_ch5_id, 26, '/assets/kanji/n1/illustrations/chap5_intro.webp', NOW())
