    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('疎', 'ソ', 'うと.まれる, うと.ましい', 'utomareru', 'SƠ', 'bị cấp trên thờ ơ, khó chịu', 14, '糸 -> 疎', '糸', '上司に疎まれる (じょうしにうとまれる: bị cấp trên thờ ơ, bỏ mặc)、疎ましい (うとましい: khó chịu)、疎い (うとい: qua loa, sơ sài)、過疎の村 (かそのむら: ngôi làng dân cư thưa thớt)', '上司に疎まれる（じょうしにうとまれる）', 'joushiniutomareru', 'bị cấp trên thờ ơ, bỏ mặc', 'N1', 'Chiết tự Hán Việt: SƠ (疎)', 'Chỉ bó buộc dừng lại ở mức SƠ sài', '⚖️', v_ch5_id, 34, '/assets/kanji/n1/illustrations/chap5_intro.webp', NOW())
