    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('偏', 'ヘン', 'かたよ.っている, かたよ.らないよう', 'katayotteiru', 'THIÊN', 'suy nghĩ lệch lạc, đảm bảo không bị thiếu dinh dưỡng', 14, '門 -> 亻', '門', '考えは偏っている (かんがえはかたよっている: suy nghĩ lệch lạc)、栄養が偏らないようにする (えいようがかたよらないようにする: đảm bảo không bị thiếu dinh dưỡng)、偏見を持つ (へんけんをもつ: có thành kiến)、知識偏重 (ちしきへんちょう: coi trọng kiến thức)', '考えは偏っている（かんがえはかたよっている）', 'kangaehakatayotteiru', 'suy nghĩ lệch lạc', 'N1', 'Chiết tự Hán Việt: THIÊN (偏)', 'Người có THIÊN hướng bày sách ngoài cửa', '⚖️', v_ch5_id, 39, '/assets/kanji/n1/illustrations/chap5_intro.webp', NOW())
