    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('憤', 'フン', 'いきどお.る', 'ikidooru', 'PHẪN', 'phẫn nộ, thái độ căm phẫn', 17, '金 -> 忄 -> 貝', '金', '憤る (いきどおる: phẫn nộ, tức giận)、憤然とした態度 (ふんぜんとしたたいど: thái độ căm phẫn, giận dữ)', '憤る（いきどおる）', 'ikidooru', 'phẫn nộ, tức giận', 'N1', 'Chiết tự Hán Việt: PHẪN (憤)', 'Tâm(忄) PHẪN uất (憤) vì mất tiền (貝) cho 10 (十） ngọn cỏ (艹)', '💭', v_ch6_id, 11, '/assets/kanji/n1/illustrations/chap6_intro.webp', NOW())
