    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('剛', 'ゴウ', 'つよし', 'tsuyoshi', 'CƯƠNG', 'hành động dũng cảm, gia đình có truyền thống bình dị', 14, '刂 -> 木', '刂', '剛胆な振る舞い (ごうたんなふるまい: hành động dũng cảm)、質実剛健な家風 (しつじつごうけんなかふう: gia đình có truyền thống bình dị)、柔よく剛を制す (じゅうよくつよしをせいす: lây nhu thắng cương, lạt mềm buộc chặt)', '剛胆な振る舞い（ごうたんなふるまい）', 'goutannafurumai', 'hành động dũng cảm', 'N1', 'Chiết tự Hán Việt: CƯƠNG (剛)', 'CƯƠNG cứng như cây đao', '💭', v_ch6_id, 15, '/assets/kanji/n1/illustrations/chap6_intro.webp', NOW())
