    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('敢', 'カン', '', 'kan', 'CẢM', 'dám nói những điều khó nói, dũng cảm', 17, '亻 -> 工 -> 攵', '亻', '言いにくいことを敢えて言う (いいにくいことを敢えていう: dám nói những điều khó nói)、勇敢な (ゆうかんな: dũng cảm)、果敢 (かかん: dũng cảm gan dạ)、敢然と戦う (かんぜんとたたかう: chiến đấu anh dũng)', '言いにくいことを敢えて言う（いいにくいことを敢えていう）', 'iinikuikotoo敢eteiu', 'dám nói những điều khó nói', 'N1', 'Chiết tự Hán Việt: CẢM (敢)', 'Người làm Công (工) bị Đánh (攵) vào Tai (耳) thì sẽ dũng CẢM đứng lên', '💭', v_ch6_id, 16, '/assets/kanji/n1/illustrations/chap6_intro.webp', NOW())
