    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('敏', 'ビン', '', 'bin', 'MẪN', 'hành động nhanh nhẹn, thông minh sắc sảo', 14, '一 -> 敏', '敏', '機敏に行動する (きびんにこうどうする: hành động nhanh nhẹn)、俊敏な (しゅんびんな: thông minh sắc sảo, nhanh nhẹn)、敏捷性 (びんしょうせい: nhanh nhẹn, lanh lợi)、敏腕な弁護士 (びんわんなべんごし: luật sư nhạy bén, khéo léo)', '機敏に行動する（きびんにこうどうする）', 'kibinnikoudousuru', 'hành động nhanh nhẹn', 'N1', 'Chiết tự Hán Việt: MẪN (敏)', 'MẪN cảm với việc đánh nhau mỗi ngày', '💭', v_ch6_id, 18, '/assets/kanji/n1/illustrations/chap6_intro.webp', NOW())
