    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('粗', 'アラ, ア', 'あら.い', 'arai', 'THÔ', 'công việc thô sơ, kể lại tóm tắt tiểu thuyết', 14, '禾 -> 粗', '禾', '仕事が粗い (しごとがあらい: công việc thô sơ)、小説の粗筋 (しょうせつのあらすじ: kể lại tóm tắt tiểu thuyết)、粗探しをする (あらさがしをする: soi mói, bắt lỗi)、粗挽き (あらびき: băm nhỏ, xay, nghiền)', '仕事が粗い（しごとがあらい）', 'shigotogaarai', 'công việc thô sơ', 'N1', 'Chiết tự Hán Việt: THÔ (粗)', 'Gạo mà xếp thành 3 tầng thật là THÔ thiển', '💭', v_ch6_id, 23, '/assets/kanji/n1/illustrations/chap6_intro.webp', NOW())
