    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('懐', 'コノ', 'なず.く, なつ.ける', 'nazuku', 'HOÀI', 'đứa trẻ than thiết với bà, thuần phục chú chó', 17, '衤 -> 目 -> 忄', '衤', 'この子は祖母に懐く (このこはそぼになずく: đứa trẻ than thiết với bà)、飼い犬を懐ける (かいいぬをなつける: thuần phục chú chó)、昔を懐かしむ (むかしをなつかしむ: hoài niệm về ngày xưa ấy)、子供の頃が懐かしい (こどものころがなつかしい: nhớ về tuổi thơ)', 'この子は祖母に懐く（このこはそぼになずく）', 'konokohasoboninazuku', 'đứa trẻ than thiết với bà', 'N1', 'Chiết tự Hán Việt: HOÀI (懐)', '10 con mắt trái tim HOÀI niệm về bộ y phục', '💭', v_ch6_id, 25, '/assets/kanji/n1/illustrations/chap6_intro.webp', NOW())
