    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('恨', 'ラ, コン', 'うら.む, うら.み', 'uramu', 'HẬN', 'căm ghét, không nhớ đã gay thù chuốc oán với ai', 17, '亻 -> 忄 -> 艮', '亻', '恨む (うらむ: căm ghét)、恨みを買う覚えはない (うらみをかうおぼえはない: không nhớ đã gay thù chuốc oán với ai)、恨めしい (うらめしい: căm ghét)、逆恨みする (さかうらみする: trả đũa)', '恨む（うらむ）', 'uramu', 'căm ghét', 'N1', 'Chiết tự Hán Việt: HẬN (恨)', 'HẬN 恨 là trong TIM(忄) còn cấn (艮) nỗi đau vì bị người khác trở mặt', '💭', v_ch6_id, 29, '/assets/kanji/n1/illustrations/chap6_intro.webp', NOW())
