    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('芽', 'ツガ, ガ', 'め', 'me', 'NHA', 'cây nảy mầm, mùa cây cối đâm chồi nảy lộc', 17, '食 -> 艹 -> 牙', '食', '木の芽が出る (きのめがでる: cây nảy mầm)、木木が芽吹く季節 (木木がめぶくきせつ: mùa cây cối đâm chồi nảy lộc)、恋が芽生える (こいがめばえる: nảy sinh tình cảm)、種が発芽する (しゅがはつがする: hạt giống nảy mầm)', '木の芽が出る（きのめがでる）', 'kinomegaderu', 'cây nảy mầm', 'N1', 'Chiết tự Hán Việt: NHA (芽)', 'Cô giáo thảo ( 艹) vừa ăn NHA đam (牙) vừa cầm ô', '🌿', v_ch7_id, 3, '/assets/kanji/n1/illustrations/chap7_intro.webp', NOW())
