    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('樹', 'ジュ', '', 'ju', 'THỤ', 'cây cối, cây bên lề đường', 17, '木 -> 村 -> 十', '木', '樹木 (じゅもく: cây cối)、街路樹 (がいろじゅ: cây bên lề đường)、果樹園 (かじゅえん: vườn cây ăn quả)、樹氷 (じゅひょう: cây cối phủ băng)', '樹木（じゅもく）', 'jumoku', 'cây cối', 'N1', 'Chiết tự Hán Việt: THỤ (樹)', 'ở giữa ngôi làng (村) có 10 (十) cây đậu (豆) cổ THỤ', '🌿', v_ch7_id, 8, '/assets/kanji/n1/illustrations/chap7_intro.webp', NOW())
