    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('獲', 'エ, カク', 'え.る', 'eru', 'HOẠCH', 'bắt cá, con mồi', 17, '鳥 -> 艹 -> 金', '鳥', '魚を獲る (さかなをえる: bắt cá)、獲物 (えもの: con mồi)、捕獲する (ほかくする: bắt được)、乱獲を禁止する (らんかくをきんしする: cấm săn bắt bừa bãi)', '魚を獲る（さかなをえる）', 'sakanaoeru', 'bắt cá', 'N1', 'Chiết tự Hán Việt: HOẠCH (獲)', 'Con chó đuổi bắt con chim trên đồng cỏ', '🌿', v_ch7_id, 9, '/assets/kanji/n1/illustrations/chap7_intro.webp', NOW())
