    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('尾', 'ビ', 'お', 'o', 'VĨ', 'đuôi của động vật, ảnh hưởng vẫn còn tiếp diễn', 14, '門 -> 尾', '門', '動物の尾 (どうぶつのお: đuôi của động vật)、尾を引く (おをひく: ảnh hưởng vẫn còn tiếp diễn)、尾根伝いに歩く (おねづたいにあるく: đi bộ dọc theo sườn núi)、犯人を尾行する (はんにんをびこうする: thoe dõi tên tội phạm)', '動物の尾（どうぶつのお）', 'doubutsunoo', 'đuôi của động vật', 'N1', 'Chiết tự Hán Việt: VĨ (尾)', 'Có cái Lông VĨ đại mọc ở gần cửa hậu là cái ĐUÔI', '🌿', v_ch7_id, 10, '/assets/kanji/n1/illustrations/chap7_intro.webp', NOW())
