    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('雄', 'ユウ', 'おす, お.しべ', 'osu', 'HÙNG', 'chó đực, nhị hoa', 14, '隹 -> 雄', '隹', '雄の犬 (おすのいぬ: chó đực)、雄しべ (おしべ: nhị hoa)、雄大な富士山の姿 (ゆうだいなふじさんのすがた: diện mạo nguy nga tráng lệ của núi phú sĩ)、英雄 (えいゆう: anh hùng)', '雄の犬（おすのいぬ）', 'osunoinu', 'chó đực', 'N1', 'Chiết tự Hán Việt: HÙNG (雄)', 'NAM(ナム） nhi có CHYM（隹） giống đực là anh HÙNG', '🌿', v_ch7_id, 11, '/assets/kanji/n1/illustrations/chap7_intro.webp', NOW())
