    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('滅', 'メツ', 'ほろ.びる, ほろ.ぼす', 'horobiru', 'DIỆT', 'nền văn minh bị phá hủy, tiêu diệt kẻ thù', 14, '灬 -> 氵', '灬', '文明が滅びる (ぶんめいがほろびる: nền văn minh bị phá hủy)、敵を滅ぼす (てきをほろぼす: tiêu diệt kẻ thù)、人類が滅亡する (じんるいがめつぼうする: loài người diệt vong)、絶滅する (ぜつめつする: tuyệt chủng)', '文明が滅びる（ぶんめいがほろびる）', 'bunmeigahorobiru', 'nền văn minh bị phá hủy', 'N1', 'Chiết tự Hán Việt: DIỆT (滅)', 'một ngọn lửa nhỏ mà chiến đấu với dòng nước lớn thì sẽ thành DIỆT vong', '🌿', v_ch7_id, 13, '/assets/kanji/n1/illustrations/chap7_intro.webp', NOW())
