    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('獣', 'ケモ, ジュウ', 'けもの', 'kemono', 'THÚ', 'con thú, đường mòn', 17, '犭 -> 艹 -> 金', '犭', '獣 (けもの: con thú)、獣道 (けものみち: đường mòn)、猛獣 (もうじゅう: mãnh thú, thú dữ)、獣医 (じゅうい: bác sĩ thú y)', '獣（けもの）', 'kemono', 'con thú', 'N1', 'Chiết tự Hán Việt: THÚ (獣)', 'Dùng 10 con chó để săn THÚ ăn cỏ ở ngoài đồng', '🌿', v_ch7_id, 14, '/assets/kanji/n1/illustrations/chap7_intro.webp', NOW())
