    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('亜', 'アリ', '', 'ari', 'Á', 'khí hậu cận nhiệt đới, bắt chước', 14, '氵 -> 中', '氵', '亜熱帯気候 (あねったいきこう: khí hậu cận nhiệt đới)、亜流 (ありゅう: bắt chước, học lỏm)、亜細亜 (あじあ: Châu Á)', '亜熱帯気候（あねったいきこう）', 'anettaikikou', 'khí hậu cận nhiệt đới', 'N1', 'Chiết tự Hán Việt: Á (亜)', 'Hai nước Trung (中) quốc có diện tích bằng cả châu Á', '🌿', v_ch7_id, 19, '/assets/kanji/n1/illustrations/chap7_intro.webp', NOW())
