    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('鉛', 'ナマ, エン', 'なまり', 'namari', 'DUYÊN', 'chì, bầu trời xám xịt', 17, '金 -> 八 -> 口', '金', '鉛 (なまり: chì)、鉛色の空 (なまりいろのそら: bầu trời xám xịt)、鉛筆 (えんぴつ: bút chì)、亜鉛 (あえん: kẽm)', '鉛（なまり）', 'namari', 'chì', 'N1', 'Chiết tự Hán Việt: DUYÊN (鉛)', 'cho dù là vàng (金) mà qua tám (八) cái miệng (口) thì cũng thành chì (鉛)', '🌿', v_ch7_id, 20, '/assets/kanji/n1/illustrations/chap7_intro.webp', NOW())
