    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('晶', 'ショウ', '', 'shou', 'TINH', 'bông tuyết, kết tinh của sự nỗ lực', 14, '一 -> 晶', '晶', '雪の結晶 (ゆきのけっしょう: bông tuyết)、努力の結晶 (どりょくのけっしょう: kết tinh của sự nỗ lực)、水晶 (すいしょう: quả cầu pha lê)', '雪の結晶（ゆきのけっしょう）', 'yukinokesshou', 'bông tuyết', 'N1', 'Chiết tự Hán Việt: TINH (晶)', '3 mặt trời kết TINH thành thuỷ TINH trong suốt', '🌿', v_ch7_id, 24, '/assets/kanji/n1/illustrations/chap7_intro.webp', NOW())
