    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('浦', 'ウラ, ノウラ', '', 'ura', 'PHỔ', 'mở rộng ở khắp mọi nơi mọi chỗ, sóng biển gần bờ', 17, '糸 -> 氵 -> 用', '糸', '津津浦浦に広まる (つつうらうらにひろまる: mở rộng ở khắp mọi nơi mọi chỗ)、浦波 (うらなみ: sóng biển gần bờ)、海浦 (うみのうら: bờ biển)', '津津浦浦に広まる（つつうらうらにひろまる）', 'tsutsuurauranihiromaru', 'mở rộng ở khắp mọi nơi mọi chỗ', 'N1', 'Chiết tự Hán Việt: PHỔ (浦)', 'Thủy ( 氵) đc PHỔ biến rằng, bờ sông này mỗi người chỉ đc sử Dụng (用) 10 (十) lần', '🌿', v_ch7_id, 26, '/assets/kanji/n1/illustrations/chap7_intro.webp', NOW())
