    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('沿', 'エン', 'そ.う', 'sou', 'DUYÊN', 'men thưo con sông, tuân theo phương châm của công ty', 17, '言 -> 口 -> 氵', '言', '川に沿う (川にそう: men thưo con sông)、会社の方針に沿う (会社の方針にそう: tuân theo phương châm của công ty)、沿岸 (えんがん: bãi biển)、電車の沿線 (電車のえんせん: dọc tuyén đường tàu)', '川に沿う（川にそう）', '川nisou', 'men thưo con sông', 'N1', 'Chiết tự Hán Việt: DUYÊN (沿)', 'TÁM cái Miệng nói chuyện bắn NƯỚC tung toé rất vô DUYÊN', '🌿', v_ch7_id, 27, '/assets/kanji/n1/illustrations/chap7_intro.webp', NOW())
