    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('溝', 'コウ', 'みぞ', 'mizo', 'CÂU', 'đào rãnh, rãnh', 14, '氵 -> 溝', '氵', '溝を掘る (みぞをほる: đào rãnh, đào mương)、溝 みぞ (みぞ みぞ: rãnh)、排水溝 (はいすいこう: cống thải)、海溝 (かいこう: rãnh đại dương)', '溝を掘る（みぞをほる）', 'mizoohoru', 'đào rãnh, đào mương', 'N1', 'Chiết tự Hán Việt: CÂU (溝)', 'Cấu đi CÂU ở CỐNG nước', '🌿', v_ch7_id, 28, '/assets/kanji/n1/illustrations/chap7_intro.webp', NOW())
