    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('漂', 'ヒョウ', 'ただよ.う', 'tadayou', 'PHIÊU', 'con thuyền nhỏ trôi nổi trên mặt biển, tỏa ra', 17, '艹 -> 票 -> 氵', '艹', '海面に漂う小舟 (かいめんにただようこぶね: con thuyền nhỏ trôi nổi trên mặt biển)、穏やかな雰囲気が漂う (おだやかなふんいきがただよう: tỏa ra, tràn ngập bầu không khí hòa nhã)、漂着する (ひょうちゃくする: dạt vào)、漂流船 (ひょうりゅうせん: con thuyền trôi dạt)', '海面に漂う小舟（かいめんにただようこぶね）', 'kaimennitadayoukobune', 'con thuyền nhỏ trôi nổi trên mặt biển', 'N1', 'Chiết tự Hán Việt: PHIÊU (漂)', 'Lá phiếu (票) trôi nổi (漂) trên mặt nước (氵)', '🌿', v_ch7_id, 29, '/assets/kanji/n1/illustrations/chap7_intro.webp', NOW())
