    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('濁', 'ダク', 'にご.る, にご.す', 'nigoru', 'TRỌC, TRẠC', 'nước sông đục, đánh trống lảng', 17, '木 -> 氵 -> 目', '木', '水が濁る (水がにごる: nước sông đục)、お茶を濁す (おちゃをにごす: đánh trống lảng)、立つ鳥跡を濁さず (たつとりあとをにごさず: Giống như chim, đi ko để lại dấu vết. ( ko để lại tiếng xấu))、濁流にのまれる (だくりゅうにのまれる: bị cuốn trôi trong nước lũ)', '水が濁る（水がにごる）', '水ganigoru', 'nước sông đục', 'N1', 'Chiết tự Hán Việt: TRỌC, TRẠC (濁)', 'nước 氵từ gỗ mục 目 chảy ra chứa bao 勹 nhiêu côn trùng 虫 gọi là nước đục 濁', '🌿', v_ch7_id, 31, '/assets/kanji/n1/illustrations/chap7_intro.webp', NOW())
