    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('鳩', 'キュウ', 'はと', 'hato', 'CƯU', 'cho bồ câu ăn, đồng hồ cúc cu', 14, '鳥 -> 鳩', '鳥', '鳩に餌をやる (はとにえさをやる: cho bồ câu ăn)、鳩時計 (はとどけい: đồng hồ cúc cu)、伝書鳩 (でんしょばと: bồ câu đưa thư)、鳩舎 (きゅうしゃ: chuồng chim bồ câu)', '鳩に餌をやる（はとにえさをやる）', 'hatoniesaoyaru', 'cho bồ câu ăn', 'N1', 'Chiết tự Hán Việt: CƯU (鳩)', 'Con chim bồ câu thể hiện tình yêu vĩnh cửu nên thường được treo trong đám cưới', '🦅', v_ch8_id, 10, '/assets/kanji/n1/illustrations/chap8_intro.webp', NOW())
