    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('鶴', 'ツル', 'つる', 'tsuru', 'HẠC', 'câu chúc “sống lâu trăm tuổi”, gấp 1 nghìn con hạc giấy', 17, '亻 -> 隹 -> 鳥', '亻', '鶴は千年、亀は万年 (つるはせんねん、かめはまんねん: câu chúc “sống lâu trăm tuổi”)、千羽鶴を折る (せんばづるをおる: gấp 1 nghìn con hạc giấy)', '鶴は千年、亀は万年（つるはせんねん、かめはまんねん）', 'tsuruhasennenkamehamannen', 'câu chúc “sống lâu trăm tuổi”', 'N1', 'Chiết tự Hán Việt: HẠC (鶴)', 'Ngày xưa người ta gọi chim (隹) điểu (鳥) là con HẠC (鶴)', '🦅', v_ch8_id, 13, '/assets/kanji/n1/illustrations/chap8_intro.webp', NOW())
