    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('猿', 'エン', 'さる', 'saru', 'VIÊN', 'con khỉ, nhân vô thập toàn “ai cũng có lúc mắc sai lầm”', 14, '袁 -> 犭', '袁', '猿 (さる: con khỉ)、猿も木から落ちる (さるもきからおちる: nhân vô thập toàn “ai cũng có lúc mắc sai lầm”)、類人猿 (るいじんえん: vượn người)、A さんとB さんは犬猿の仲 (A さんとB さんはけんえんのなか: anh A và B như chó với mèo)', '猿（さる）', 'saru', 'con khỉ', 'N1', 'Chiết tự Hán Việt: VIÊN (猿)', 'Công VIÊN (袁) có nuôi con khỉ (vượn) (猿) đầu chó (犭)', '🦅', v_ch8_id, 17, '/assets/kanji/n1/illustrations/chap8_intro.webp', NOW())
