    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('狼', 'ロウ', 'おおかみ', 'ookami', 'LANG', 'chó sói, đơn độc một mình', 14, '犭 -> 狼', '犭', '狼 (おおかみ: chó sói)、一匹狼 (いっぴきおおかみ: đơn độc một mình)、狼狽する (ろうばいする: lạc lối hoảng loạn)', '狼（おおかみ）', 'ookami', 'chó sói', 'N1', 'Chiết tự Hán Việt: LANG (狼)', 'Chó Lương thiện thì sẽ không đi LANG thang như chó sói', '🦅', v_ch8_id, 18, '/assets/kanji/n1/illustrations/chap8_intro.webp', NOW())
