    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('猪', 'チ, イノシ', 'いのしし', 'inoshishi', 'TRƯ', 'lợn rừng, liều lĩnh xông pha hết sức trẻ', 17, '木 -> 犭 -> 者', '木', '猪 (いのしし: lợn rừng)、若さにまかせて猪突猛進する (わかさにまかせてちょとつもうしんする: liều lĩnh xông pha hết sức trẻ)、お猪口 (おちょこ: chén rượu nhỏ)、猪首の男 (いのししくびのおとこ: người đàn ông cứng đầu)', '猪（いのしし）', 'inoshishi', 'lợn rừng', 'N1', 'Chiết tự Hán Việt: TRƯ (猪)', 'Con chó(犭) và người(者) đi săn heo Rừng (TRƯ 猪)', '🦅', v_ch8_id, 19, '/assets/kanji/n1/illustrations/chap8_intro.webp', NOW())
