    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('熊', 'ク', 'くま', 'kuma', 'HÙNG', 'con gấu xuất hiện, gom lá rơi bằng cái cào', 14, '力 -> 熊', '力', '熊が出没する (くまがしゅつぼつする: con gấu xuất hiện)、熊手で落ち葉を集める (くまででおちばをあつめる: gom lá rơi bằng cái cào)', '熊が出没する（くまがしゅつぼつする）', 'kumagashutsubotsusuru', 'con gấu xuất hiện', 'N1', 'Chiết tự Hán Việt: HÙNG (熊)', 'Anh HÙNG cứu Hoả phải có Năng lực bắt GẤU', '🦅', v_ch8_id, 20, '/assets/kanji/n1/illustrations/chap8_intro.webp', NOW())
