    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('巡', 'ジュン', 'めぐ.る, めぐ.り', 'meguru', 'TUẦN', 'đi dạo quanh, tình cờ gặp được người định mệnh của đời mình', 14, '氵 -> 巡', '氵', '巡る (めぐる: đi dạo quanh)、運命の人に巡り合う (うんめいのひとにめぐりあう: tình cờ gặp được người định mệnh của đời mình)、町を巡回する (まちをじゅんかいする: đi vòng quanh thành phố)', '巡る（めぐる）', 'meguru', 'đi dạo quanh', 'N1', 'Chiết tự Hán Việt: TUẦN (巡)', 'Đi lại dọc bờ sông TUẦN tra', '💼', v_ch9_id, 4, '/assets/kanji/n1/illustrations/chap9_intro.webp', NOW())
