    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('稲', 'イナ', 'いね', 'ine', 'ĐẠO', 'gặt lúa, nông dân trồng lúa', 14, '禾 -> 稲', '禾', '稲を刈る (いねをかる: gặt lúa)、稲作農家 (いなさくのうか: nông dân trồng lúa)、稲妻が走る (いなずまがはしる: tia chớp xẹt qua)、水稲耕作 (すいとうこうさく: canh tác lúa nước)', '稲を刈る（いねをかる）', 'ineokaru', 'gặt lúa', 'N1', 'Chiết tự Hán Việt: ĐẠO (稲)', 'lúa gặt một ngày có thể nhận đc gạo', '💼', v_ch9_id, 10, '/assets/kanji/n1/illustrations/chap9_intro.webp', NOW())
