    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('穂', 'ナホ, ホ', 'ほ', 'ho', 'TUỆ', 'trổ bông, bông lúa mì', 14, '禾 -> 亻', '禾', '穂が出る (ほがでる: trổ bông)、麦の穂 (むぎのほ: bông lúa mì)、稲穂 (いなほ: bông lúa)、筆の穂先 (ふでのほさき: ngòi bút lông)', '穂が出る（ほがでる）', 'hogaderu', 'trổ bông', 'N1', 'Chiết tự Hán Việt: TUỆ (穂)', 'Bông LÚA là ân HUỆ mà trí TUỆ con người tạo ra', '💼', v_ch9_id, 11, '/assets/kanji/n1/illustrations/chap9_intro.webp', NOW())
