    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('耕', 'タハ', 'たがや.す', 'tagayasu', 'CANH', 'cày cấy ruộng nương, dân tộc làm ruộng', 14, '田 -> 氵', '田', '田畑を耕す (たはたをたがやす: cày cấy ruộng nương)、農耕民族 (のうこうみんぞく: dân tộc làm ruộng)、晴耕雨読 (せいこううどく: “cuộc sông ung dung tự tại)', '田畑を耕す（たはたをたがやす）', 'tahataotagayasu', 'cày cấy ruộng nương', 'N1', 'Chiết tự Hán Việt: CANH (耕)', 'CANH tác ruộng cần có cày và nước giếng', '💼', v_ch9_id, 12, '/assets/kanji/n1/illustrations/chap9_intro.webp', NOW())
