    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('穫', 'カク', '', 'kaku', 'HOẠCH', 'thu hoạch, sản lượng thu hoạch', 17, '禾 -> 鳥 -> 艹', '禾', '収穫する (しゅうかくする: thu hoạch)、収穫量 (しゅうかくりょう: sản lượng thu hoạch)、収穫を得る (しゅうかくをえる: lĩnh hội, gặt hái được)', '収穫する（しゅうかくする）', 'shuukakusuru', 'thu hoạch', 'N1', 'Chiết tự Hán Việt: HOẠCH (穫)', 'đến mùa thu HOẠCH lúa lại thấy chim thảo bay về', '💼', v_ch9_id, 13, '/assets/kanji/n1/illustrations/chap9_intro.webp', NOW())
