    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('培', 'バイ', 'つちか.う', 'tsuchikau', 'BỒI', 'vun đắp tình bạn, trồng trọt', 14, '土 -> 培', '土', '友情を培う (ゆうじょうをつちかう: vun đắp tình bạn)、栽培する (さいばいする: trồng trọt)、細菌を培養する (さいきんをばいようする: nuôi cấy vi khuẩn)', '友情を培う（ゆうじょうをつちかう）', 'yuujouotsuchikau', 'vun đắp tình bạn', 'N1', 'Chiết tự Hán Việt: BỒI (培)', 'BỒI đất lên gấp bội', '💼', v_ch9_id, 16, '/assets/kanji/n1/illustrations/chap9_intro.webp', NOW())
