    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('渉', 'ショウ', '', 'shou', 'THIỆP', 'đàm phán thành công, can thiệp', 14, '一 -> 渉', '渉', '交渉がまとまる (こうしょうがまとまる: đàm phán thành công)、他人に干渉する (たにんにかんしょうする: can thiệp, xen vào việc người khác)、渉外担当 (しょうがいたんとう: phụ trách liên lạc với bên ngoài)', '交渉がまとまる（こうしょうがまとまる）', 'koushougamatomaru', 'đàm phán thành công', 'N1', 'Chiết tự Hán Việt: THIỆP (渉)', 'Thuỷ đi Bộ lên đưa THIỆP mời', '💼', v_ch9_id, 17, '/assets/kanji/n1/illustrations/chap9_intro.webp', NOW())
