    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('提', 'テイ', 'さ.げる', 'sageru', 'ĐỀ', 'vác cặp từ trên vai, nộp', 14, '扌 -> 提', '扌', '鞄を肩から提げる (かばんをかたからさげる: vác cặp từ trên vai)、提出する (ていしゅつする: nộp)、提案する (ていあんする: đưa ra đề án chính sách)、前提 (ぜんてい: tiền đề)', '鞄を肩から提げる（かばんをかたからさげる）', 'kabanokatakarasageru', 'vác cặp từ trên vai', 'N1', 'Chiết tự Hán Việt: ĐỀ (提)', 'Chạy một ngày để đến dơ tay ĐỀ cử', '💼', v_ch9_id, 18, '/assets/kanji/n1/illustrations/chap9_intro.webp', NOW())
