    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('摘', 'テキ', 'つ.む', 'tsumu', 'TRÍCH', 'hái hoa, chỉ ra điểm chính của vấn đề', 17, '酉 -> 糸 -> 扌', '酉', '花を摘む (はなをつむ: hái hoa)、問題点を指摘する (もんだいてんをしてきする: chỉ ra điểm chính của vấn đề)、脱税を摘発する (だつぜいをてきはつする: vạch trần việc trốn thuế)、がんの摘出手術 (がんのてきしゅつしゅじゅつ: phẫu thuật loại bỏ ung thư)', '花を摘む（はなをつむ）', 'hanaotsumu', 'hái hoa', 'N1', 'Chiết tự Hán Việt: TRÍCH (摘)', 'Tay nắm chặt bình rượu cũ nên bị chỉ TRÍCH', '💼', v_ch9_id, 19, '/assets/kanji/n1/illustrations/chap9_intro.webp', NOW())
