    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('請', 'セイ, シン', 'こ.う, う.ける', 'kou', 'THỈNH', 'xin tha thứ, thi công xây dựng', 17, '足 -> 言 -> 青', '足', '許しを請う (ゆるしをこう: xin tha thứ)、工事を請ける (こうじをうける: thi công xây dựng)、仕事を請け負う (しごとを請けおう: đảm nhận công việc)、請求する (せいきゅうする: yêu cầu)', '許しを請う（ゆるしをこう）', 'yurushiokou', 'xin tha thứ', 'N1', 'Chiết tự Hán Việt: THỈNH (請)', 'muốn THỈNH cầu 請 ai đó .phát NGÔN 言 phải chân thành giọng phải THANH 青 nhé', '💼', v_ch9_id, 24, '/assets/kanji/n1/illustrations/chap9_intro.webp', NOW())
