    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('派', 'ハ, パ', '', 'ha', 'PHÁI', 'phe phái, đảng phái', 14, '亻 -> 氵', '亻', '派閥 (はばつ: phe phái, bè phái)、党派 (とうは: đảng phái)、特派員 (とくはいん: đặc phái viên)、立派な行い (りっぱなおこない: hành động tuyệt vời)', '派閥（はばつ）', 'habatsu', 'phe phái, bè phái', 'N1', 'Chiết tự Hán Việt: PHÁI (派)', 'PHÁI ba người đi tưới nước', '💼', v_ch9_id, 25, '/assets/kanji/n1/illustrations/chap9_intro.webp', NOW())
