    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('遣', 'ヅカ, ケン', 'つか.う, つか.わす', 'tsukau', 'KHIỂN', 'quan tâm, phung phí', 14, '辶 -> 中', '辶', '気を遣う (きをつかう: quan tâm, chú ý)、金遣いが荒い (かねづかいがあらい: phung phí)、使者を遣わす (ししゃをつかわす: cử xứ giả)、大使を派遣する (たいしをはけんする: phái đại sứ)', '気を遣う（きをつかう）', 'kiotsukau', 'quan tâm, chú ý', 'N1', 'Chiết tự Hán Việt: KHIỂN (遣)', 'Ông quan được cử đi khảo sát bên trong 中 của mộtー con đường', '💼', v_ch9_id, 26, '/assets/kanji/n1/illustrations/chap9_intro.webp', NOW())
