    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('軌', 'キ', '', 'ki', 'QUỸ', 'vệ tinh nhân tạo đi vào quỹ đạo, đi theo quỹ đạo', 14, '車 -> 九', '車', '人工衛星が軌道に乗る (じんこうえいせいがきどうにのる: vệ tinh nhân tạo đi vào quỹ đạo)、軌跡をたどる (きせきをたどる: đi theo quỹ đạo)、常軌を逸した (じょうきをいっした: khác thường)', '人工衛星が軌道に乗る（じんこうえいせいがきどうにのる）', 'jinkoueiseigakidouninoru', 'vệ tinh nhân tạo đi vào quỹ đạo', 'N1', 'Chiết tự Hán Việt: QUỸ (軌)', 'XE (車) chạy 9 (九) vòng QUỸ (軌) đạo', '💼', v_ch9_id, 31, '/assets/kanji/n1/illustrations/chap9_intro.webp', NOW())
