    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('還', 'カン', '', 'kan', 'HOÀN', 'sống sót một cách an toàn, trả lại', 14, '車 -> 目', '車', '無事に生還する (ぶじにせいかんする: sống sót một cách an toàn)、変換する (へんかんする: trả lại)、還元する (かんげんする: hoàn trả lại)、密航者を強制送還する (みっこうしゃをきょうせいそうかんする: trục xuất những người đi tàu vé lậu)', '無事に生還する（ぶじにせいかんする）', 'bujiniseikansuru', 'sống sót một cách an toàn', 'N1', 'Chiết tự Hán Việt: HOÀN (還)', 'Đi đường xa xôi để HOÀN trả lại 3 mắt', '💼', v_ch9_id, 32, '/assets/kanji/n1/illustrations/chap9_intro.webp', NOW())
