    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('遇', 'グウ', '', 'guu', 'NGỘ', 'đãi ngộ, cảnh ngộ', 14, '一 -> 遇', '遇', '待遇 (たいぐう: đãi ngộ)、境遇 (きょうぐう: cảnh ngộ, hoàn cảnh)、奇遇 (きぐう: kỳ ngộ, trùng hợp)、経験者優遇 (けいけんしゃゆうぐう: ưu tiên người có kinh nghiệm)', '待遇（たいぐう）', 'taiguu', 'đãi ngộ', 'N1', 'Chiết tự Hán Việt: NGỘ (遇)', 'Đi ra đường mới NGỘ ra cái ngu của mình', '💼', v_ch9_id, 33, '/assets/kanji/n1/illustrations/chap9_intro.webp', NOW())
