    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('障', 'ザワ, ョウ', 'さわ.る, さわ.り', 'sawaru', 'CHƯỚNG', 'làm việc quá nhiều có hại cho sức khỏe, xúc phạm', 14, '早 -> 立', '早', '働きすぎは体に障る (はたらきすぎはからだにさわる: làm việc quá nhiều có hại cho sức khỏe)、気に障る (きにさわる: xúc phạm, gây tổn thương)、耳障りな音 (みみざわりなおと: âm thanh chói tai, âm thanh khó chịu)、当たり障りのない言葉 (あたりさわりのないことば: lời nói vô hại)', '働きすぎは体に障る（はたらきすぎはからだにさわる）', 'hatarakisugihakaradanisawaru', 'làm việc quá nhiều có hại cho sức khỏe', 'N1', 'Chiết tự Hán Việt: CHƯỚNG (障)', 'Đến sớm 早 đứng 立 chờ nhưng gặp CHƯỚNG ngại vật là cái mông', '💼', v_ch9_id, 37, '/assets/kanji/n1/illustrations/chap9_intro.webp', NOW())
