    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('礎', 'ソ', 'いしずえ', 'ishizue', 'SỞ', 'Đá tảng kê cột, nền tảng', 18, '石 -> 楚', '石', '基礎 (きそ: cơ sở, nền tảng)、礎 (いしずえ: viên đá tảng)、定礎 (ていそ: đặt đá móng)', '基礎からしっかり勉強する（きそからしっかりべんきょうする）', 'Kiso kara shikkari benkyousuru', 'Học tập vững chắc ngay từ nền tảng cơ bản', 'N1', 'Chiết tự Hán Việt: SỞ (礎)', 'Tảng đá (石) đặt dưới rừng cây (林) làm nền móng vững chãi (SỞ).', '🎓', v_ch10_id, 1, '/assets/kanji/n1/illustrations/chap10_intro.webp', NOW())
