    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('範', 'ハン', '', 'han', 'PHẠM', 'mô hình, câu trả lời mẫu', 17, '竹 -> 糸 -> 木', '竹', '模範 (もはん: mô hình, kiểu mẫu)、模範解答 (もはんかいとう: câu trả lời mẫu)、社会の規範 (しゃかいのきはん: quy chuẩn của xã hội)、範囲 (はんい: phạm vi)', '模範（もはん）', 'mohan', 'mô hình, kiểu mẫu', 'N1', 'Chiết tự Hán Việt: PHẠM (範)', 'Ở rừng TRÚC Xe chỉ được chạy trong PHẠM VI cho phép', '🎓', v_ch10_id, 4, '/assets/kanji/n1/illustrations/chap10_intro.webp', NOW())
