    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('釈', 'シャク, シャ', '', 'shaku', 'THÍCH', 'giải thích, thêm chú thích', 14, '一 -> 釈', '釈', '解釈する (かいしゃくする: giải thích)、注釈を加える (ちゅうしゃくをくわえる: thêm chú thích)、釈明 (しゃくめい: thanh minh, giải thích)、被疑者を釈放する (ひぎしゃをしゃくほうする: thả tự do cho nghi phạm)', '解釈する（かいしゃくする）', 'kaishakusuru', 'giải thích', 'N1', 'Chiết tự Hán Việt: THÍCH (釈)', 'không cần phải giải THÍCH hay biện luận gì cả, hãy XÍCH hắn lại!', '🎓', v_ch10_id, 5, '/assets/kanji/n1/illustrations/chap10_intro.webp', NOW())
