    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('啓', 'ケイ', '', 'kei', 'KHẢI', 'mở mang (tri thức), tự trau dồi mở mang kiến thức', 17, '宀 -> 攵 -> 口', '宀', '啓発 (けいはつ: mở mang (tri thức))、自己啓発 (じこけいはつ: tự trau dồi mở mang kiến thức)、拝啓 (はいけい: kính gửi)、啓蒙書を読む (けいもうしょをよむ: sách vỡ lòng)', '啓発（けいはつ）', 'keihatsu', 'mở mang (tri thức)', 'N1', 'Chiết tự Hán Việt: KHẢI (啓)', 'vừa đánh(攵) vừa nói(口) mới khai sáng(KHẢI) được những kẻ không bao giờ ra khỏi cửa nhà(戸)', '🎓', v_ch10_id, 24, '/assets/kanji/n1/illustrations/chap10_intro.webp', NOW())
