    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('監', 'カン', '', 'kan', 'GIÁM', 'giám sát, kiểm toán', 17, '臣 -> 二 -> 皿', '臣', '監視する (かんしする: giám sát)、会計を監査する (かいけいをかんさする: kiểm toán)、監修する (かんしゅうする: kiểm duyệt)', '監視する（かんしする）', 'kanshisuru', 'giám sát', 'N1', 'Chiết tự Hán Việt: GIÁM (監)', 'Vị THẦN (臣) cầm HAI (二) cái ĐĨA (皿) GIÁM (監) sát cả thế gian', '🎓', v_ch10_id, 25, '/assets/kanji/n1/illustrations/chap10_intro.webp', NOW())
