    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('誠', 'セイ', 'まこと', 'makoto', 'THÀNH', 'sự tín nhiệm đã không còn kể từ lời nói dối, người thật thà trung thực', 17, '食 -> 言 -> 成', '食', '噓から出た誠 (うそからでたまこと: sự tín nhiệm đã không còn kể từ lời nói dối)、誠実な人 (せいじつなひと: người thật thà trung thực)、誠意ある対応 (せいいあるたいおう: phản ứng trung thực)、忠誠を誓う (ちゅうせいをちかう: thề trung thành với...)', '噓から出た誠（うそからでたまこと）', 'usokaradetamakoto', 'sự tín nhiệm đã không còn kể từ lời nói dối', 'N1', 'Chiết tự Hán Việt: THÀNH (誠)', 'lời Nói (言) THÀNH Thực(誠) thì sẽ Thành công(成)', '🎓', v_ch10_id, 34, '/assets/kanji/n1/illustrations/chap10_intro.webp', NOW())
