    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('繰', 'ケイ', 'く.る, く.り', 'kuru', 'SÀO', 'xe sợi len, mở trang sách', 14, '糸 -> 木', '糸', '毛糸を繰る (けいとをくる: xe sợi len)、本のページを繰る (ほんのページをくる: mở trang sách)、繰り返す (繰りかえす: lặp đi lặp lại)、予定の時間を繰り上げる (よていのじかんをくりあげる: đẩy thời gian dự kiến lên sớm hơn)', '毛糸を繰る（けいとをくる）', 'keitookuru', 'xe sợi len', 'N1', 'Chiết tự Hán Việt: SÀO (繰)', 'lấy dây buộc sản phẩm vào cây SÀO', '🎓', v_ch10_id, 37, '/assets/kanji/n1/illustrations/chap10_intro.webp', NOW())
