    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('娯', 'ゴ', '', 'go', 'NGU', 'Giải trí, vui chơi, tiêu khiển', 10, '女 -> 呉', '女', '娯楽 (ごらく: giải trí, tiêu khiển)、娯楽番組 (ごらくばんぐみ: chương trình giải trí)', '都会には多様な娯楽施設がある（とかいにはたようなごらくしせつがある）', 'Tokai ni wa tayou na goraku shisetsu ga aru', 'Ở đô thị có nhiều cơ sở vui chơi giải trí đa dạng', 'N1', 'Chiết tự Hán Việt: NGU (娯)', 'Người phụ nữ (女) nước Ngô (呉) múa hát mang lại niềm vui giải trí (NGU).', '🎨', v_ch11_id, 2, '/assets/kanji/n1/illustrations/chap11_intro.webp', NOW())
