    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('興', 'コウ, キョウ', 'おこ.る, おこ.す', 'okoru', 'HƯNG', 'một đất nước mới được gây dựng, khôi phục công việc kinh doanh', 14, '犭 -> 興', '犭', '新しい国が興る (あたらしいくにがおこる: một đất nước mới được gây dựng)、事業を興す (じぎょうをおこす: khôi phục công việc kinh doanh)、災害から復興する (さいがいからふっこうする: phục hồi sau thảm họa)、振興 (しんこう: khuyến khích túc đẩy)', '新しい国が興る（あたらしいくにがおこる）', 'atarashiikunigaokoru', 'một đất nước mới được gây dựng', 'N1', 'Chiết tự Hán Việt: HƯNG (興)', 'hai cái cầu thang giống nhau thật thú vị', '🎨', v_ch11_id, 3, '/assets/kanji/n1/illustrations/chap11_intro.webp', NOW())
