    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('趣', 'シ, シュ', 'おもむき', 'omomuki', 'THÚ', 'dáng vẻ, có sở thích', 17, '犭 -> 取 -> 走', '犭', '趣 (おもむき: dáng vẻ, cảnh tượng, sắc thái, phong cách)、趣味を持つ (しゅみをもつ: có sở thích)、趣旨 (しゅし: ý đồ mục đích)、趣向を凝らす (しゅこうをこらす: khơi gợi hứng thú)', '趣（おもむき）', 'omomuki', 'dáng vẻ, cảnh tượng, sắc thái, phong cách', 'N1', 'Chiết tự Hán Việt: THÚ (趣)', 'Lấy 取 hứng THÚ làm động lực chạy 走 cho nhanh', '🎨', v_ch11_id, 4, '/assets/kanji/n1/illustrations/chap11_intro.webp', NOW())
