    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('釣', 'ツリ', 'つ.る, つ.り', 'tsuru', 'ĐIẾU', 'câu cá, câu khách bằng những lời nói ngọt ngào', 14, '金 -> 釣', '金', '魚を釣る (さかなをつる: câu cá)、甘い言葉を客を釣る (あまいことばをきゃくをつる: câu khách bằng những lời nói ngọt ngào)、お釣り (おつり: tiền thừa)、釣銭 (つりせん: tiền thừa)', '魚を釣る（さかなをつる）', 'sakanaotsuru', 'câu cá', 'N1', 'Chiết tự Hán Việt: ĐIẾU (釣)', 'cần câu làm bằng sắt có bao móc cau mồi ở giữa', '🎨', v_ch11_id, 5, '/assets/kanji/n1/illustrations/chap11_intro.webp', NOW())
