    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('撮', 'サツ', 'と.る', 'toru', 'TOÁT', 'chụp ảnh, quay phim', 14, '最 -> 扌', '最', '写真を撮る (しゃしんをとる: chụp ảnh)、映画を撮影する (えいがをさつえいする: quay phim)、記念撮影 (きねんさつえい: chụp ảnh kỉ niệm)', '写真を撮る（しゃしんをとる）', 'shashinotoru', 'chụp ảnh', 'N1', 'Chiết tự Hán Việt: TOÁT (撮)', 'Sự Tối[最 (Tối Thượng)] của 1 Tay[扌(bộ thủ)] săn ảnh là phải TOÁT [撮 (Toát)] lên vẻ đẹp', '🎨', v_ch11_id, 6, '/assets/kanji/n1/illustrations/chap11_intro.webp', NOW())
