    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('漫', 'マン', '', 'man', 'MẠN', 'con sông mênh mông đầy nước, ngây thơ trong trắng', 17, '足 -> 氵 -> 日', '足', '漫々と水をたたえた川 (まんまんとみずをたたえたかわ: con sông mênh mông đầy nước)、天真爛漫 (てんしんらんまん: ngây thơ trong trắng)、漫画 (まんが: phim manga)、漫遊する (まんゆうする: du ngoạn)', '漫々と水をたたえた川（まんまんとみずをたたえたかわ）', 'manmantomizuotataetakawa', 'con sông mênh mông đầy nước', 'N1', 'Chiết tự Hán Việt: MẠN (漫)', 'Ở nước 氵 Nhật 日, mắc võng 罒 nằm chéo chân 又 Tản MẠN đọc manga', '🎨', v_ch11_id, 12, '/assets/kanji/n1/illustrations/chap11_intro.webp', NOW())
