    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('魔', 'クマ, マ', 'ま', 'ma', 'MA', 'ác ma, email ảo', 14, '宀 -> 木', '宀', '悪魔 (あくま: ác ma, ma quỷ)、メール魔 (メールま: email ảo)、魔が差す (まがさす: ma xui quỷ khiến)、魔法を使う (まほうをつかう: dùng ma thuật)', '悪魔（あくま）', 'akuma', 'ác ma, ma quỷ', 'N1', 'Chiết tự Hán Việt: MA (魔)', 'Trong nhà có 2 con quỷ MA cây', '👑', v_ch12_id, 20, '/assets/kanji/n1/illustrations/chap12_intro.webp', NOW())
