    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('吉', 'ヨ, キツ', 'きち', 'kichi', 'CÁT', 'vận may xuất hiện, điềm lành cứ tiếp diễn', 17, '亻 -> 士 -> 口', '亻', '吉が出る (きちがでる: vận may xuất hiện)、吉次が続く (よしじがつづく: điềm lành cứ tiếp diễn)、不吉な予感 (ふきつなよかん: điềm chẳng lành)、吉報 (きっぽう: tin vui)', '吉が出る（きちがでる）', 'kichigaderu', 'vận may xuất hiện', 'N1', 'Chiết tự Hán Việt: CÁT (吉)', 'Người có học (Sĩ) 士 luôn Nói (Khẩu) 口 ra những điều tốt lành (CÁT) 吉', '👑', v_ch12_id, 21, '/assets/kanji/n1/illustrations/chap12_intro.webp', NOW())
