    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('凶', 'キョウ', 'きょう', 'kyou', 'HUNG', 'căn nguyên, tội phạm hung ác', 14, '亻 -> 凶', '亻', '元凶 (げんきょう: căn nguyên, nguồn gốc)、凶悪犯 (きょうあくはん: tội phạm hung ác)、凶をひいた (きょうをひいた: rút phải thẻ rủi)、凶作 (きょうさく: mất mùa)', '元凶（げんきょう）', 'genkyou', 'căn nguyên, nguồn gốc', 'N1', 'Chiết tự Hán Việt: HUNG (凶)', 'Trói người bỏ xuống hố là HUNG ác', '👑', v_ch12_id, 22, '/assets/kanji/n1/illustrations/chap12_intro.webp', NOW())
