    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('鬼', 'キ', 'おに', 'oni', 'QUỶ', 'ma quỷ, nghiêm khắc trách mắng đứa trẻ', 14, '足 -> 金', '足', '鬼 (おに: ma quỷ)、心を鬼にして子を𠮟る (こころをおににしてこをしかる: nghiêm khắc trách mắng đứa trẻ)、仕事の鬼 (しごとのおに: nghiện công việc)、鬼に金棒 (おににかなぼう: hổ mọc thêm cánh)', '鬼（おに）', 'oni', 'ma quỷ', 'N1', 'Chiết tự Hán Việt: QUỶ (鬼)', 'Trên cánh đồng ,QUỶ 2 chân mang theo 1 ma bé', '👑', v_ch12_id, 24, '/assets/kanji/n1/illustrations/chap12_intro.webp', NOW())
