    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('裸', 'ラ', 'はだか', 'hadaka', 'KHỎA', 'cởi quần áo, tranh khỏa thân', 14, '果 -> 衤', '果', '裸になる (はだかになる: cởi quần áo)、裸体画 (らたいが: tranh khỏa thân)、全裸 (ぜんら: trần truồng)、裸眼視力を測る (らがんしりょくをはかる: đo thị lực mắt)', '裸になる（はだかになる）', 'hadakaninaru', 'cởi quần áo', 'N1', 'Chiết tự Hán Việt: KHỎA (裸)', 'kết quả(果) của việc thoát y(衤) là KHỎA thân', '🫀', v_ch13_id, 9, '/assets/kanji/n1/illustrations/chap13_intro.webp', NOW())
