    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('膝', 'ヒザ', 'ひざ', 'hiza', 'TẤT', 'gập đầu gối, đầu gối', 17, '氵 -> 人 -> 木', '氵', '膝を曲げる (ひざをまげる: gập đầu gối)、膝小僧 (ひざこぞう: đầu gối)、膝枕 (ひざまくら: nằm gối lên đùi)、膝を交えて話す (ひざをまじえてはなす: nói chuyện thân mật)', '膝を曲げる（ひざをまげる）', 'hizaomageru', 'gập đầu gối', 'N1', 'Chiết tự Hán Việt: TẤT (膝)', 'Người(人)đứng trên cây(木)ngắm trăng(月)thì đầu gối TẤT (膝)không bị dính nước(水', '🫀', v_ch13_id, 12, '/assets/kanji/n1/illustrations/chap13_intro.webp', NOW())
