    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('尻', 'ジリ', 'しり', 'shiri', 'CỬU', 'mông, sợ vợ/ sợ chồng', 14, '尸 -> 九', '尸', '尻 (しり: mông)、尻に敷かれる (しりにしかれる: sợ vợ/ sợ chồng)、尻にたたいて勉強させる (しりにたたいてべんきょうさせる: thúc giục học tập)、目尻を下げる (めじりをさげる: hạnh phúc, hài lòng)', '尻（しり）', 'shiri', 'mông', 'N1', 'Chiết tự Hán Việt: CỬU (尻)', 'THI(尸) đọc bảng CỬU(九)chương mà giọng cứ KHÀO KHÀO như CÁI ĐÍT(尻)ngan', '🫀', v_ch13_id, 16, '/assets/kanji/n1/illustrations/chap13_intro.webp', NOW())
