    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('肺', 'ハイ', 'はい', 'hai', 'PHẾ', 'mắc ung thư phổi, viêm phổi', 14, '月 -> 肺', '月', '肺がんになる (はいがんになる: mắc ung thư phổi)、肺炎 (はいえん: viêm phổi)、肺活量 (はいかつりょう: dung tích phổi)', '肺がんになる（はいがんになる）', 'haiganninaru', 'mắc ung thư phổi', 'N1', 'Chiết tự Hán Việt: PHẾ (肺)', 'chị Nguyệt Ở đô Thị hay bị viêm PHẾ quản', '🫀', v_ch13_id, 17, '/assets/kanji/n1/illustrations/chap13_intro.webp', NOW())
