    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('慢', 'マン', '', 'man', 'MẠN', 'lơ là bỏ bê công việc, tự mãn', 14, '目 -> 忄', '目', '職務怠慢 (しょくむたいまん: lơ là bỏ bê công việc)、自慢 (じまん: tự mãn)、傲慢な (ごうまんな: ngạo mạn)、我慢 (がまん: nhẫn nại)', '職務怠慢（しょくむたいまん）', 'shokumutaiman', 'lơ là bỏ bê công việc', 'N1', 'Chiết tự Hán Việt: MẠN (慢)', 'Con tim ngạo MẠN đứng nhìn mặt trời', '🫀', v_ch13_id, 25, '/assets/kanji/n1/illustrations/chap13_intro.webp', NOW())
