    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('陳', 'チン', '', 'chin', 'TRẦN', 'trưng bày, lời xin lỗi', 17, '山 -> 宀 -> 氵', '山', '陳列する (ちんれつする: trưng bày)、陳謝する (ちんしゃする: lời xin lỗi)、陳情 (ちんじょう: thỉnh cầu, kiến nghị)、新陳代謝 (しんちんたいしゃ: chuyển hóa, trao đổi chất)', '陳列する（ちんれつする）', 'chinretsusuru', 'trưng bày', 'N1', 'Chiết tự Hán Việt: TRẦN (陳)', 'Nhà TRẦN tuyên bố lập nước ở sườn ĐỒI phía ĐÔNG', '🏛️', v_ch14_id, 19, '/assets/kanji/n1/illustrations/chap14_intro.webp', NOW())
