    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('貫', 'カン', 'つらぬ.く', 'tsuranuku', 'QUÁN', 'xuyên thấu, giữ vững niềm tin', 14, '田 -> 金', '田', '貫く (つらぬく: xuyên thấu)、信念を貫く (しんねんをつらぬく: giữ vững niềm tin)、貫通する (かんつうする: đâm xuyên)、貫禄がある (かんろくがある: có quyền uy, uy nghiêm)', '貫く（つらぬく）', 'tsuranuku', 'xuyên thấu', 'N1', 'Chiết tự Hán Việt: QUÁN (貫)', 'Có ruộng và tiền sẽ QUÁN triệt được tất cả', '🏛️', v_ch14_id, 20, '/assets/kanji/n1/illustrations/chap14_intro.webp', NOW())
