    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('牲', 'セイ', '', 'sei', 'SINH', 'Vật hiến tế, sự hy sinh', 9, '牛 -> 生', '牛', '犠牲 (ぎせい: hy sinh)、犠牲者 (ぎせいしゃ: nạn nhân)', '尊い犠牲を払って平和を守る（とうといぎせいをはらってへいわをまもる）', 'Toutoi gisei o haratte heiwa o mamoru', 'Chấp nhận sự hy sinh cao cả để bảo vệ hòa bình', 'N1', 'Chiết tự Hán Việt: SINH (牲)', 'Con trâu bò (牛) còn sống (生) được dâng lên làm vật hy SINH tế lễ.', '🏛️', v_ch14_id, 23, '/assets/kanji/n1/illustrations/chap14_intro.webp', NOW())
