    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('脅', 'キョウ', 'おびや.かす, おど.す, おど.かす', 'odosu', 'HIẾP', 'Đe dọa, uy hiếp, bức bách', 10, '劦 -> 月', '力', '脅す (おどす: đe dọa)、脅かす (おびやかす: uy hiếp)、脅迫 (きょうはく: cưỡng bức đe dọa)、脅威 (きょうい: mối đe dọa)', '世界の平和を脅かす重大な危機（せかいのへいわをおびやかすじゅうだいなきき）', 'Sekai no heiwa o obiyakasu juudai na kiki', 'Cuộc khủng hoảng nghiêm trọng đe dọa hòa bình thế giới', 'N1', 'Chiết tự Hán Việt: HIẾP (脅)', 'Dùng ba phần sức lực (劦) ép sát cơ thể (月) để uy HIẾP đối phương.', '🏛️', v_ch14_id, 24, '/assets/kanji/n1/illustrations/chap14_intro.webp', NOW())
