    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('襲', 'シュウ', 'おそ.う, おそ.われる', 'osou', 'TẬP', 'tấn công ngân hàng, bị con gấu tấn công', 14, '衤 -> 亻', '衤', '銀行を襲う (ぎんこうをおそう: tấn công ngân hàng)、クマに襲われる (クマにおそわれる: bị con gấu tấn công)、襲撃する (しゅうげきする: tấn công)、逆襲する (ぎゃくしゅうする: phản kháng)', '銀行を襲う（ぎんこうをおそう）', 'ginkouoosou', 'tấn công ngân hàng', 'N1', 'Chiết tự Hán Việt: TẬP (襲)', 'Khủng Long mặc y phục để TẬP kích con người !', '🏛️', v_ch14_id, 25, '/assets/kanji/n1/illustrations/chap14_intro.webp', NOW())
