    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('陣', 'ジン', '', 'jin', 'TRẬN', 'trận địa, trại quân địch', 14, '車 -> 陣', '車', '陣地 (じんち: trận địa)、敵陣 (てきじん: trại quân địch)、陣頭指揮 (じんとうしき: đứng đầu chỉ huy quân đội)、報道陣 (ほうどうじん: phóm phóng viên)', '陣地（じんち）', 'jinchi', 'trận địa', 'N1', 'Chiết tự Hán Việt: TRẬN (陣)', 'bê (B) xe (車) ra TRẬN (陣)', '🏛️', v_ch14_id, 31, '/assets/kanji/n1/illustrations/chap14_intro.webp', NOW())
