    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('拘', 'コウ', '', 'kou', 'CÂU', 'ràng buộc, thời gian làm việc', 14, '口 -> 扌', '口', '拘束する (こうそくする: ràng buộc, giam lỏng)、拘束時間 (こうそくじかん: thời gian làm việc)、拘留する (こうりゅうする: giam giữ)、拘置所 (こうちしょ: trại tạm giam)', '拘束する（こうそくする）', 'kousokusuru', 'ràng buộc, giam lỏng', 'N1', 'Chiết tự Hán Việt: CÂU (拘)', 'Miệng nói Bao CÂU thì Tay vẫn bị bắt', '🏛️', v_ch14_id, 33, '/assets/kanji/n1/illustrations/chap14_intro.webp', NOW())
