    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('謙', 'ケン', '', 'ken', 'KHIÊM', 'người khiêm tốn, khiêm nhường ngữ', 17, '亻 -> 言 -> 兼', '亻', '謙虚な人 (けんきょなひと: người khiêm tốn)、謙譲語 (けんじょうご: khiêm nhường ngữ)', '謙虚な人（けんきょなひと）', 'kenkyonahito', 'người khiêm tốn', 'N1', 'Chiết tự Hán Việt: KHIÊM (謙)', '(Ngôn 言) từ của người (kiêm 兼) nhiều chức vụ thường (KHIÊM 謙 )tốn', '🙇', v_ch15_id, 5, '/assets/kanji/n1/illustrations/chap15_intro.webp', NOW())
