    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('遜', 'ソン', '', 'son', 'TỐN', 'khiêm tốn, không kém hơn', 14, '一 -> 遜', '遜', '謙遜する (けんそんする: khiêm tốn)、遜色がない (そんしょくがない: không kém hơn, không thấp hơn)、不遜な態度 (ふそんなたいど: thái độ ngạo mạn)', '謙遜する（けんそんする）', 'kensonsuru', 'khiêm tốn', 'N1', 'Chiết tự Hán Việt: TỐN (遜)', 'Dạy con cháu đi lại khiêm TỐN', '🙇', v_ch15_id, 6, '/assets/kanji/n1/illustrations/chap15_intro.webp', NOW())
