    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('寿', 'ジュ', 'ひさし', 'hisashi', 'THỌ', 'thiếp cưới, tuổi thọ', 14, '一 -> 寿', '寿', '寿 (ひさし: thiếp cưới)、寿命 (じゅみょう: tuổi thọ)、平均寿命 (へいきんじゅみょう: tuổi thọ trung bình)、長寿 (ちょうじゅ: trường thọ)', '寿（ひさし）', 'hisashi', 'thiếp cưới', 'N1', 'Chiết tự Hán Việt: THỌ (寿)', 'Trải qua 3 lần thốn thì sẽ sống THỌ', '🙇', v_ch15_id, 9, '/assets/kanji/n1/illustrations/chap15_intro.webp', NOW())
