    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('該', 'ガイ', '', 'gai', 'CAI', 'Đương sự, tương ứng, nói trên', 13, '言 -> 亥', '言', '該当 (がいとう: tương ứng, thuộc diện)、当該 (とうがい: đương sự, nói trên)、博学多才 (はくがくたさい)', '該当する項目に丸をつけてください（がいとうするこうもくにまるをつけてください）', 'Gaitousuru koumoku ni maru o tsukete kudasai', 'Xin hãy khoanh tròn vào hạng mục tương ứng', 'N1', 'Chiết tự Hán Việt: CAI (該)', 'Lời nói (言) xác nhận đúng tuổi Hợi (亥) của đương sự (CAI).', '📜', v_ch16_id, 17, '/assets/kanji/n1/illustrations/chap16_intro.webp', NOW())
