    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('扶', 'フ', 'たす.ける', 'tasu', 'PHÙ', 'Nâng đỡ, giúp đỡ, cấp dưỡng', 7, '扌 -> 夫', '扌', '扶養 (ふよう: cấp dưỡng, nuôi dưỡng)、扶助 (ふじょ: tương trợ giúp đỡ)、相互扶助 (そうごふじょ: tương thân tương ái)', '家族を扶養する義務がある（かぞくをふようするぎむがある）', 'Kazoku o fuyousuru gimu ga aru', 'Có nghĩa vụ cấp dưỡng chăm lo cho gia đình', 'N1', 'Chiết tự Hán Việt: PHÙ (扶)', 'Đưa bàn tay (扌) nâng đỡ người chồng/trượng phu (夫) lúc khó khăn (PHÙ trợ).', '📜', v_ch16_id, 19, '/assets/kanji/n1/illustrations/chap16_intro.webp', NOW())
