    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('媒', 'バイ', '', 'bai', 'MÔI', 'Môi giới, trung gian, truyền thông', 12, '女 -> 某', '女', '媒体 (ばいたい: phương tiện truyền thông)、媒介 (ばいかい: trung gian truyền dẫn)、触媒 (しょくばい: chất xúc tác)、媒酌人 (ばいしゃくにん: người làm mai)', 'インターネットを媒体として情報を発信する（インターネットをばいたいとしてじょうほうをはっしんする）', 'Intaanetto o baitai toshite jouhou o hasshinsuru', 'Phát đi thông tin lấy Internet làm phương tiện truyền dẫn', 'N1', 'Chiết tự Hán Việt: MÔI (媒)', 'Người phụ nữ (女) giúp kết nối người nào đó (某) nên duyên vợ chồng (làm MÔI).', '📜', v_ch16_id, 20, '/assets/kanji/n1/illustrations/chap16_intro.webp', NOW())
