    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('嘱', 'ショク', 'しょく.する', 'shoku', 'CHÚC', 'Ủy thác, giao phó, dặn dò', 15, '口 -> 属', '口', '委嘱 (いしょく: ủy thác giao phó)、嘱託 (しょくたく: cộng tác viên hợp đồng)、嘱望 (しょくぼう: kỳ vọng gửi gắm)', '専門家に調査を委嘱する（せんもんかにちょうさをいしょくする）', 'Senmonka ni chousa o ishokusuru', 'Ủy thác việc khảo sát cho chuyên gia', 'N1', 'Chiết tự Hán Việt: CHÚC (嘱)', 'Dùng lời nói từ miệng (口) dặn dò người thuộc quyền (属) làm việc (ủy CHÚC).', '📜', v_ch16_id, 21, '/assets/kanji/n1/illustrations/chap16_intro.webp', NOW())
