    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('懇', 'コン', 'ねんご.ろ', 'nengoro', 'KHẨN', 'Thân mật, chân thành, khẩn thiết', 17, '豸 -> 心', '心', '懇談 (こんだん: tọa đàm thân mật)、懇親会 (こんしんかい: tiệc giao lưu thân mật)、懇願 (こんがん: khẩn cầu)、懇切丁寧 (こんせつていねい: ân cần chu đáo)', '住民との懇談会を開催する（じゅうみんとのこんだんかいをかいさいする）', 'Juumin to no kondankai o kaisaisuru', 'Tổ chức buổi tọa đàm thân mật với người dân', 'N1', 'Chiết tự Hán Việt: KHẨN (懇)', 'Tấm lòng (心) chân thành tha thiết hướng về nhau trong buổi trò chuyện (KHẨN).', '📜', v_ch16_id, 22, '/assets/kanji/n1/illustrations/chap16_intro.webp', NOW())
