    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('弊', 'ヘイ', '', 'hei', 'TỆ', 'Tệ hại, thói xấu, khiêm xưng công ty mình', 15, '敝 -> 廾', '廾', '弊害 (へいがい: mặt trái, tệ hại)、弊社 (へいしゃ: công ty chúng tôi - khiêm nhường)、疲弊 (ひへい: kiệt quệ rệu rã)、旧弊 (きゅうへい: hủ tục)', '制度の弊害を改める必要がある（せいどのへいがいをあらためるひつようがある）', 'Seido no heigai o aratameru hitsuyou ga aru', 'Cần phải chấn chỉnh những mặt trái tệ hại của chế độ', 'N1', 'Chiết tự Hán Việt: TỆ (弊)', 'Hai bàn tay (廾) nâng tấm vải rách nát (敝) biểu thị sự khiêm nhường hoặc TỆ hại.', '📜', v_ch16_id, 23, '/assets/kanji/n1/illustrations/chap16_intro.webp', NOW())
