    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('綻', 'タン', 'ほころ.びる', 'hokoro', 'TRÁN', 'Bục chỉ, rách toạc, đổ vỡ, hé nở', 14, '糸 -> 定', '糸', '破綻 (はたん: đổ vỡ, phá sản)、ほころびる (bục đường chỉ, nụ hoa hé nở)', '経営が破綻して会社が倒産した（けいえいがはたんしてかいしゃがとうさんした）', 'Keiei ga hatanshite kaisha ga tousanshita', 'Việc kinh doanh đổ vỡ khiến công ty phá sản', 'N1', 'Chiết tự Hán Việt: TRÁN (綻)', 'Đường chỉ khâu (糸) cố định (定) bị bung rách làm kế hoạch đổ vỡ (phá TRÁN).', '📜', v_ch16_id, 24, '/assets/kanji/n1/illustrations/chap16_intro.webp', NOW())
