    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('措', 'ソ', 'お.く', 'so', 'THỐ', 'Đặt để, thi hành biện pháp, xử lý', 11, '扌 -> 昔', '扌', '措置 (そち: biện pháp xử lý)、措く (おく: gác lại, để sang một bên)、挙措 (きょそ: cử chỉ hành động)', '緊急の措置を講じる（きんきゅうのそちをこうじる）', 'Kinkyuu no sochi o koujiru', 'Thực hiện các biện pháp xử lý khẩn cấp', 'N1', 'Chiết tự Hán Việt: THỐ (措)', 'Đưa tay (扌) sắp xếp công việc từ xưa (昔) để đưa ra biện pháp xử lý (THỐ trí).', '📜', v_ch16_id, 25, '/assets/kanji/n1/illustrations/chap16_intro.webp', NOW())
