    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('准', 'ジュン', '', 'jun', 'CHUẨN', 'Phê chuẩn, cấp phó (tương đương)', 10, '冫 -> 隹', '冫', '批准 (ひじゅん: phê chuẩn hiệp ước)、准教授 (じゅんきょうじゅ: phó giáo sư)、准看護師 (じゅんかんごし: y tá trung cấp)', '国際条約を国会で批准する（こくさいじょうやくをこっかいでひじゅんする）', 'Kokusai jouyaku o kokkai de hijunsuru', 'Phê chuẩn điều ước quốc tế tại Quốc hội', 'N1', 'Chiết tự Hán Việt: CHUẨN (准)', 'Dòng nước đóng băng (冫) phẳng lặng nơi chim (隹) đậu làm thước đo phê CHUẨN.', '📜', v_ch16_id, 26, '/assets/kanji/n1/illustrations/chap16_intro.webp', NOW())
