    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('款', 'カン', '', 'kan', 'KHOẢN', 'Điều khoản, khoản tiền, lòng thành', 12, '士 -> 欠', '欠', '定款 (ていかん: điều lệ công ty)、約款 (やっかん: điều khoản hợp đồng)、借款 (しゃっかん: khoản vay tín dụng)、落款 (らっかん: con dấu lạc khoản)', '会社の定款を変更する（かいしゃのていかんをへんこうする）', 'Kaisha no teikan o henkousuru', 'Thay đổi điều lệ hoạt động của công ty', 'N1', 'Chiết tự Hán Việt: KHOẢN (款)', 'Khắc từng điều KHOẢN trang trọng lên văn bản thỏa thuận chính thức.', '📜', v_ch16_id, 27, '/assets/kanji/n1/illustrations/chap16_intro.webp', NOW())
