    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('枢', 'スウ', '', 'suu', 'XU', 'trục, trung tâm', 17, '忄 -> 木 -> 区', '忄', '枢軸 (すうじく: trục, trung tâm)、中枢 (ちゅうすう: trung tâm)、枢要な産業 (すうようなさんぎょう: ngành công nghiệp chủ chốt)、中枢神経 (ちゅうすうしんけい: thần kinh trung ương)', '枢軸（すうじく）', 'suujiku', 'trục, trung tâm', 'N1', 'Chiết tự Hán Việt: XU (枢)', 'XU(枢) xu là CÂY(木) mọc ở KHU(区) trung tâm(枢)', '📜', v_ch16_id, 33, '/assets/kanji/n1/illustrations/chap16_intro.webp', NOW())
