    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('箇', 'ニカ', '', 'nika', 'CÁ', '2 nơi, địa điểm chỉnh sửa', 14, '固 -> 竹', '固', '二箇所 (にかしょ: 2 nơi, 2 chỗ (cách đếm địa điểm))、修正箇所 (しゅうせいかしょ: địa điểm chỉnh sửa)、箇条書きにする (かじょうがきにする: liệt kê, gạch đầu dòng)', '二箇所（にかしょ）', 'nikasho', '2 nơi, 2 chỗ (cách đếm địa điểm)', 'N1', 'Chiết tự Hán Việt: CÁ (箇)', 'Đếm các con CÁ ngoan Cố (固) chui vào ống Trúc ( 竹)', '📐', v_ch17_id, 14, '/assets/kanji/n1/illustrations/chap17_intro.webp', NOW())
