    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('括', 'カツ', '', 'katsu', 'QUÁT', 'cùng một lúc, tổng kết', 17, '口 -> 扌 -> 舌', '口', '一括する (いっかつする: cùng một lúc)、総括 (そうかつ: tổng kết)、統括する (とうかつする: bao quát)、一括払い (いっかつばらい: thanh toán một lần)', '一括する（いっかつする）', 'ikkatsusuru', 'cùng một lúc', 'N1', 'Chiết tự Hán Việt: QUÁT (括)', 'khua Tay 9 (扌)  múa Lưỡi (舌) bao QUÁT vấn đề', '📐', v_ch17_id, 15, '/assets/kanji/n1/illustrations/chap17_intro.webp', NOW())
