    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('塊', 'カイ', 'かたまり', 'katamari', 'KHỐI', 'đống tuyết, mua 1 miếng thịt', 17, '石 -> 鬼 -> 土', '石', '雪の塊 (ゆきのかたまり: đống tuyết)、牛肉を塊で買う (ぎゅうにくをかたまりでかう: mua 1 miếng thịt)、金塊 (きんかい: vàng khối, thỏi vàng)', '雪の塊（ゆきのかたまり）', 'yukinokatamari', 'đống tuyết', 'N1', 'Chiết tự Hán Việt: KHỐI (塊)', 'Con quỷ 鬼 từ đất 土 chui ra biến thành KHỐI đá 塊', '📐', v_ch17_id, 20, '/assets/kanji/n1/illustrations/chap17_intro.webp', NOW())
