    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('岐', 'キ', '', 'ki', 'KÌ', 'phân nhánh, nội dung trải rộng', 14, '支 -> 山', '支', '分岐する (ぶんきする: phân nhánh)、多岐にわたる (たきにわたる: nội dung trải rộng)、分岐点 (ぶんきてん: điểm phân nhánh, bước ngoặt)、岐路 (きろ: ngã rẽ, đường rẽ)', '分岐する（ぶんきする）', 'bunkisuru', 'phân nhánh', 'N1', 'Chiết tự Hán Việt: KÌ (岐)', 'phân công cho Chi (支) nhánh trên Núi (山) theo định KÌ', '📐', v_ch17_id, 22, '/assets/kanji/n1/illustrations/chap17_intro.webp', NOW())
