    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('又', 'マ', 'また', 'mata', 'HỰU', 'hãy nắm lấy cơ hội sau, việc cho thuê lại sách', 14, '扌 -> 又', '扌', '又の機会にしましょう (またのきかいにしましょう: hãy nắm lấy cơ hội sau)、本の又貸し (ほんのまたがし: việc cho thuê lại sách)', '又の機会にしましょう（またのきかいにしましょう）', 'matanokikainishimashou', 'hãy nắm lấy cơ hội sau', 'N1', 'Chiết tự Hán Việt: HỰU (又)', 'HỰU vắt chéo 2 tay trước ngực', '📐', v_ch17_id, 23, '/assets/kanji/n1/illustrations/chap17_intro.webp', NOW())
