    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('既', 'キ', 'すで', 'sude', 'KÍ', 'tình trạng đã quá muộn, đã kết hôn', 14, '艮 -> 旡', '艮', '既に手遅れの状態 (すでにておくれのじょうたい: tình trạng đã quá muộn)、既婚 (きこん: đã kết hôn)、既製服 (きせいふく: quần áo may sẵn)、既成の事実 (きせいのじじつ: sự đã rồi)', '既に手遅れの状態（すでにておくれのじょうたい）', 'sudeniteokurenojoutai', 'tình trạng đã quá muộn', 'N1', 'Chiết tự Hán Việt: KÍ (既)', 'Lấn cấn (艮) thì cũng đã KÍ (旡) rồi', '📐', v_ch17_id, 24, '/assets/kanji/n1/illustrations/chap17_intro.webp', NOW())
