    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('謎', 'ナゾ', 'なぞ', 'nazo', 'MÊ', 'lí giải điều bí ẩn, vụ việc đã được che dấu điều bí ẩn', 17, '禾 -> 言 -> 米', '禾', '謎を解く (なぞをとく: lí giải điều bí ẩn)、謎に包まれた事件 (なぞにつつまれたじけん: vụ việc đã được che dấu điều bí ẩn)、謎謎で遊ぶ (なぞなぞであそぶ: chơi câu đố)', '謎を解く（なぞをとく）', 'nazootoku', 'lí giải điều bí ẩn', 'N1', 'Chiết tự Hán Việt: MÊ (謎)', 'khi MÊ nói (言) sảng hạt gạo (米) đi lạc ngoài đường (辶)', '⛩️', v_ch18_id, 17, '/assets/kanji/n1/illustrations/chap18_intro.webp', NOW())
