    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('獄', 'ゴク', '', 'goku', 'NGỤC', 'thiên đường và địa ngục, nhà giam', 17, '亻 -> 言 -> 犬', '亻', '天国と地獄 (てんごくとじごく: thiên đường và địa ngục)、監獄 (かんごく: nhà giam, nhà ngục)、脱獄 (だつごく: vượt ngục)、獄中 (ごくちゅう: trong ngục)', '天国と地獄（てんごくとじごく）', 'tengokutojigoku', 'thiên đường và địa ngục', 'N1', 'Chiết tự Hán Việt: NGỤC (獄)', 'Địa NGỤC là lúc người ta NÓI ( 言) nhau chẳng khác gì CHÓ(犬)với CHÓ (犭)', '⛩️', v_ch18_id, 20, '/assets/kanji/n1/illustrations/chap18_intro.webp', NOW())
