    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('冥', 'メイ', '', 'mei', 'MINH', 'sao Diêm Vương, âm phủ', 17, '木 -> 六 -> 冖', '木', '冥王星 (めいおうせい: sao Diêm Vương)、冥土（冥途） (めいど（めいど）: âm phủ)、瞑想 (めいそう: ngồi thiền)', '冥王星（めいおうせい）', 'meiousei', 'sao Diêm Vương', 'N1', 'Chiết tự Hán Việt: MINH (冥)', 'Bác Sáu (六) ở rừng u MINH lấy Khăn (冖) che Mặt trời (日)', '⛩️', v_ch18_id, 21, '/assets/kanji/n1/illustrations/chap18_intro.webp', NOW())
