    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('襟', 'エリ, キン', 'えり', 'eri', 'KHÂM', 'cổ áo, cái gáy', 14, '禁 -> 衤', '禁', '服の襟 (ふくのえり: cổ áo)、襟首 (えりくび: cái gáy)、襟を正す (えりをただす: sửa sang cổ áo chỉnh tề)、胸襟を開く (きょうきんをひらく: mở lòng)', '服の襟（ふくのえり）', 'fukunoeri', 'cổ áo', 'N1', 'Chiết tự Hán Việt: KHÂM (襟)', 'Cấm (禁) KHÂM sai mặc Y phục (衤) có CỔ ÁO', '👘', v_ch19_id, 25, '/assets/kanji/n1/illustrations/chap19_intro.webp', NOW())
