    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('芯', 'エン', 'しん', 'shin', 'TÂM', 'ngòi bút chì, lồng lót cổ áo', 17, '忄 -> 心 -> 艹', '忄', '鉛筆の芯 (えんぴつのしん: ngòi bút chì)、襟に芯を入れる (えりにしんをいれる: lồng lót cổ áo)、体の芯まで冷える (からだのしんまでひえる: làm mát đến tận trong cơ thể)', '鉛筆の芯（えんぴつのしん）', 'enpitsunoshin', 'ngòi bút chì', 'N1', 'Chiết tự Hán Việt: TÂM (芯)', 'TÂM (心)  + thảo (艹) = tận đáy lòng', '👘', v_ch19_id, 26, '/assets/kanji/n1/illustrations/chap19_intro.webp', NOW())
