    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('履', 'リ', 'は.く, は.き', 'haku', 'LÍ', 'xỏ giày, giày dép', 14, '復 -> 尸', '復', '靴を履く (くつをはく: xỏ giày)、履き物 (はきもの: giày dép)、履歴書 (りれきしょ: sơ  yếu lí lịch)、契約を履行する (けいやくをりこうする: thi hành/ thực thi hợp đồng)', '靴を履く（くつをはく）', 'kutsuohaku', 'xỏ giày', 'N1', 'Chiết tự Hán Việt: LÍ (履)', 'Phục hồi (復) lại LÍ lịch để đi Thi ( 尸)', '👘', v_ch19_id, 27, '/assets/kanji/n1/illustrations/chap19_intro.webp', NOW())
