    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('縛', 'バク', 'しば.る, しば.られる', 'shibaru', 'PHƯỢC', 'buộc, bị hạn chế', 14, '糸 -> 尃', '糸', '紐で縛る (ひもでしばる: buộc, trói dây giày)、規則に縛られる (きそくにしばられる: bị hạn chế, rằng buộc bởi các quy tắc)、自由を束縛される (じゆうをそくばくされる: bị trói buộc hạn chế sự tự do)', '紐で縛る（ひもでしばる）', 'himodeshibaru', 'buộc, trói dây giày', 'N1', 'Chiết tự Hán Việt: PHƯỢC (縛)', 'PHƯỢC là Chỉ (糸) Chuyên (尃) dùng để BUỘC', '👘', v_ch19_id, 30, '/assets/kanji/n1/illustrations/chap19_intro.webp', NOW())
