    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('賄', 'ワイ', 'まかな.う', 'makanau', 'HỐI', 'tặng quà hối lộ, nhận hối lộ', 17, '金 -> 有 -> 貝', '金', '贈賄 (ぞうわい: tặng quà hối lộ)、収賄 (しゅうわい: nhận hối lộ)、生活費を賄う (せいかつひをまかなう: trang trải chi phí sinh hoạt)', '贈賄（ぞうわい）', 'zouwai', 'tặng quà hối lộ', 'N1', 'Chiết tự Hán Việt: HỐI (賄)', 'Có (有) tiền  (貝) thì nghĩ ngay đến HỐI lộ', '⚔️', v_ch20_id, 1, '/assets/kanji/n1/illustrations/chap20_intro.webp', NOW())
