    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('窃', 'セッ', '', 'se', 'THIẾT', 'phạm tội trộm cắp, bắt giữu kẻ trộm', 14, '切 -> 穴', '切', '窃盗をはたらく (せっとうをはたらく: phạm tội trộm cắp)、窃盗犯を検挙する (せっとうはんをけんきょする: bắt giữu kẻ trộm)', '窃盗をはたらく（せっとうをはたらく）', 'settouohataraku', 'phạm tội trộm cắp', 'N1', 'Chiết tự Hán Việt: THIẾT (窃)', 'THIẾT nghĩ kẻ trộm cắp (窃) thì nên bị cắt (切)  đầu rồi chôn xuống Huyệt (穴 )', '⚔️', v_ch20_id, 4, '/assets/kanji/n1/illustrations/chap20_intro.webp', NOW())
