    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('拐', 'カイ', '', 'kai', 'QUẢI', 'Bắt cóc, lừa gạt cuỗm đi', 8, '扌 -> 另', '扌', '誘拐 (ゆうかい: bắt cóc)、拐帯 (かいたい: cuỗm tiền bỏ trốn)', '子供の誘拐事件を未然に防ぐ（こどものゆうかいじけんをみぜんにふせぐ）', 'Kodomo no yuukai jiken o mizen ni fusegu', 'Ngăn chặn từ trước vụ án bắt cóc trẻ em', 'N1', 'Chiết tự Hán Việt: QUẢI (拐)', 'Dùng tay (扌) dùng lời đường mật ở miệng (口) và sức mạnh (力) để bắt cóc (dụ QUẢI).', '⚔️', v_ch20_id, 5, '/assets/kanji/n1/illustrations/chap20_intro.webp', NOW())
