    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('搾', 'サク', 'しぼ.る, しぼ.り', 'shiboru', 'TRÁ', 'vắt sữa bò, bóc lột tiền thuế', 14, '扌 -> 穴', '扌', '牛の乳を搾る (うしのちちをしぼる: vắt sữa bò)、税金を搾り取る (ぜいきんをしぼりとる: bóc lột tiền thuế)、利益を搾取する (りえきをさくしゅする: bóc lột lợi nhuận)', '牛の乳を搾る（うしのちちをしぼる）', 'ushinochichioshiboru', 'vắt sữa bò', 'N1', 'Chiết tự Hán Việt: TRÁ (搾)', 'Tay ( 扌) xảo TRÁ bị ÉP cầm bồ Cào đào Huyệt ( 穴 )', '⚔️', v_ch20_id, 11, '/assets/kanji/n1/illustrations/chap20_intro.webp', NOW())
