    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('謀', 'ボウ, ム', 'はか.る', 'hakaru', 'MƯU (MƯU mẹo phải dùng Ngôn (言) từ Mộc (木) mạc mà Ngọt (甘) ngào!', 'âm mưu ám sát tổng thống, kế hoạch liều lĩnh', 17, '言 -> 木 -> 甘', '言', '大統領暗殺を謀る (だいとうりょうあんさつをはかる: âm mưu ám sát tổng thống)、無謀な計画 (むぼうなけいかく: kế hoạch liều lĩnh)、陰謀 (いんぼう: âm mưu)、謀反 (むほん: chống đối)', '大統領暗殺を謀る（だいとうりょうあんさつをはかる）', 'daitouryouansatsuohakaru', 'âm mưu ám sát tổng thống', 'N1', 'Chiết tự Hán Việt: MƯU (MƯU mẹo phải dùng Ngôn (言) từ Mộc (木) mạc mà Ngọt (甘) ngào! (謀)', 'MƯU (MƯU mẹo phải dùng Ngôn (言) từ Mộc (木) mạc mà Ngọt (甘) ngào!', '⚔️', v_ch20_id, 12, '/assets/kanji/n1/illustrations/chap20_intro.webp', NOW())
