    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('酷', 'コク, コ', '', 'koku', 'KHỐC', 'tàn khốc, người lạnh lùng', 14, '酉 -> 告', '酉', '残酷な (ざんこくな: tàn khốc)、冷酷な人 (れいこくなひと: người lạnh lùng, tàn nhẫn)、体を酷使する (からだをこくしする: làm việc quá sức)、過酷なトレーニング (かこくなトレーニング: huấn luyện đào tạo khắc nhiệt)', '残酷な（ざんこくな）', 'zankokuna', 'tàn khốc', 'N1', 'Chiết tự Hán Việt: KHỐC (酷)', 'Uống rượu vào thì sẽ tố cáo (告) nhau 1 cách tàn KHỐC', '⚔️', v_ch20_id, 14, '/assets/kanji/n1/illustrations/chap20_intro.webp', NOW())
