    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('征', 'セイ', '', 'sei', 'CHINH', 'trận đấu diễn ra ở nước ngoài, xâm chiếm nước láng giềng', 17, '辶 -> 足 -> 正', '辶', '試合で外国へ遠征する (しあいでがいこくへえんせいする: trận đấu diễn ra ở nước ngoài)、隣国を征服する (りんごくをせいふくする: xâm chiếm nước láng giềng)', '試合で外国へ遠征する（しあいでがいこくへえんせいする）', 'shiaidegaikokuheenseisuru', 'trận đấu diễn ra ở nước ngoài', 'N1', 'Chiết tự Hán Việt: CHINH (征)', 'CHINH  phục con đường chân chính (正)', '⚔️', v_ch20_id, 15, '/assets/kanji/n1/illustrations/chap20_intro.webp', NOW())
