    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('覇', 'ハ', '', 'ha', 'BÁ (Qua nhiều tháng  )cải cách (革)  để nuôi mộng xưng BÁ vượt', 'bá chủ, chinh phục', 14, '革 -> 覇', '革', '覇者 (はしゃ: bá chủ)、制覇する (せいはする: chinh phục)', '覇者（はしゃ）', 'hasha', 'bá chủ', 'N1', 'Chiết tự Hán Việt: BÁ (Qua nhiều tháng  )cải cách (革)  để nuôi mộng xưng BÁ vượt (覇)', 'BÁ (Qua nhiều tháng  )cải cách (革)  để nuôi mộng xưng BÁ vượt', '⚔️', v_ch20_id, 16, '/assets/kanji/n1/illustrations/chap20_intro.webp', NOW())
