    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('懲', 'シッ', 'こ.りる, こ.らす', 'koriru', 'TRỪNG', 'nản lòng, trừng trị kẻ ác', 17, '忄 -> 徴 -> 王', '忄', '失敗に懲りる (しっぱいにこりる: nản lòng, chùn bước vì thất bại)、悪人を懲らす (あくにんをこらす: trừng trị kẻ ác)、噓をつく子を懲らしめる (うそをつくこをこらしめる: trùng phạt đứa trẻ nói dối)、懲役刑 (ちょうえきけい: hình phạt tù)', '失敗に懲りる（しっぱいにこりる）', 'shippainikoriru', 'nản lòng, chùn bước vì thất bại', 'N1', 'Chiết tự Hán Việt: TRỪNG (懲)', 'Đặc Trưng (徴) của vua (王) là TRỪNG trị kẻ làm điều trái với lương Tâm (心)', '⚔️', v_ch20_id, 17, '/assets/kanji/n1/illustrations/chap20_intro.webp', NOW())
