    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('虚', 'キョ, キ', '', 'kyo', 'HƯ', 'ngày ngày trống rỗng, lời khai man', 14, '虍 -> 业', '虍', '空虚な日々 (くうきょなひび: ngày ngày trống rỗng)、虚偽の証言 (きょぎのしょうげん: lời khai man)、虚弱体質 (きょじゃくたいしつ: thể trạng yếu ớt)、虚空を掴む (こくうをつかむ: nắm lấy khoảng không)', '空虚な日々（くうきょなひび）', 'kuukyonahibi', 'ngày ngày trống rỗng', 'N1', 'Chiết tự Hán Việt: HƯ (虚)', 'răng hô (虍 ) và xếp ( 业)  thẳng hàng được thì thật là HƯ cấu', '⚔️', v_ch20_id, 26, '/assets/kanji/n1/illustrations/chap20_intro.webp', NOW())
