    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('禍', 'カ', '', 'ka', 'HỌA', 'để lại ảnh hưởng xấu, điều lỡ lời', 17, '耳 -> 咼 -> 礻', '耳', '禍根を残す (かこんをのこす: để lại ảnh hưởng xấu)、舌禍 (ぜっか: điều lỡ lời)、人生の禍福 (じんせいのかふく: phúc họa của đời người)', '禍根を残す（かこんをのこす）', 'kakononokosu', 'để lại ảnh hưởng xấu', 'N1', 'Chiết tự Hán Việt: HỌA (禍)', 'Qua loa (咼) là biểu thị (礻) của tai HỌA (禍)', '⚔️', v_ch20_id, 27, '/assets/kanji/n1/illustrations/chap20_intro.webp', NOW())
