    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('陵', 'ョウ, リョウ', 'みささぎ', 'misasagi', 'LĂNG', 'lăng mộ, thở cúng tại lăng mộ', 17, '阝 -> 夂 -> 先', '阝', '陵 (みささぎ: lăng mộ)、御陵に参拝する (ごりょうにさんぱいする: thở cúng tại lăng mộ)、丘陵 (きゅうりょう: ngọn đồi)', '陵（みささぎ）', 'misasagi', 'lăng mộ', 'N1', 'Chiết tự Hán Việt: LĂNG (陵)', 'LĂNG tẩm của các Bố (阝) bị Truy (夂) xét đầu Tiên(先)', '🏯', v_ch21_id, 5, '/assets/kanji/n1/illustrations/chap21_intro.webp', NOW())
