    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('郭', 'カク', '', 'kaku', 'QUÁCH', 'bao quanh tòa thành, vẽ nét phác thảo', 17, '土 -> 口 -> 子', '土', '城郭を巡らす (じょうかくをめぐらす: bao quanh tòa thành)、輪郭を描く (りんかくをかく: vẽ nét phác thảo)', '城郭を巡らす（じょうかくをめぐらす）', 'joukakuomegurasu', 'bao quanh tòa thành', 'N1', 'Chiết tự Hán Việt: QUÁCH (郭)', 'Đầu tiên,dùng Miệng (口) dạy Trẻ (子) dựng Bờ đất (阝) làm Thành QUÁCH', '🏯', v_ch21_id, 6, '/assets/kanji/n1/illustrations/chap21_intro.webp', NOW())
