    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('朽', 'ュウ', 'く.ちる', 'kuchiru', 'HỦ', 'mục nát, hư hỏng', 14, '目 -> 木', '目', '木が朽ちる (きがくちる: mục nát)、老朽化する (ろうきゅうかする: hư hỏng, cũ kỹ)、不朽の名作 (ふきゅうのめいさく: tác phẩm trứ danh)', '木が朽ちる（きがくちる）', 'kigakuchiru', 'mục nát', 'N1', 'Chiết tự Hán Việt: HỦ (朽)', 'Cây gỗ (木) 5 năm tưởng bất HỦ vậy mà đã mục nát rồi', '🏯', v_ch21_id, 8, '/assets/kanji/n1/illustrations/chap21_intro.webp', NOW())
