    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('薫', 'カオ, クン', '', 'kao', 'HUÂN', 'tháng 5 gió hiu hiu mát mẻ, làm món cá xông khói', 17, '灬 -> 重 -> 艹', '灬', '風薫る五月 (かぜかおるごがつ: tháng 5 gió hiu hiu mát mẻ)、魚を燻製にする (さかなをくんせいにする: làm món cá xông khói)、薫陶を受ける (くんとうをうける: nhận được sự cảm hóa)', '風薫る五月（かぜかおるごがつ）', 'kazekaorugogatsu', 'tháng 5 gió hiu hiu mát mẻ', 'N1', 'Chiết tự Hán Việt: HUÂN (薫)', 'HUÂN chương sẽ trao tặng cho ai nấu (灬 )  được 1 trọng (重) lượng cỏ (艹) thơm !', '🍶', v_ch22_id, 11, '/assets/kanji/n1/illustrations/chap22_intro.webp', NOW())
