    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('殻', 'ガラ, カク', 'から', 'kara', 'XÁC', 'vỏ trứng, thu mình trong chiếc vỏ', 17, '糸 -> 壳 -> 殳', '糸', '卵の殻 (たまごのから: vỏ trứng)、殻に閉じこもる (からにとじこもる: thu mình trong chiếc vỏ)、貝殻 (かいがら: vỏ sò, vỏ trai)、地殻 (ちかく: vỏ trái đất)', '卵の殻（たまごのから）', 'tamagonokara', 'vỏ trứng', 'N1', 'Chiết tự Hán Việt: XÁC (殻)', 'XÁC (壳) của binh khí (殳) chỉ còn là cái vỏ và áo giáp', '🍶', v_ch22_id, 12, '/assets/kanji/n1/illustrations/chap22_intro.webp', NOW())
