    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('俵', 'ダワラ, ョウ', '', 'dawara', 'BIỂU', 'bao gạo, 1 bao gạo', 17, '衤 -> 亻 -> 表', '衤', '米俵 (こめだわら: bao gạo)、米一俵 (べいいちたわら: 1 bao gạo)、相撲の土俵 (すもうのどひょう: võ đài sumo)', '米俵（こめだわら）', 'komedawara', 'bao gạo', 'N1', 'Chiết tự Hán Việt: BIỂU (俵)', 'Người ( 亻) bỏ cái Biểu ( áo 表) vào cái BIỂU ( bao 俵)', '🍶', v_ch22_id, 13, '/assets/kanji/n1/illustrations/chap22_intro.webp', NOW())
