    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('升', 'マス', 'ます', 'masu', 'THĂNG', 'đo bằng đơn vị shou/masu (1, uống 1 shou rượu', 14, '十 -> 千', '十', '升で量る (ますではかる: đo bằng đơn vị shou/masu (1,804 lít))、酒を一升飲む (さけをいっしょうのむ: uống 1 shou rượu)、一升瓶 (いっしょうびん: 1 bình/ 1 chai 1,804 lít)、升席 (ますせき: khán đài trong trận sumo)', '升で量る（ますではかる）', 'masudehakaru', 'đo bằng đơn vị shou/masu (1,804 lít)', 'N1', 'Chiết tự Hán Việt: THĂNG (升)', 'Chi 10(十) nghìn (千) yên sẽ được THĂNG chức', '🍶', v_ch22_id, 15, '/assets/kanji/n1/illustrations/chap22_intro.webp', NOW())
