    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('煎', 'セン', 'い.る, せん.じて', 'iru', 'TIÊN', 'rán trứng, trà xanh của nhật', 17, '金 -> 前 -> 灬', '金', '卵を煎る (たまごをいる: rán trứng)、煎茶 (せんちゃ: trà xanh của nhật)、薬を煎じて飲む (くすりをせんじてのむ: sắc thuốc rồi uống)', '卵を煎る（たまごをいる）', 'tamagooiru', 'rán trứng', 'N1', 'Chiết tự Hán Việt: TIÊN (煎)', 'lấy tiền ( 前) nhóm lửa (灬) thì cảm giác sướng như TIÊN', '🍶', v_ch22_id, 18, '/assets/kanji/n1/illustrations/chap22_intro.webp', NOW())
