    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('餅', 'ベイ, ペイ', 'もち', 'mochi', 'BÍNH', 'bánh dày, bánh gạo', 14, '食 -> 并', '食', '餅 (もち: bánh dày)、煎餅 (せんべい: bánh gạo)、月餅 (げっぺい: bánh trung thu)、餅肌 (もちはだ: làn da trắng mịn màng)', '餅（もち）', 'mochi', 'bánh dày', 'N1', 'Chiết tự Hán Việt: BÍNH (餅)', 'Yêu Tinh (并) ăn trộm bánh giày ô BÍNH', '🍶', v_ch22_id, 19, '/assets/kanji/n1/illustrations/chap22_intro.webp', NOW())
