    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('衷', 'チュウ, ュウ', '', 'chuu', 'TRUNG', 'cảm tạ từ trong thâm tâm, đồng cảm với nỗi đau trong lòng', 17, '亻 -> 衣 -> 十', '亻', '衷心から感謝する (ちゅうしんからかんしゃする: cảm tạ từ trong thâm tâm)、苦衷を察する (くちゅうをさっする: đồng cảm với nỗi đau trong lòng)、折衷する (せっちゅうする: pha trộn)、折衷案を出す (せっちゅうあんをだす: đưa ra đề xuất thỏa hiệp)', '衷心から感謝する（ちゅうしんからかんしゃする）', 'chuushinkarakanshasuru', 'cảm tạ từ trong thâm tâm', 'N1', 'Chiết tự Hán Việt: TRUNG (衷)', 'người mặc áo (衣) quan luôn TRUNG thành, hỏi 10 (十)lần cũng không khai', '🍶', v_ch22_id, 24, '/assets/kanji/n1/illustrations/chap22_intro.webp', NOW())
