    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('蹴', 'シュウ', 'け.る', 'keru', 'XÚC', 'đá bóng, đánh bại đối thủ', 14, '足 -> 就', '足', 'ボールを蹴る (ボールをける: đá bóng)、ライバルを蹴落とす (ライバルをけおとす: đánh bại đối thủ)、一蹴する (いっしゅうする: hạ đo ván)、蹴球 (しゅうきゅう: bóng đá)', 'ボールを蹴る（ボールをける）', 'bo-ruokeru', 'đá bóng', 'N1', 'Chiết tự Hán Việt: XÚC (蹴)', 'Túc lấy Chân (足 ) XÚC bóng cho Tựu (就)', '🔥', v_ch23_id, 5, '/assets/kanji/n1/illustrations/chap23_intro.webp', NOW())
