    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('狙', 'ソ', 'ねら.う, ねら.い', 'nerau', 'THƯ', 'nhắm vào con mồi, bây giờ là cơ hội đó', 17, '目 -> 且 -> 犭', '目', '獲物を狙う (えものをねらう: nhắm vào con mồi)、今が狙い目だ (いまがねらいめだ: bây giờ là cơ hội đó)、狙いを定める (ねらいをさだめる: xác định mục tiêu)、狙撃する (そげきする: bắn tỉa)', '獲物を狙う（えものをねらう）', 'emonoonerau', 'nhắm vào con mồi', 'N1', 'Chiết tự Hán Việt: THƯ (狙)', 'Thả (且) chó (犭) đi dạo rất THƯ  thái nhưng MỤC TIÊU là đi ngắm gái', '🔥', v_ch23_id, 6, '/assets/kanji/n1/illustrations/chap23_intro.webp', NOW())
