    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('傍', 'ボウ', 'かたわ.ら', 'katawara', 'BÀNG', 'bên cạnh, thờ ơ trước sự bắt nạt', 17, '亻 -> 立 -> 方', '亻', '傍ら (かたわら: bên cạnh)、いじめを傍観する (いじめをぼうかんする: thờ ơ trước sự bắt nạt)、傍線を引く (ぼうせんをひく: kẻ đường gạch dọc)、傍若無人な振る舞い (ぼうじゃくぶじんなふるまい: hành vi kiêu ngạo)', '傍ら（かたわら）', 'katawara', 'bên cạnh', 'N1', 'Chiết tự Hán Việt: BÀNG (傍)', 'nhân ( 亻) đứng (立) Cạnh Phương (方) BÀNG hoàng không biết nói gì', '🔥', v_ch23_id, 9, '/assets/kanji/n1/illustrations/chap23_intro.webp', NOW())
