    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('鎮', 'チン', 'しず.まる', 'shizumaru', 'TRẤN', 'cơn đau giảm, đàn áp cuộc nội chiến', 17, '足 -> 真 -> 金', '足', '痛みが鎮まる (いたみがしずまる: cơn đau giảm)、内乱を鎮まる (ないらんをしずまる: đàn áp cuộc nội chiến)、デモを鎮圧する (デモをちんあつする: đàn áp cuộc biểu tình)、鎮静剤 (ちんせいざい: thuốc an thần)', '痛みが鎮まる（いたみがしずまる）', 'itamigashizumaru', 'cơn đau giảm', 'N1', 'Chiết tự Hán Việt: TRẤN (鎮)', 'TRẤN áp người chân (真  ) chính bằng tiền (金)', '🔥', v_ch23_id, 10, '/assets/kanji/n1/illustrations/chap23_intro.webp', NOW())
