    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('窮', 'キュウ', 'きわ.める', 'kiwameru', 'CÙNG', 'tiến thoái lưỡng nan, rơi vào tình trạng chán chường', 17, '弓 -> 身 -> 穴', '弓', '進退窮まる (しんたいきわまる: tiến thoái lưỡng nan)、退屈窮まる (たいくつきわまる: rơi vào tình trạng chán chường)、困難を窮める (こんなんをきわめる: rơi vào tình cảnh khó khăn)、窮屈な服 (きゅうくつなふく: quần áo chật, kích)', '進退窮まる（しんたいきわまる）', 'shintaikiwamaru', 'tiến thoái lưỡng nan', 'N1', 'Chiết tự Hán Việt: CÙNG (窮)', 'Bắn cung (弓) vào thân (身), chết nằm dưới huyệt (穴) sâu tận CÙNG', '🔥', v_ch23_id, 11, '/assets/kanji/n1/illustrations/chap23_intro.webp', NOW())
