    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('堪', 'タエ', 'た.える, た.えない', 'taeru', 'KHAM', 'chịu đựng, lời nói xấu không đáng để nghe', 14, '土 -> 甚', '土', '堪える (たえる: chịu đựng, nhẫn nhịn)、聞くに堪えない悪口 (きくにたえないわるくち: lời nói xấu không đáng để nghe)、憤慨に堪えない (ふんがいにたえない: không chịu nổi phẫn uất)', '堪える（たえる）', 'taeru', 'chịu đựng, nhẫn nhịn', 'N1', 'Chiết tự Hán Việt: KHAM (堪)', 'Để có mảnh đất (土) thậm (甚) chí phải cam chịu sự KHAM khổ từ gần 4 phía', '🔥', v_ch23_id, 12, '/assets/kanji/n1/illustrations/chap23_intro.webp', NOW())
