    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('漏', 'マモ, ロウ', 'も.る, も.れる', 'moru', 'LẬU', 'nước mưa rỉ xuống từ trần nhà, vết dột nước mưa', 17, '門 -> 尸 -> 雨', '門', '天井から雨が漏る (てんじょうからあめがもる: nước mưa rỉ xuống từ trần nhà)、雨漏り (あまもり: vết dột nước mưa)、ガスが漏れる (ガスがすがもれる: rò rỉ khí ga)、ため息を漏らす (ためいきをもらす: buông tiếng thở dài)', '天井から雨が漏る（てんじょうからあめがもる）', 'tenjoukaraamegamoru', 'nước mưa rỉ xuống từ trần nhà', 'N1', 'Chiết tự Hán Việt: LẬU (漏)', 'Có cái Cửa (尸) mới Mưa (雨) cái đã rò rỉ nước ( 氵) đúng là hàng LẬU', '🔥', v_ch23_id, 20, '/assets/kanji/n1/illustrations/chap23_intro.webp', NOW())
