    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('擁', 'ヨウ', '', 'you', 'ỦNG', 'ôm đứa trẻ, bảo hộ quyền con người', 14, '雍 -> 扌', '雍', '子供を抱擁する (こどもをほうようする: ôm đứa trẻ)、人権を擁護する (じんけんをようごする: bảo hộ quyền con người)、擁立する (ようりつする: ủng hộ)', '子供を抱擁する（こどもをほうようする）', 'kodomoohouyousuru', 'ôm đứa trẻ', 'N1', 'Chiết tự Hán Việt: ỦNG (擁)', 'Ung(雍) dung giơ Tay(扌) lên Ủng hộ', '🔥', v_ch23_id, 21, '/assets/kanji/n1/illustrations/chap23_intro.webp', NOW())
