    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('詮', 'セン', 'せん.ずる', 'senzuru', 'THUYÊN', 'đến cuối cùng, giấc mơ cuối cùng cũng không thành hiện thực', 14, '言 -> 全', '言', '詮ずる所、責任は自分にある (せんずるところ、せきにんはじぶんにある: đến cuối cùng, trách nhiệm là ở bản thân mỗi người)、所詮かなわぬ夢 (しょせんかなわぬゆめ: giấc mơ cuối cùng cũng không thành hiện thực)', '詮ずる所、責任は自分にある（せんずるところ、せきにんはじぶんにある）', 'senzurutokorosekininhajibunniaru', 'đến cuối cùng, trách nhiệm là ở bản thân mỗi người', 'N1', 'Chiết tự Hán Việt: THUYÊN (詮)', 'nói (言) toàn (全) chuyện luyên THUYÊN mà lại kĩ càng', '🔥', v_ch23_id, 22, '/assets/kanji/n1/illustrations/chap23_intro.webp', NOW())
