    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('遡', 'シャ', 'さかのぼ.る', 'sakanoboru', 'TỐ', 'cá hồi bay ngược dòng sông, quay trở về lịch sử', 14, '月 -> 逆', '月', '鮭が川を遡る (しゃけがかわをさかのぼる: cá hồi bay ngược dòng sông)、歴史を遡る (れきしをさかのぼる: quay trở về lịch sử)、遡及適用する (そきゅうてきようする: áp dụng luật hồi tố)', '鮭が川を遡る（しゃけがかわをさかのぼる）', 'shakegakawaosakanoboru', 'cá hồi bay ngược dòng sông', 'N1', 'Chiết tự Hán Việt: TỐ (遡)', 'Chị nguyệt （月）leo (のぼる）dốc (さか）ngược lại ( 逆） đầy bão TỐ', '🔥', v_ch23_id, 23, '/assets/kanji/n1/illustrations/chap23_intro.webp', NOW())
