    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('悼', 'トウ', 'いた.む', 'itamu', 'ĐIỆU', 'đau buồn trước cái chết của người bạn thân, gửi lời chia buồn', 14, '忄 -> 卓', '忄', '友の死を悼む (とものしをいたむ: đau buồn trước cái chết của người bạn thân)、哀悼の意を表する (あいとうのいをひょうする: gửi lời chia buồn)、追悼の辞を述べる (ついとうのじをのべる: bày tỏ sự tưởng nhớ)', '友の死を悼む（とものしをいたむ）', 'tomonoshioitamu', 'đau buồn trước cái chết của người bạn thân', 'N1', 'Chiết tự Hán Việt: ĐIỆU (悼)', 'con tim (忄) truy ĐIỆU trên bàn ( 卓)', '🔥', v_ch23_id, 25, '/assets/kanji/n1/illustrations/chap23_intro.webp', NOW())
