    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('銘', 'メイ', 'めい', 'mei', 'MINH', 'khắc ghi lời dạy vào trong tim, làm cho cảm động', 14, '金 -> 名', '金', '教えを心に銘記する (おしえをこころにめいきする: khắc ghi lời dạy vào trong tim)、感銘を受ける (かんめいをうける: làm cho cảm động, ấn tượng sâu sắc)、座右の銘 (ざゆうのめい: châm ngôn sống)、銘柄品 (めいがらひん: sản phảm có thương hiệu)', '教えを心に銘記する（おしえをこころにめいきする）', 'oshieokokoronimeikisuru', 'khắc ghi lời dạy vào trong tim', 'N1', 'Chiết tự Hán Việt: MINH (銘)', 'Có tiền (金) có danh ( 名) ắt sẽ văn MINH', '🔥', v_ch23_id, 27, '/assets/kanji/n1/illustrations/chap23_intro.webp', NOW())
