    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('葛', 'ク', 'くず', 'kuzu', 'CÁT', 'uống bột sắn dây, sắn dây', 17, '木 -> 艹 -> 匂', '木', '葛湯を飲む (くずゆをのむ: uống bột sắn dây)、葛 (くず: sắn dây)', '葛湯を飲む（くずゆをのむ）', 'kuzuyuonomu', 'uống bột sắn dây', 'N1', 'Chiết tự Hán Việt: CÁT (葛)', 'Sắn dây 葛 là một loại cây(艹) không mùi (匂), cần ánh sáng mặt trời (日) được trồng trên đất CÁT', '🔥', v_ch23_id, 28, '/assets/kanji/n1/illustrations/chap23_intro.webp', NOW())
