    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('萎', 'イシ', 'な.える', 'naeru', 'NUY', 'lá xanh trở nên yếu đuối, cảm thấy yếu đuối', 17, '木 -> 艹 -> 委', '木', '青葉が萎える (あおばがなえる: lá xanh trở nên yếu đuối)、気持ちが萎える (きもちがなえる: cảm thấy yếu đuối)、萎縮する (いしゅくする: co rúm lại)', '青葉が萎える（あおばがなえる）', 'aobaganaeru', 'lá xanh trở nên yếu đuối', 'N1', 'Chiết tự Hán Việt: NUY (萎)', 'bà Thảo (艹 )  đã Ủy (委) quyền việc trồng Lúa cho đứa Con gái tên NUY . do không có khinh nghiệm đã làm cây lúa HÉO KHÔ', '🔥', v_ch23_id, 29, '/assets/kanji/n1/illustrations/chap23_intro.webp', NOW())
