    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('嘲', 'チョウ', 'あざけ.る', 'azakeru', 'TRÀO', 'chế giễu thất bại của người khác, cười nhạo', 17, '亻 -> 朝 -> 口', '亻', '人の失敗を嘲る (ひとのしっぱいをあざける: chế giễu thất bại của người khác)、嘲笑 (ちょうしょう: cười nhạo)、自嘲気味 (じちょうぎみ: tự chế nhạo chính mình)', '人の失敗を嘲る（ひとのしっぱいをあざける）', 'hitonoshippaioazakeru', 'chế giễu thất bại của người khác', 'N1', 'Chiết tự Hán Việt: TRÀO (嘲)', 'thạt là tức TRÀO máu mới sáng ( 朝) ra đã mở mồm (口) nhạo báng người khác', '🔥', v_ch23_id, 32, '/assets/kanji/n1/illustrations/chap23_intro.webp', NOW())
