    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('呪', 'ジュ', 'のろ.う, のろ.われた', 'norou', 'CHÚ', 'nguyền rủa người khác, số phận đã bị nguyền rủa', 14, '口 -> 兄', '口', '人を呪う (ひとをのろう: nguyền rủa người khác)、呪われた運命 (のろわれたうんめい: số phận đã bị nguyền rủa)、呪縛 (じゅばく: lời nguyền)、呪文を唱える (じゅもんをとなえる: đọc câu thần chú)', '人を呪う（ひとをのろう）', 'hitoonorou', 'nguyền rủa người khác', 'N1', 'Chiết tự Hán Việt: CHÚ (呪)', 'Mồm (口) huynh (兄) đọc thần CHÚ', '🔥', v_ch23_id, 34, '/assets/kanji/n1/illustrations/chap23_intro.webp', NOW())
