    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('蔑', 'ベツ, ベッ', 'さげす.む, さげす.むような', 'sagesumu', 'MIỆT', 'coi thường đối phương, ánh mắt như đang khinh thường', 17, '亻 -> 艹 -> 目', '亻', '相手を蔑む (あいてをさげすむ: coi thường đối phương)、蔑むような目つき (さげすむようなめつき: ánh mắt như đang khinh thường)、軽蔑する (けいべつする: khinh miệt, khinh thường)、蔑視 (べっし: khinh miệt)', '相手を蔑む（あいてをさげすむ）', 'aiteosagesumu', 'coi thường đối phương', 'N1', 'Chiết tự Hán Việt: MIỆT (蔑)', 'cô giáo Thảo (艹) có ánh mắt (目) MIỆT thị người thành (成) công', '🔥', v_ch23_id, 35, '/assets/kanji/n1/illustrations/chap23_intro.webp', NOW())
