    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('罵', 'バ', 'ののし.る', 'nonoshiru', 'MẠ', 'chửi mắng, chửi rủa', 14, '馬 -> 罒', '馬', '口汚く罵る (くちぎたなくののしる: chửi mắng, lăng mạ)、罵倒する (ばとうする: chửi rủa)、罵声を浴びせる (ばせいをあびせる: bị cười nhạo, chửi mắng té tát)、罵詈雑言 (ばりぞうごん: phỉ báng, chửi thề)', '口汚く罵る（くちぎたなくののしる）', 'kuchigitanakunonoshiru', 'chửi mắng, lăng mạ', 'N1', 'Chiết tự Hán Việt: MẠ (罵)', 'con Ngựa ( 馬) đi mà đánh Võng (罒) thì sẽ bị lăng MẠ', '🔥', v_ch23_id, 36, '/assets/kanji/n1/illustrations/chap23_intro.webp', NOW())
