    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('浪', 'ロウ', '', 'rou', 'LÃNG', 'cảnh báo sóng lớn trên biển, đi phượt', 17, '忄 -> 良 -> 氵', '忄', '波浪注意報 (はろうちゅういほう: cảnh báo sóng lớn trên biển)、放浪の旅に出る (ほうろうのたびにでる: đi phượt, đi du lịch bụi)、流浪の民 (るろうのたみ: những người sống lang thang)、浪人する (ろうにんする: vô công rồi nghề)', '波浪注意報（はろうちゅういほう）', 'harouchuuihou', 'cảnh báo sóng lớn trên biển', 'N1', 'Chiết tự Hán Việt: LÃNG (浪)', 'Người có Lương (良) tâm thì không LÃNG Phí Nước ( 氵)', '🌊', v_ch24_id, 5, '/assets/kanji/n1/illustrations/chap24_intro.webp', NOW())
