    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('潜', 'ミズ', 'もぐ.る, ひそ.む', 'moguru', 'TIỀM', 'trốn dưới nước, ẩn nấp trong vỏ bọc', 17, '夫 -> 氵 -> 日', '夫', '水の中に潜る (みずのなかにもぐる: trốn dưới nước)、物陰に潜む (ものかげにひそむ: ẩn nấp trong vỏ bọc)、潜入捜査 (せんにゅうそうさ: điều tra thâm nhập)、潜在的な力 (せんざいてきなちから: năng lực tiềm ẩn)', '水の中に潜る（みずのなかにもぐる）', 'mizunonakanimoguru', 'trốn dưới nước', 'N1', 'Chiết tự Hán Việt: TIỀM (潜)', '2 ông chồng (夫) đứng cùng nhau dưới nước ( 氵) Cả ngày ( 日) TIỀM ẩn nhiều nguy cơ', '🌊', v_ch24_id, 6, '/assets/kanji/n1/illustrations/chap24_intro.webp', NOW())
