    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('帆', 'ハン', 'ほ', 'ho', 'PHÀM', 'căng buồm lên, thuyền buồm', 14, '巾 -> 凡', '巾', '帆を上げる (ほをあげる: căng buồm lên)、帆船 (はんせん: thuyền buồm)、順風満帆 (じゅんぷうまんぱん: thuận buồm xuôi gió)', '帆を上げる（ほをあげる）', 'hooageru', 'căng buồm lên', 'N1', 'Chiết tự Hán Việt: PHÀM (帆)', 'PHÀM thì cánh buồm được làm từ vải (巾)thường (凡)', '🌊', v_ch24_id, 7, '/assets/kanji/n1/illustrations/chap24_intro.webp', NOW())
