    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('墜', 'ツイ', '', 'tsui', 'TRỤY', 'máy bay rơi, lòng tin bị đánh mất', 17, '弓 -> 隊 -> 土', '弓', '飛行機が墜落する (ひこうきがついらくする: máy bay rơi)、信用が失墜する (しんようがしっついする: lòng tin bị đánh mất)、ミサイルを撃墜する (ミサイルをげきついする: bắn rơi tên lửa)', '飛行機が墜落する（ひこうきがついらくする）', 'hikoukigatsuirakusuru', 'máy bay rơi', 'N1', 'Chiết tự Hán Việt: TRỤY (墜)', 'Đội (隊) quân TRỤY lạc bị bắn rơi xuống Đất (土)', '🌊', v_ch24_id, 14, '/assets/kanji/n1/illustrations/chap24_intro.webp', NOW())
