    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('飢', 'ショ', 'う.える', 'ueru', 'CƠ', 'đói khát vì thiếu lương thực, khát khao tình yêu thương', 17, '月 -> 飠 -> 几', '月', '食料がなくて飢える (しょくりょうがなくてうえる: đói khát vì thiếu lương thực)、愛情に飢える (あいじょうにうえる: khát khao tình yêu thương)、大飢饉が起こる (だいききんがおこる: nạn đói trầm trọng xảy ra)', '食料がなくて飢える（しょくりょうがなくてうえる）', 'shokuryouganakuteueru', 'đói khát vì thiếu lương thực', 'N1', 'Chiết tự Hán Việt: CƠ (飢)', 'CƠ thể đói quá ăn (飠) luôn cả Ghế (几)', '🌊', v_ch24_id, 15, '/assets/kanji/n1/illustrations/chap24_intro.webp', NOW())
