    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('遍', 'ヘン', '', 'hen', 'BIẾN ( Cửa (戸) hiệu Sách 9 冊) có mặt khắp nơi trên Đường (辶)rất', 'tính phổ biến, đi lang thang khắp nơi', 17, '門 -> 戸 -> 冊', '門', '普遍的 (ふへんてき: tính phổ biến)、遍歴する (へんれきする: đi lang thang khắp nơi)、何遍言ったらわかるだろう (なんべんいったらわかるだろう: nếu nói nhiều lần như vậy rồi thì tôi đã hiểu)', '普遍的（ふへんてき）', 'fuhenteki', 'tính phổ biến', 'N1', 'Chiết tự Hán Việt: BIẾN ( Cửa (戸) hiệu Sách 9 冊) có mặt khắp nơi trên Đường (辶)rất (遍)', 'BIẾN ( Cửa (戸) hiệu Sách 9 冊) có mặt khắp nơi trên Đường (辶)rất', '✨', v_ch25_id, 10, '/assets/kanji/n1/illustrations/chap25_intro.webp', NOW())
