    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('顕', 'ケン', '', 'ken', 'HIỂN', 'nổi bật, hiện thực háo', 17, '頁 -> 日 -> 並', '頁', '顕著 (けんちょ: nổi bật)、顕在化する (けんざいかする: hiện thực háo)、自己顕示欲 (じこけんじよく: tự cao, thích thể hiện)、顕微鏡 (けんびきょう: kính hiển vi)', '顕著（けんちょ）', 'kencho', 'nổi bật', 'N1', 'Chiết tự Hán Việt: HIỂN (顕)', 'HIỂN hiện rõ trong đầu (頁)rằng mỗi ngày (日) đều cần phải xếp hàng(並)', '✨', v_ch25_id, 17, '/assets/kanji/n1/illustrations/chap25_intro.webp', NOW())
