    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('璧', 'ペキ, ヘキ', '', 'peki', 'BÍCH', 'diễn xuất hoàn hảo, hoàn thành 1 cách hoàn hảo', 17, '王 -> 土 -> 壁', '王', '完璧な演技 (かんぺきなえんぎ: diễn xuất hoàn hảo)、完璧に仕上げる (かんぺきにしあげる: hoàn thành 1 cách hoàn hảo)、双璧 (そうへき: cặp đôi ngang tài ngang sức)', '完璧な演技（かんぺきなえんぎ）', 'kanpekinaengi', 'diễn xuất hoàn hảo', 'N1', 'Chiết tự Hán Việt: BÍCH (璧)', 'Bích (壁) tường bỏ thổ thêm Ngọc là ngọc BÍCH (璧) hoàn hảo', '✨', v_ch25_id, 19, '/assets/kanji/n1/illustrations/chap25_intro.webp', NOW())
