    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('唾', 'ダ', 'つば', 'tsuba', 'THÓA', 'nuốt nước bọt, nước bọt', 17, '氵 -> 垂 -> 口', '氵', '唾を飲み込む (つばをのみこむ: nuốt nước bọt)、唾液 (だえき: nước bọt)、眉唾物 (まゆつばもの: đồ giả,không đáng tin)', '唾を飲み込む（つばをのみこむ）', 'tsubaonomikomu', 'nuốt nước bọt', 'N1', 'Chiết tự Hán Việt: THÓA (唾)', 'Trông Thùy ( 垂 ) mị mà mở Miệng ( 口 ) là THÓA ( 唾 ) mạ văng NƯỚC BỌT', '🧬', v_ch26_id, 11, '/assets/kanji/n1/illustrations/chap26_intro.webp', NOW())
