    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('拳', 'ケン', 'こぶし', 'kobushi', 'QUYỀN', 'nắm đấm, môn võ kenpo', 17, '扌 -> 手 -> 二', '扌', '握り拳 (にぎりこぶし: nắm đấm)、拳法 (けんぽう: môn võ kenpo)、拳銃 (けんじゅう: khẩu súng lục)、太極拳 (たいきょくけん: môn võ Thái cực quyền)', '握り拳（にぎりこぶし）', 'nigirikobushi', 'nắm đấm', 'N1', 'Chiết tự Hán Việt: QUYỀN (拳)', 'có QUYỀN (拳) dùng tay (手) để đấm người đã gây ra 2 ( 二) vụ hỏa  (火)  hoạn', '🧬', v_ch26_id, 12, '/assets/kanji/n1/illustrations/chap26_intro.webp', NOW())
