    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('股', 'マタ, マ', '', 'mata', 'CỔ', 'sải bước đi, xoạc chân', 14, '月 -> 殳', '月', '大股で歩く (おおまたであるく: sải bước đi)、股割り (またわり: xoạc chân)、二股をかける (ふたまたをかける: bắt cá 2 tay)、股関節が痛い (こかんせつがいたい: đau khớp háng)', '大股で歩く（おおまたであるく）', 'oomatadearuku', 'sải bước đi', 'N1', 'Chiết tự Hán Việt: CỔ (股)', 'CỔ của Nguyệt (月) to bằng đùi nên làm kẻ Thù (殳) khiếp sợ', '🧬', v_ch26_id, 13, '/assets/kanji/n1/illustrations/chap26_intro.webp', NOW())
