    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('癒', 'ユチ', 'い.える, いや.す', 'ieru', 'DŨ', 'phục hồi sang chấn tâm lý, giải khát', 17, '忄 -> 前 -> 疒', '忄', '心の傷が癒える (こころのきずがいえる: phục hồi sang chấn tâm lý)、喉の渇きを癒す (のどのかわきをいやす: giải khát)、病気が治癒する (びょうきがちゆする: điều trị bệnh)、手術の跡が癒着する (しゅじゅつのあとがゆちゃくする: để lại sẹo sau phẫu thuật)', '心の傷が癒える（こころのきずがいえる）', 'kokoronokizugaieru', 'phục hồi sang chấn tâm lý', 'N1', 'Chiết tự Hán Việt: DŨ (癒)', 'Trước (前) khi chữa Bệnh (疒) phải chữa lành (癒) con tim(心) đang ủ DŨ', '🧬', v_ch26_id, 15, '/assets/kanji/n1/illustrations/chap26_intro.webp', NOW())
