        (v_ch_id, '和気藹々', 'わきあいあい', 'wakiaiai', 'Hòa khí ái ái (bầu không khí đầm ấm hòa thuận)', 'Harmonious and friendly atmosphere', 129, NOW()),
        (v_ch_id, '半信半疑', 'はんしんはんぎ', 'hanshinhangi', 'Bán tín bán nghi (nửa tin nửa ngờ)', 'Half in doubt', 130, NOW()),
        (v_ch_id, '心機一転', 'しんきいってん', 'shinkiitten', 'Tâm cơ nhất chuyển (đổi mới tâm thế)', 'Turning over a new leaf', 131, NOW()),
        (v_ch_id, '弱者を愚弄する', 'じゃくしゃをぐろうする', 'moteasobu', 'chế giễu người yếu đuối', 'LỘNG — chế giễu người yếu đuối', 132, NOW()),
        (v_ch_id, '運命に翻弄される', 'うんめいにほんろうされる', 'moteasobu', 'chịu sự đùa giỡn của số phận', 'LỘNG — chịu sự đùa giỡn của số phận', 133, NOW()),
        (v_ch_id, '憧憬を抱く', 'どうけいをだく', 'kei', 'ấp ủ khát vọng', 'CẢNH — ấp ủ khát vọng', 134, NOW()),
        (v_ch_id, '名誉毀損', 'めいよきそん', 'mei', 'phỉ báng/ tổn hại danh dự', 'HỦY — phỉ báng/ tổn hại danh dự', 135, NOW()),
        (v_ch_id, '証拠隠蔽', 'しょうこいんぺい', 'sho', 'che giấu bằng chứng', 'TẾ — che giấu bằng chứng', 136, NOW()),
        (v_ch_id, '憂鬱', 'ゆううつ', 'tsu', 'khu rừng rậm rạp', 'UẤT — khu rừng rậm rạp', 137, NOW()),
        (v_ch_id, '肥沃な土地', 'ひよくなとち', 'yoku', 'đất đai màu mỡ', 'ỐC — đất đai màu mỡ', 138, NOW()),
        (v_ch_id, '人格を陶冶する', 'じんかくをとうやする', 'ya', 'tu dưỡng, giáo dục nhân cách', 'DÃ — tu dưỡng, giáo dục nhân cách', 139, NOW()),
        (v_ch_id, '貨幣を鋳造する', 'かへいをちゅうぞうする', 'iru', 'đúc tiền', 'CHÚ — đúc tiền', 140, NOW()),
        (v_ch_id, '粘土で作られた塑像', 'ねんどでつくられたそぞう', 'so', 'bức tượng được làm bằng đất sét', 'TỐ — bức tượng được làm bằng đất sét', 141, NOW()),
        (v_ch_id, '悪戦苦闘', 'あくせんくとう', 'akusenkutou', 'Ác chiến khổ đấu (chiến đấu gian khổ)', 'Hard-fought struggle', 142, NOW()),
        (v_ch_id, '暗中模索', 'あんちゅうもさく', 'anchuumosaku', 'Ám trung mô tác (mò mẫm trong bóng tối)', 'Groping in the dark', 143, NOW()),
        (v_ch_id, '一網打尽', 'いちもうだじん', 'ichimoudajin', 'Nhất võng đả tận (bắt trọn một mẻ lưới)', 'Rounding up all at once', 144, NOW()),
        (v_ch_id, '試行錯誤', 'しこうさくご', 'shikousakugo', 'Thử hành sai ngộ (thử và sai)', 'Trial and error', 145, NOW()),
        (v_ch_id, '臨機応変', 'りんきおうへん', 'rinkiouhen', 'Lâm cơ ứng biến (tùy cơ ứng biến)', 'Adapting to circumstances', 146, NOW());
    END IF;
END $$;

-- 4. SEED 750 CÂU TRẮC NGHIỆM NGỮ CẢNH & ĐIỀN CHỮ (25 CÂU / CHƯƠNG)
DO $$
DECLARE v_ch_id BIGINT; BEGIN
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 1;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_exercises WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', '彼は、電話を切ると[慌ただしく]部屋を出ていった。', '慌ただしく', 'あわただしく', '["いそがしく", "さわがしく", "あわたしく", "あわただしく"]', 'Anh ấy vừa cúp điện thoại liền vội vàng hấp tấp bước ra khỏi phòng. — Từ「慌ただしく」trong câu đọc là「あわただしく」.', 1, NOW()),
        (v_ch_id, 'READING', '人が話しているのに、彼はそれを[遮って]自分の話を始めた。', '遮って', 'さえぎって', '["とめて", "さえぎって", "さまたげて", "ふせいで"]', 'Dù người khác đang nói, anh ta vẫn cắt ngang để bắt đầu câu chuyện của mình. — Từ「遮って」trong câu đọc là「さえぎって」.', 2, NOW()),
        (v_ch_id, 'READING', '厳しい練習に[耐え]、見事チャンピオンの座を手に入れた。', '耐え', 'たえ', '["かかえ", "こらえ", "たえ", "そなえ"]', 'Chịu đựng quá trình tập luyện khắc nghiệt, anh đã xuất sắc giành được ngôi vô địch. — Từ「耐え」trong câu đọc là「たえ」.', 3, NOW()),
        (v_ch_id, 'READING', '健康志向を意識し、[添加物]を使用していない食品が増えている。', '添加物', 'てんかぶつ', '["ふかぶつ", "てんかぶつ", "そうかぶつ", "てんこうぶつ"]', 'Ý thức được xu hướng sống khỏe, ngày càng có nhiều thực phẩm không sử dụng chất phụ gia. — Từ「添加物」trong câu đọc là「てんかぶつ」.', 4, NOW()),
        (v_ch_id, 'READING', '緊急着陸のアナウンスが流れ、乗客に[動揺]が広がった。', '動揺', 'どうよう', '["どうこう", "どうよう", "しんどう", "ようどう"]', 'Thông báo hạ cánh khẩn cấp vang lên khiến sự hoang mang dao động lan rộng среди hành khách. — Từ「動揺」trong câu đọc là「どうよう」.', 5, NOW()),
        (v_ch_id, 'READING', 'パソコンの[操作]マニュアルを見ながら、初期設定を行う。', '操作', 'そうさ', '["ちょうさ", "そうさ", "そうさく", "しょうさ"]', 'Vừa xem sách hướng dẫn thao tác máy tính vừa tiến hành cài đặt ban đầu. — Từ「操作」trong câu đọc là「そうさ」.', 6, NOW()),
        (v_ch_id, 'READING', '理不尽な要求に対し、怒りを[抑えて]冷静に対応した。', '抑えて', 'おさえて', '["とらえて", "おさえて", "かかえて", "ひかえて"]', 'Trước yêu cầu vô lý, tôi đã kìm nén cơn giận và ứng phó một cách bình tĩnh. — Từ「抑えて」trong câu đọc là「おさえて」.', 7, NOW()),
        (v_ch_id, 'READING', '二人組の男が店に押し入り、[略奪]をはたらく。', '略奪', 'りゃくだつ', '["りゃくばつ", "しんりゃく", "ごうだつ", "りゃくだつ"]', 'Hai gã đàn ông xông vào cửa hàng thực hiện hành vi cướp bóc. — Từ「略奪」trong câu đọc là「りゃくだつ」.', 8, NOW()),
        (v_ch_id, 'READING', '今回[活躍]を期待されているのは、前大会で優勝した細田選手だ。', '活躍', 'かつやく', '["かつやく", "ひやく", "かつどう", "ちょうやく"]', 'Người được kỳ vọng sẽ tỏa sáng lần này là tuyển thủ Hosoda, nhà vô địch giải trước. — Từ「活躍」trong câu đọc là「かつやく」.', 9, NOW()),
        (v_ch_id, 'READING', '電車内の携帯電話使用を迷惑[行為]だと感じている人は多い。', '行為', 'こうい', '["こうせい", "ぎょうい", "こうどう", "こうい"]', 'Nhiều người cảm thấy việc sử dụng điện thoại di động trên tàu điện là hành vi gây phiền toái. — Từ「行為」trong câu đọc là「こうい」.', 10, NOW()),
        (v_ch_id, 'READING', 'この店のシェフはフランスで修行を積み、腕を[磨いた]。', '磨いた', 'みがいた', '["はいた", "きずいた", "みがいた", "ぬぐいた"]', 'Đầu bếp của nhà hàng này đã tích lũy tu nghiệp ở Pháp và mài giũa tay nghề. — Từ「磨いた」trong câu đọc là「みがいた」.', 11, NOW()),
        (v_ch_id, 'READING', '被疑者が未成年である場合、名前は[伏せて]報道される。', '伏せて', 'ふせて', '["まかせて", "かくせて", "のせて", "ふせて"]', 'Trường hợp nghi phạm là người chưa thành niên, tên tuổi sẽ được giữ kín khi đưa tin. — Từ「伏せて」trong câu đọc là「ふせて」.', 12, NOW()),
        (v_ch_id, 'READING', '朝と晩の二回、この薬を患部に[塗って]ください。', '塗って', 'ぬって', '["はって", "もって", "ぬって", "ふって"]', 'Hãy bôi thuốc này lên vùng bị thương ngày hai lần sáng và tối. — Từ「塗って」trong câu đọc là「ぬって」.', 13, NOW()),
        (v_ch_id, 'READING', '過ちを反省し、もう二度と繰り返さないと心に[誓った]。', '誓った', 'ちかった', '["ねがった", "ちかった", "さとった", "いのった"]', 'Tôi tự kiểm điểm lỗi lầm và thề trong lòng sẽ không bao giờ tái phạm lần thứ hai. — Từ「誓った」trong câu đọc là「ちかった」.', 14, NOW()),
        (v_ch_id, 'READING', '家の近くを通る電車の音で安眠を[妨害]される。', '妨害', 'ぼうがい', '["そがい", "ぼうがい", "しんがい", "しょうがい"]', 'Giấc ngủ ngon bị cản trở bởi tiếng tàu điện chạy qua gần nhà. — Từ「妨害」trong câu đọc là「ぼうがい」.', 15, NOW()),
        (v_ch_id, 'WRITING', '農業の振興に力を[つくして]いくという彼の決意は固い。', 'つくして', '尽くして', '["着くして", "尽くして", "築くして", "付くして"]', 'Quyết tâm dốc hết sức mình để chấn hưng nông nghiệp của anh ấy rất vững vàng. — Từ「つくして」trong câu viết chữ Hán là「尽くして」.', 16, NOW()),
        (v_ch_id, 'WRITING', '会議が円滑にいくよう、問題の[しょうてん]を絞って進める。', 'しょうてん', '焦点', '["焦点", "笑点", "昇点", "商点"]', 'Để cuộc họp diễn ra suôn sẻ, chúng tôi thu hẹp trọng tâm (tiêu điểm) của vấn đề rồi mới tiến hành. — Từ「しょうてん」trong câu viết chữ Hán là「焦点」.', 17, NOW()),
        (v_ch_id, 'WRITING', '彼女の声が[はずんで]いた。何かいいことがあったのだろう。', 'はずんで', '弾んで', '["踏んで", "躍んで", "弾んで", "跳んで"]', 'Giọng cô ấy đầy hào hứng sôi nổi. Chắc là đã có chuyện gì tốt đẹp rồi. — Từ「はずんで」trong câu viết chữ Hán là「弾んで」.', 18, NOW()),
        (v_ch_id, 'WRITING', '彼は駅の改札を抜けると、都会の[ざっとう]にまぎれていった。', 'ざっとう', '雑踏', '["雑闘", "雑到", "雑踏", "雑倒"]', 'Vừa bước qua cửa soát vé nhà ga, anh ấy đã hòa lẫn vào đám đông nhộn nhịp của đô thị. — Từ「ざっとう」trong câu viết chữ Hán là「雑踏」.', 19, NOW()),
        (v_ch_id, 'WRITING', '合格には程遠いだろうが、難関校に[ちょうせん]するつもりだ。', 'ちょうせん', '挑戦', '["挑戦", "眺戦", "兆戦", "跳戦"]', 'Dù còn cách khá xa mức đỗ, tôi vẫn dự định thử thách thi vào trường top đầu. — Từ「ちょうせん」trong câu viết chữ Hán là「挑戦」.', 20, NOW()),
        (v_ch_id, 'WRITING', '部長は不注意による部下のミスを厳しく[しっせき]した。', 'しっせき', '叱責', '["質責", "失責", "室責", "叱責"]', 'Trưởng phòng nghiêm khắc khiển trách lỗi lầm do bất cẩn của cấp dưới. — Từ「しっせき」trong câu viết chữ Hán là「叱責」.', 21, NOW()),
        (v_ch_id, 'WRITING', '大雨で土砂崩れの恐れがあるため、近くの学校へ[ひなん]した。', 'ひなん', '避難', '["批難", "避難", "飛難", "非難"]', 'Do mưa lớn có nguy cơ sạt lở đất nên người dân đã sơ tán đến trường học gần đó. — Từ「ひなん」trong câu viết chữ Hán là「避難」.', 22, NOW()),
        (v_ch_id, 'WRITING', '新居はベランダからの[ながめ]が良くて気に入っている。', 'ながめ', '眺め', '["流め", "永め", "眺め", "長め"]', 'Tôi rất ưng ngôi nhà mới vì tầm nhìn ngắm cảnh từ ban công rất đẹp. — Từ「ながめ」trong câu viết chữ Hán là「眺め」.', 23, NOW()),
        (v_ch_id, 'WRITING', '息子が傷だらけで帰ってきたが、[だまった]まま何も言わない。', 'だまった', '黙った', '["止まった", "閉まった", "黙った", "困った"]', 'Con trai trở về nhà đầy vết thương nhưng cứ im lặng chẳng nói lời nào. — Từ「だまった」trong câu viết chữ Hán là「黙った」.', 24, NOW()),
        (v_ch_id, 'WRITING', 'おもちゃメーカーが発売予定の新型ゲーム機を[ひろう]した。', 'ひろう', '披露', '["疲労", "批露", "比露", "披露"]', 'Hãng đồ chơi đã công bố ra mắt máy chơi game thế hệ mới dự kiến phát hành. — Từ「ひろう」trong câu viết chữ Hán là「披露」.', 25, NOW()),
        (v_ch_id, 'WRITING', '会議できまりかけた案に、ただ一人課長が異議を[となえた]。', 'となえた', '唱えた', '["称えた", "備えた", "訴えた", "唱えた"]', 'Đối với phương án sắp được chốt trong cuộc họp, chỉ riêng tổ trưởng lên tiếng phản đối. — Từ「となえた」trong câu viết chữ Hán là「唱えた」.', 26, NOW()),
        (v_ch_id, 'WRITING', '今あなたに聞いた話は、口が[さけても]誰にも言いません。', 'さけても', '裂けても', '["裂けても", "欠けても", "開けても", "避けても"]', 'Chuyện vừa nghe bạn kể hôm nay, dù có bị xé miệng tôi cũng không nói với ai đâu. — Từ「さけても」trong câu viết chữ Hán là「裂けても」.', 27, NOW()),
        (v_ch_id, 'WRITING', 'この番組は意見の投稿によって[しちょうしゃ]も参加できる。', 'しちょうしゃ', '視聴者', '["試聴者", "視聴者", "支庁者", "市長者"]', 'Chương trình này cho phép khán giả truyền hình cùng tham gia bằng cách gửi ý kiến. — Từ「しちょうしゃ」trong câu viết chữ Hán là「視聴者」.', 28, NOW()),
        (v_ch_id, 'WRITING', 'やるからには目標を高く[かかげる]べきだ。', 'かかげる', '掲げる', '["揚げる", "掲げる", "挙げる", "上げる"]', 'Một khi đã làm thì nên đề ra mục tiêu thật cao. — Từ「かかげる」trong câu viết chữ Hán là「掲げる」.', 29, NOW()),
        (v_ch_id, 'WRITING', '彼は発言と行動が[ともなわない]ことがある。', 'ともなわない', '伴わない', '["伴わない", "友わない", "供わない", "共わない"]', 'Anh ta đôi khi lời nói không đi đôi với hành động. — Từ「ともなわない」trong câu viết chữ Hán là「伴わない」.', 30, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 2;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_exercises WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', '岸さんは電車でお年寄りに席を[譲る]ような優しい人だ。', '譲る', 'ゆずる', '["たすける", "ゆずる", "まもる", "ゆだねる"]', 'Anh Kishi là người hiền hậu, luôn nhường ghế cho người già trên tàu điện. — Từ「譲る」trong câu đọc là「ゆずる」.', 1, NOW()),
        (v_ch_id, 'READING', '毎晩、隣の部屋からテレビの音が聞こえてきて[迷惑]だ。', '迷惑', 'めいわく', '["ゆうわく", "こんわく", "めいわく", "ぎわく"]', 'Mỗi tối tiếng tivi từ phòng bên cạnh vọng sang thật sự gây phiền phức. — Từ「迷惑」trong câu đọc là「めいわく」.', 2, NOW()),
        (v_ch_id, 'READING', 'インフルエンザが流行しているため、クラス全員に注意を[促した]。', '促した', 'うながした', '["うごかした", "のこした", "さとした", "うながした"]', 'Do dịch cúm đang bùng phát nên giáo viên đã nhắc nhở thúc giục cả lớp chú ý phòng tránh. — Từ「促した」trong câu đọc là「うながした」.', 3, NOW()),
        (v_ch_id, 'READING', '彼の説明は[抽象的]で具体性に欠ける。', '抽象的', 'ちゅうしょうてき', '["たいしょうてき", "ちゅうしょうてき", "いんしょうてき", "げんしょうてき"]', 'Lời giải thích của anh ấy mang tính trừu tượng và thiếu tính cụ thể. — Từ「抽象的」trong câu đọc là「ちゅうしょうてき」.', 4, NOW()),
        (v_ch_id, 'READING', '本物だと思って買ったブランドバッグが[偽物]だった。', '偽物', 'にせもの', '["安もの", "ほんもの", "にせもの", "まがいもの"]', 'Chiếc túi hàng hiệu tôi tưởng là thật khi mua hóa ra lại là đồ giả. — Từ「偽物」trong câu đọc là「にせもの」.', 5, NOW()),
        (v_ch_id, 'READING', '大好きな歌手のライブで、[興奮]のあまり泣いてしまった。', '興奮', 'こうふん', '["こうぶん", "はっぷん", "こうふん", "きょうふん"]', 'Tại buổi biểu diễn trực tiếp của ca sĩ yêu thích, tôi đã bật khóc vì quá phấn khích. — Từ「興奮」trong câu đọc là「こうふん」.', 6, NOW()),
        (v_ch_id, 'READING', '画家を目指している彼は、[挿し絵]のアルバイトをしている。', '挿し絵', 'さしえ', '["うつしえ", "はりえ", "さしえ", "かきえ"]', 'Anh ấy đang làm thêm công việc vẽ tranh minh họa trong khi hướng tới ước mơ trở thành họa sĩ. — Từ「挿し絵」trong câu đọc là「さしえ」.', 7, NOW()),
        (v_ch_id, 'READING', '今回の台風上陸の被害は全国各地に[及んだ]。', '及んだ', 'およんだ', '["よろこんだ", "およんだ", "すんだ", "ならんだ"]', 'Thiệt hại từ đợt bão đổ bộ lần này đã lan rộng ra khắp các vùng trên cả nước. — Từ「及んだ」trong câu đọc là「およんだ」.', 8, NOW()),
        (v_ch_id, 'READING', '新入社員の採用試験で、誰を合格とするか[慎重に]協議した。', '慎重に', 'しんちょうに', '["しんちょうに", "しんけんに", "ていちょうに", "げんじゅうに"]', 'Trong kỳ thi tuyển nhân viên mới, hội đồng đã thảo luận thận trọng xem nên chọn ai đỗ. — Từ「慎重に」trong câu đọc là「しんちょうに」.', 9, NOW()),
        (v_ch_id, 'READING', '同僚の妙に明るく振る舞っている姿に、[一抹]の不安を感じた。', '一抹', 'いちまつ', '["いちまつ", "いちぶ", "いっぺん", "いっしゅん"]', 'Trước dáng vẻ cố tỏ ra vui vẻ lạ thường của đồng nghiệp, tôi cảm thấy một chút bất an. — Từ「一抹」trong câu đọc là「いちまつ」.', 10, NOW()),
        (v_ch_id, 'READING', '周囲の人に[諭されて]、病院で検査を受ける決心をした。', '諭されて', 'さとされて', '["はげまされて", "うながされて", "さとされて", "だまされて"]', 'Được những người xung quanh khuyên nhủ, tôi đã quyết tâm đi khám tại bệnh viện. — Từ「諭されて」trong câu đọc là「さとされて」.', 11, NOW()),
        (v_ch_id, 'READING', '社長は、経費見直しで大幅な人員[削減]を検討している。', '削減', 'さくげん', '["さくげん", "しょうげん", "ぞうげん", "けいげん"]', 'Giám đốc đang xem xét việc cắt giảm nhân sự quy mô lớn nhằm rà soát lại chi phí. — Từ「削減」trong câu đọc là「さくげん」.', 12, NOW()),
        (v_ch_id, 'READING', '定職に就かず、[自由奔放な]生活を送る若者が増えている。', '自由奔放な', 'じゆうほんぽうな', '["じゆうほんぼうな", "じゆうきままな", "じゆうほんぽうな", "じゆうほうまんな"]', 'Ngày càng có nhiều người trẻ không làm công việc cố định mà sống cuộc đời tự do phóng khoáng. — Từ「自由奔放な」trong câu đọc là「じゆうほんぽうな」.', 13, NOW()),
        (v_ch_id, 'READING', '学生の頃は[貪る]ように本を読んだものだ。', '貪る', 'むさぼる', '["むさぼる", "あなどる", "たどる", "さぐる"]', 'Thời còn là sinh viên, tôi từng đọc sách ngấu nghiến như nuốt từng chữ. — Từ「貪る」trong câu đọc là「むさぼる」.', 14, NOW()),
        (v_ch_id, 'READING', '相手企業と[忍耐]強く交渉し、業務提携の合意にこぎつけた。', '忍耐', 'にんたい', '["にんたいう", "けいたい", "にんたい", "しんぼう"]', 'Sau khi kiên nhẫn đàm phán với doanh nghiệp đối tác, chúng tôi đã đạt được thỏa thuận hợp tác kinh doanh. — Từ「忍耐」trong câu đọc là「にんたい」.', 15, NOW()),
        (v_ch_id, 'WRITING', '急ブレーキに備え、前の車との[かんかく]は十分確保してください。', 'かんかく', '間隔', '["間隔", "管轄", "感覚", "関係"]', 'Để đề phòng phanh gấp, hãy giữ khoảng cách thật an toàn với xe phía trước. — Từ「かんかく」trong câu viết chữ Hán là「間隔」.', 16, NOW()),
        (v_ch_id, 'WRITING', 'A社は新技術の開発に成功し、急速な発展を[とげた]。', 'とげた', '遂げた', '["果げた", "遂げた", "挙げた", "げた"]', 'Công ty A đã thành công trong việc phát triển công nghệ mới và đạt được bước phát triển thần tốc. — Từ「とげた」trong câu viết chữ Hán là「遂げた」.', 17, NOW()),
        (v_ch_id, 'WRITING', 'コーヒー一杯で3時間も[ねばった]が、彼女は現れなかった。', 'ねばった', '粘った', '["張った", "粘った", "待った", "残った"]', 'Tôi đã kiên trì ngồi lì suốt 3 tiếng đồng hồ chỉ với một tách cà phê nhưng cô ấy vẫn không xuất hiện. — Từ「ねばった」trong câu viết chữ Hán là「粘った」.', 18, NOW()),
        (v_ch_id, 'WRITING', '誕生日のプレゼントのおもちゃを見て、息子は目を[かがやかせて]喜んだ。', 'かがやかせて', '輝かせて', '["照らせて", "輝かせて", "光らせて", "咲かせて"]', 'Nhìn thấy món đồ chơi quà sinh nhật, cậu con trai mắt sáng rực lên đầy thích thú. — Từ「かがやかせて」trong câu viết chữ Hán là「輝かせて」.', 19, NOW()),
        (v_ch_id, 'WRITING', '最近体重が気になり始めたので、肉類を[ひかえて]いる。', 'ひかえて', '控えて', '["抑えて", "控えて", "抱えて", "替えて"]', 'Gần đây bắt đầu lo lắng về cân nặng nên tôi đang hạn chế ăn các loại thịt. — Từ「ひかえて」trong câu viết chữ Hán là「控えて」.', 20, NOW()),
        (v_ch_id, 'WRITING', '入学試験で一定の点数に達した人は、入学金を[めんじょ]される。', 'めんじょ', '免除', '["排除", "削除", "免除", "解除"]', 'Những người đạt số điểm nhất định trong kỳ thi tuyển sinh sẽ được miễn lệ phí nhập học. — Từ「めんじょ」trong câu viết chữ Hán là「免除」.', 21, NOW()),
        (v_ch_id, 'WRITING', 'クラスメートは優秀な人ばかりで、[れっとうかん]にさいなまれる。', 'れっとうかん', '劣等感', '["烈等感", "劣頭感", "列島感", "劣等感"]', 'Bạn cùng lớp toàn những người xuất sắc khiến tôi bị giày vò bởi cảm giác tự ti. — Từ「れっとうかん」trong câu viết chữ Hán là「劣等感」.', 22, NOW()),
        (v_ch_id, 'WRITING', '志望校合格を目指して、少しの時間も[おしんで]勉強している。', 'おしんで', '惜しんで', '["惜しんで", "苦しんで", "悲しんで", "楽しんで"]', 'Hướng tới mục tiêu đỗ trường nguyện vọng, tôi quý tiếc từng chút thời gian để học tập. — Từ「おしんで」trong câu viết chữ Hán là「惜しんで」.', 23, NOW()),
        (v_ch_id, 'WRITING', '友達が失恋したと言ってわんわん泣いていたので、[なぐさめた]。', 'なぐさめた', '慰めた', '["慰めた", "諌めた", "収めた", "勧めた"]', 'Vì người bạn thất tình khóc nức nở nên tôi đã an ủi vỗ về. — Từ「なぐさめた」trong câu viết chữ Hán là「慰めた」.', 24, NOW()),
        (v_ch_id, 'WRITING', '新しく入社したスタッフのために、来週[かんげいかい]を開く。', 'かんげいかい', '歓迎会', '["歓芸会", "観迎会", "勧迎会", "歓迎会"]', 'Tuần tới chúng tôi sẽ tổ chức tiệc chào mừng dành cho các nhân viên mới vào công ty. — Từ「かんげいかい」trong câu viết chữ Hán là「歓迎会」.', 25, NOW()),
        (v_ch_id, 'WRITING', '当たって[くだけろ]の覚悟で告白してみたらどうですか。', 'くだけろ', '砕けろ', '["抜けろ", "砕けろ", "溶けろ", "裂けろ"]', 'Sao bạn không thử tỏ tình với tinh thần ''được ăn cả, ngã về không'' (va vào dù tan vỡ cũng đành) xem sao. — Từ「くだけろ」trong câu viết chữ Hán là「砕けろ」.', 26, NOW()),
        (v_ch_id, 'WRITING', 'コンサート会場に[ねっきょうてきな]ファンが押しかけた。', 'ねっきょうてきな', '熱狂的な', '["熱狂的な", "熱境的な", "熱響的な", "熱強的な"]', 'Những người hâm mộ cuồng nhiệt đã ùa tới hội trường buổi hòa nhạc. — Từ「ねっきょうてきな」trong câu viết chữ Hán là「熱狂的な」.', 27, NOW()),
        (v_ch_id, 'WRITING', '社会のモラルが低下している。実に[なげかわしい]ことだ。', 'なげかわしい', '嘆かわしい', '["痛かわしい", "悲かわしい", "嘆かわしい", "惜かわしい"]', 'Đạo đức xã hội đang xuống cấp. Thật là một điều đáng than thở. — Từ「なげかわしい」trong câu viết chữ Hán là「嘆かわしい」.', 28, NOW()),
        (v_ch_id, 'WRITING', '親からよく[ほめられる]子供は、社会適応力が高くなるそうだ。', 'ほめられる', '褒められる', '["認められる", "勧められる", "褒められる", "誉められる"]', 'Nghe nói những đứa trẻ thường xuyên được cha mẹ khen ngợi sẽ có khả năng thích nghi xã hội cao hơn. — Từ「ほめられる」trong câu viết chữ Hán là「褒められる」.', 29, NOW()),
        (v_ch_id, 'WRITING', 'A校は接戦を制し、2年ぶりに[せつじょく]を果たした。', 'せつじょく', '雪辱', '["侮辱", "汚辱", "屈辱", "雪辱"]', 'Trường A đã giành chiến thắng trong trận đấu sát nút và rửa mối nhục thua cuộc sau 2 năm. — Từ「せつじょく」trong câu viết chữ Hán là「雪辱」.', 30, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 3;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_exercises WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', '妹に[縁談]が持ち上がり、お見合いすることになった。', '縁談', 'えんだん', '["じょうだん", "かいだん", "そうだん", "えんだん"]', 'Có người mai mối chuyện hôn nhân cho em gái tôi nên em ấy sắp đi xem mắt. — Từ「縁談」trong câu đọc là「えんだん」.', 1, NOW()),
        (v_ch_id, 'READING', '[親戚]の子供の高校入学祝いに、図書カードを贈った。', '親戚', 'しんせき', '["しんゆう", "しんぞく", "ちじん", "しんせき"]', 'Tôi đã tặng thẻ mua sách làm quà mừng nhập học cấp 3 cho con của người họ hàng. — Từ「親戚」trong câu đọc là「しんせき」.', 2, NOW()),
        (v_ch_id, 'READING', '[俺]はコーヒーにするけど、お前は何にする？', '俺', 'おれ', '["われ", "わし", "ぼく", "おれ"]', 'Tao chọn cà phê đấy, còn mày uống gì? — Từ「俺」trong câu đọc là「おれ」.', 3, NOW()),
        (v_ch_id, 'READING', '村人は森からさまざまな[恩恵]を受けて生活している。', '恩恵', 'おんけい', '["おんけい", "ちえ", "おんぎ", "けいたく"]', 'Dân làng sinh sống nhờ nhận được nhiều ân huệ từ khu rừng. — Từ「恩恵」trong câu đọc là「おんけい」.', 4, NOW()),
        (v_ch_id, 'READING', '[紳士]服売り場で、冬物のスーツを一着新調した。', '紳士', 'しんし', '["しんし", "はかせ", "ぶし", "せんし"]', 'Tôi đã sắm mới một bộ vest mùa đông tại quầy trang phục quý ông. — Từ「紳士」trong câu đọc là「しんし」.', 5, NOW()),
        (v_ch_id, 'READING', '海外旅行中、[貴重品]は肌身離さず身につけるのが基本だ。', '貴重品', 'きちょうひん', '["きじゅうひん", "ぜいたくひん", "こうかひん", "きちょうひん"]', 'Khi đi du lịch nước ngoài, nguyên tắc cơ bản là luôn mang theo đồ quý giá bên mình không rời. — Từ「貴重品」trong câu đọc là「きちょうひん」.', 6, NOW()),
        (v_ch_id, 'READING', '暗闇から突然目の前に人が現れ、びっくり[仰天]した。', '仰天', 'ぎょうてん', '["どうてん", "こうてん", "しょうてん", "ぎょうてん"]', 'Từ trong bóng tối bỗng nhiên có người xuất hiện ngay trước mặt làm tôi kinh ngạc thất sắc. — Từ「仰天」trong câu đọc là「ぎょうてん」.', 7, NOW()),
        (v_ch_id, 'READING', '父方の[叔父]には、子供の頃よく遊んでもらった。', '叔父', 'おじ', '["おば", "おじ", "まご", "おい"]', 'Hồi nhỏ tôi thường được chú (em trai của bố) chơi cùng. — Từ「叔父」trong câu đọc là「おじ」.', 8, NOW()),
        (v_ch_id, 'READING', '社長である父親が[急逝]し、息子が跡を継いだ。', '急逝', 'きゅうせい', '["きゅうし", "きゅうせい", "きゅうびょう", "きゅう변"]', 'Người cha đang làm giám đốc đột ngột qua đời nên con trai đã kế승 sự nghiệp. — Từ「急逝」trong câu đọc là「きゅうせい」.', 9, NOW()),
        (v_ch_id, 'READING', '結婚式当日、二人揃って区役所に[婚姻]届を提出した。', '婚姻', 'こんいん', '["けっこん", "えんいん", "こんいん", "こんやく"]', 'Đúng ngày cưới, cả hai cùng nhau đến ủy ban quận nộp giấy đăng ký kết hôn. — Từ「婚姻」trong câu đọc là「こんいん」.', 10, NOW()),
        (v_ch_id, 'READING', '[老婆心]ながら忠告させてください。', '老婆心', 'ろうばしん', '["しんぱいしん", "こうきしん", "ろうじんしん", "ろうばしん"]', 'Dù biết là lo xa nhiều chuyện (lão bà tâm), nhưng xin hãy để tôi khuyên một lời. — Từ「老婆心」trong câu đọc là「ろうばしん」.', 11, NOW()),
        (v_ch_id, 'READING', '彼は会議中の自らの失言で[墓穴]を掘った。', '墓穴', 'ぼけつ', '["ぼけつう", "あなぼこ", "はかあな", "ぼけつ"]', 'Anh ta tự đào hố chôn mình bởi lời lỡ miệng trong cuộc họp. — Từ「墓穴」trong câu đọc là「ぼけつ」.', 12, NOW()),
        (v_ch_id, 'READING', '大勢の人々の拍手に包まれながら、[新郎]新婦が登場した。', '新郎', 'しんろう', '["しんぷ", "しんろう", "せいねん", "はなむこ"]', 'Trong tiếng vỗ tay của đông đảo quan khách, cô dâu và chú rể đã tiến vào lễ đường. — Từ「新郎」trong câu đọc là「しんろう」.', 13, NOW()),
        (v_ch_id, 'READING', '彼女は[お嬢様]育ちで、包丁も握ったことがない。', 'お嬢様', 'おじょうさま', '["おかあさま", "おくさま", "おひめさま", "おじょうさま"]', 'Cô ấy lớn lên như tiểu thư đài các nên chưa từng cầm đến con dao làm bếp. — Từ「お嬢様」trong câu đọc là「おじょうさま」.', 14, NOW()),
        (v_ch_id, 'READING', '彼は酔っ払って喧嘩をし、数日間の自宅[謹慎]を受けた。', '謹慎', 'きんしん', '["きんしん", "きんし", "しんちょう", "けんしん"]', 'Anh ta say rượu gây gổ đánh nhau nên bị kỷ luật đình chỉ tự kiểm điểm tại nhà vài ngày. — Từ「謹慎」trong câu đọc là「きんしん」.', 15, NOW()),
        (v_ch_id, 'WRITING', '部長は自分の出世のために、失敗の責任を部下に[てんか]した。', 'てんか', '転嫁', '["転化", "転家", "添加", "転嫁"]', 'Vì muốn thăng tiến cho bản thân, trưởng phòng đã đổ vấy trách nhiệm thất bại cho cấp dưới. — Từ「てんか」trong câu viết chữ Hán là「転嫁」.', 16, NOW()),
        (v_ch_id, 'WRITING', '彼は三代続く医師の[かけい]に生まれ、自身も目指している。', 'かけい', '家系', '["家系", "家継", "家形", "家計"]', 'Anh ấy sinh ra trong dòng họ (gia hệ) ba đời làm bác sĩ và bản thân cũng đang hướng tới nghề này. — Từ「かけい」trong câu viết chữ Hán là「家系」.', 17, NOW()),
        (v_ch_id, 'WRITING', '健康のため食事や睡眠などの[じこ]管理を怠らないようにする。', 'じこ', '自己', '["時効", "自己", "事故", "自個"]', 'Vì sức khỏe, tôi cố gắng không sao nhãng việc tự quản lý bản thân như ăn uống và giấc ngủ. — Từ「じこ」trong câu viết chữ Hán là「自己」.', 18, NOW()),
        (v_ch_id, 'WRITING', '「路上で人が倒れている」と[とくめい]で通報があった。', 'とくめい', '匿名', '["得名", "特命", "特名", "匿名"]', 'Có tin báo nặc danh rằng ''Có người đang ngã gục trên đường''. — Từ「とくめい」trong câu viết chữ Hán là「匿名」.', 19, NOW()),
        (v_ch_id, 'WRITING', '有名人の結婚式がテレビで[ちゅうけい]された。', 'ちゅうけい', '中継', '["中系", "中継", "中計", "中経"]', 'Lễ cưới của người nổi tiếng đã được truyền hình trực tiếp trên tivi. — Từ「ちゅうけい」trong câu viết chữ Hán là「中継」.', 20, NOW()),
        (v_ch_id, 'WRITING', '田中教授は脳科学の[けんい]として世界的に知られている。', 'けんい', '権威', '["権威", "賢威", "権位", "険威"]', 'Giáo sư Tanaka được biết đến trên toàn thế giới như một chuyên gia có uy quyền trong ngành khoa học thần kinh. — Từ「けんい」trong câu viết chữ Hán là「権威」.', 21, NOW()),
        (v_ch_id, 'WRITING', '卒業したら早く自立し、親[こうこう]をしたいと思っている。', 'こうこう', '孝行', '["孝行", "高校", "航行", "好行"]', 'Sau khi tốt nghiệp tôi muốn sớm tự lập và báo hiếu cha mẹ. — Từ「こうこう」trong câu viết chữ Hán là「孝行」.', 22, NOW()),
        (v_ch_id, 'WRITING', 'この庭園は入り口正面から見て左右[たいしょう]になっている。', 'たいしょう', '対称', '["対照", "対称", "対象", "対生"]', 'Khu vườn này nếu nhìn từ chính diện lối vào sẽ thấy đối xứng hai bên trái phải. — Từ「たいしょう」trong câu viết chữ Hán là「対称」.', 23, NOW()),
        (v_ch_id, 'WRITING', '仲間と楽しく過ごしていても、[こどく]を感じることがある。', 'こどく', '孤独', '["故独", "孤独", "個独", "固独"]', 'Dù đang vui vẻ bên bạn bè nhưng đôi lúc tôi vẫn cảm thấy cô độc. — Từ「こどく」trong câu viết chữ Hán là「孤独」.', 24, NOW()),
        (v_ch_id, 'WRITING', '財布を落としてしまい、警察に[いしつぶつ]届を出した。', 'いしつぶつ', '遺失物', '["遺失物", "紛失物", "消失物", "異質物"]', 'Tôi đánh rơi mất ví nên đã nộp đơn trình báo đồ thất lạc cho cảnh sát. — Từ「いしつぶつ」trong câu viết chữ Hán là「遺失物」.', 25, NOW()),
        (v_ch_id, 'WRITING', '事件の真相は闇に[ほうむられた]。', 'ほうむられた', '葬られた', '["封られた", "葬られた", "報られた", "放られた"]', 'Chân tướng của vụ án đã bị chôn vùi vào bóng tối. — Từ「ほうむられた」trong câu viết chữ Hán là「葬られた」.', 26, NOW()),
        (v_ch_id, 'WRITING', '[こじん]と近しい人だけで見送る家族葬が広まっている。', 'こじん', '故人', '["故人", "古人", "孤人", "個人"]', 'Hình thức tang lễ gia đình chỉ gồm những người thân thiết tiễn đưa người quá cố đang ngày càng phổ biến. — Từ「こじん」trong câu viết chữ Hán là「故人」.', 27, NOW()),
        (v_ch_id, 'WRITING', '日頃お世話になっているお礼を一言、[ねんがじょう]に添える。', 'ねんがじょう', '年賀状', '["年雅状", "年賀状", "念賀状", "年画状"]', 'Tôi viết thêm đôi lời cảm ơn vì sự giúp đỡ thường ngày vào tấm thiệp chúc Tết. — Từ「ねんがじょう」trong câu viết chữ Hán là「年賀状」.', 28, NOW()),
        (v_ch_id, 'WRITING', 'このドラマは原作に[ちゅうじつ]に再現されている。', 'ちゅうじつ', '忠実', '["仲実", "中実", "充実", "忠実"]', 'Bộ phim truyền hình này được tái hiện trung thành với nguyên tác. — Từ「ちゅうじつ」trong câu viết chữ Hán là「忠実」.', 29, NOW()),
        (v_ch_id, 'WRITING', 'AチームとBチームの実力は[はくちゅう]している。', 'はくちゅう', '伯仲', '["迫仲", "拍仲", "白昼", "伯仲"]', 'Thực lực của đội A và đội B ngang ngửa (kẻ tám lạng người nửa cân) với nhau. — Từ「はくちゅう」trong câu viết chữ Hán là「伯仲」.', 30, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 4;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_exercises WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', '[桃]は皮の全体にうぶ毛があり、香りの強いものがおいしい。', '桃', 'もも', '["かき", "うめ", "もも", "なし"]', 'Quả đào ngon là quả có lớp lông tơ phủ đều khắp vỏ và tỏa hương thơm浓郁. — Từ「桃」trong câu đọc là「もも」.', 1, NOW()),
        (v_ch_id, 'READING', '誕生日プレゼントに息子の好きな[昆虫]図鑑を買ってあげた。', '昆虫', 'こんちゅう', '["こんちゅう", "ようちゅう", "せいちゅう", "がいちゅう"]', 'Tôi đã mua cuốn từ điển bách khoa bằng hình về côn trùng mà con trai yêu thích làm quà sinh nhật. — Từ「昆虫」trong câu đọc là「こんちゅう」.', 2, NOW()),
        (v_ch_id, 'READING', 'この[扉]の向こうに何があるのだろう。', '扉', 'とびら', '["かきね", "まど", "のき", "とびら"]', 'Không biết phía bên kia cánh cửa này có gì nhỉ. — Từ「扉」trong câu đọc là「とびら」.', 3, NOW()),
        (v_ch_id, 'READING', '久々に家族で[鍋]料理を囲み、団らんの時間を過ごした。', '鍋', 'なべ', '["ぼん", "かま", "はち", "なべ"]', 'Lâu lắm rồi cả gia đình mới quây quần bên nồi lẩu và tận hưởng khoảng thời gian đoàn viên. — Từ「鍋」trong câu đọc là「なべ」.', 4, NOW()),
        (v_ch_id, 'READING', '水泳の国際大会の表彰式で国旗が[掲揚]された。', '掲揚', 'けいよう', '["けいじ", "ふよう", "けいよう", "こうよう"]', 'Quốc kỳ đã được kéo lên tung bay trong lễ trao giải của đại hội bơi lội quốc tế. — Từ「掲揚」trong câu đọc là「けいよう」.', 5, NOW()),
        (v_ch_id, 'READING', 'オリンピック選手団が[宿舎]用のホテルに到着した。', '宿舎', 'しゅくしゃ', '["きしゃ", "こうしゃ", "ちょうしゃ", "しゅくしゃ"]', 'Đoàn vận động viên Olympic đã đến khách sạn dùng làm khu ký túc xá lưu trú. — Từ「宿舎」trong câu đọc là「しゅくしゃ」.', 6, NOW()),
        (v_ch_id, 'READING', 'この地域では、学校の[垣根]を越えた交流が盛んだ。', '垣根', 'かきね', '["さかい", "かべ", "やね", "かきね"]', 'Ở khu vực này, hoạt động giao lưu vượt qua ranh giới (hàng rào) giữa các trường học diễn ra rất sôi nổi. — Từ「垣根」trong câu đọc là「かきね」.', 7, NOW()),
        (v_ch_id, 'READING', 'ここは90年に渡り、日本料理の伝統を守っている老舗[料亭]だ。', '料亭', 'りょうてい', '["かくてい", "りょうかん", "りょうてい", "別てい"]', 'Đây là nhà hàng Nhật truyền thống lâu đời đã gìn giữ tinh hoa ẩm thực suốt 90 năm qua. — Từ「料亭」trong câu đọc là「りょうてい」.', 8, NOW()),
        (v_ch_id, 'READING', '父の[書斎]には約五千冊の本が置かれている。', '書斎', 'しょさい', '["しょこ", "しょてん", "しょさい", "しょだな"]', 'Trong phòng đọc sách của bố có đặt khoảng năm nghìn cuốn sách. — Từ「書斎」trong câu đọc là「しょさい」.', 9, NOW()),
        (v_ch_id, 'READING', '雪の重みで枝が折れないように、竹や[縄]で枝を支える。', '縄', 'なわ', '["ひも", "なわ", "つな", "いと"]', 'Để cành cây không bị gãy vì sức nặng của tuyết, người ta dùng tre và dây thừng chống đỡ cành. — Từ「縄」trong câu đọc là「なわ」.', 10, NOW()),
        (v_ch_id, 'READING', '新学期の前に、ノートやペンなどの[文房具]を新調した。', '文房具', 'ぶんぼうぐ', '["ぶんぼうぐ", "かぐ", "ぶんぐ", "どうぐ"]', 'Trước thềm học kỳ mới, tôi đã sắm mới đồ dùng văn phòng phẩm như vở và bút. — Từ「文房具」trong câu đọc là「ぶんぼうぐ」.', 11, NOW()),
        (v_ch_id, 'READING', 'この製品は、社員が知恵を[絞って]考えた会社の目玉商品だ。', '絞って', 'しぼって', '["しめて", "しぼって", "あつめて", "ねって"]', 'Sản phẩm này là mặt hàng chủ lực của công ty do các nhân viên vắt óc suy nghĩ tạo nên. — Từ「絞って」trong câu đọc là「しぼって」.', 12, NOW()),
        (v_ch_id, 'READING', 'おでんは味が染み込むまでじっくり[煮た]方がおいしい。', '煮た', 'にた', '["むした", "いためた", "やいた", "にた"]', 'Món Oden ninh kỹ cho đến khi thấm đẫm gia vị ăn sẽ ngon hơn. — Từ「煮た」trong câu đọc là「にた」.', 13, NOW()),
        (v_ch_id, 'READING', '男は店員に[刃物]を突きつけ、現金を奪って逃げていった。', '刃物', 'はもの', '["かなもの", "にもの", "えもの", "はもの"]', 'Gã đàn ông chĩa dao (vật sắc nhọn) vào nhân viên cửa hàng, cướp tiền mặt rồi bỏ chạy. — Từ「刃物」trong câu đọc là「はもの」.', 14, NOW()),
        (v_ch_id, 'READING', '[暖炉]があるおしゃれな家に住むのが私の夢だ。', '暖炉', 'だんろ', '["こんろ", "だんぼう", "いろり", "だんろ"]', 'Ước mơ của tôi là được sống trong một ngôi nhà sang trọng có lò sưởi. — Từ「暖炉」trong câu đọc là「だんろ」.', 15, NOW()),
        (v_ch_id, 'WRITING', 'なんだか変な臭いがする。食べものが[くさって]いるのかもしれない。', 'くさって', '腐って', '["湿って", "濁って", "臭って", "腐って"]', 'Có mùi gì đó là lạ. Có lẽ thức ăn đã bị ôi thiu rồi. — Từ「くさって」trong câu viết chữ Hán là「腐って」.', 16, NOW()),
        (v_ch_id, 'WRITING', '試験の前日に一夜[づけ]で勉強しても、効果は期待できない。', 'づけ', '漬け', '["漬け", "続け", "着け", "付け"]', 'Dù có học nhồi nhét thức trắng một đêm trước ngày thi thì cũng chẳng thể kỳ vọng hiệu quả. — Từ「づけ」trong câu viết chữ Hán là「漬け」.', 17, NOW()),
        (v_ch_id, 'WRITING', '最近は、空気の熱を利用して湯を[わかす]給湯器もある。', 'わかす', '沸かす', '["乾かす", "湧かす", "沸かす", "溶かす"]', 'Gần đây còn có cả bình đun nước nóng tận dụng nhiệt lượng từ không khí để đun sôi nước. — Từ「わかす」trong câu viết chữ Hán là「沸かす」.', 18, NOW()),
        (v_ch_id, 'WRITING', '燃料代や原材料の[こうとう]で、食料や日用品も値上がりした。', 'こうとう', '高騰', '["高等", "高棟", "高頭", "高騰"]', 'Do giá nhiên liệu và nguyên vật liệu tăng vọt nên thực phẩm và đồ dùng hàng ngày cũng tăng giá theo. — Từ「こうとう」trong câu viết chữ Hán là「高騰」.', 19, NOW()),
        (v_ch_id, 'WRITING', '一人暮らしを始めてから、外食を控え[じすい]を心掛けている。', 'じすい', '自炊', '["自酔", "自推", "自粋", "自炊"]', 'Từ khi bắt đầu sống một mình, tôi hạn chế ăn ngoài và chú ý tự nấu ăn ở nhà. — Từ「じすい」trong câu viết chữ Hán là「自炊」.', 20, NOW()),
        (v_ch_id, 'WRITING', '今日の夕飯のおかずは野菜と肉の[いため]物にしよう。', 'いため', '炒め', '["煮め", "蒸し", "炒め", "焼き"]', 'Món ăn kèm bữa tối nay hãy làm món rau xào thịt nhé. — Từ「いため」trong câu viết chữ Hán là「炒め」.', 21, NOW()),
        (v_ch_id, 'WRITING', '[むし]器でふかしたての肉まんを食べる。', 'むし', '蒸し', '["沸し", "蒸し", "煮し", "炊し"]', 'Ăn bánh bao nhân thịt vừa mới hấp nóng hổi trong xửng hấp. — Từ「むし」trong câu viết chữ Hán là「蒸し」.', 22, NOW()),
        (v_ch_id, 'WRITING', '法隆寺の世界最古の五重[とう]は、世界遺産として有名だ。', 'とう', '塔', '["塔", "灯", "棟", "頭"]', 'Tháp năm tầng cổ nhất thế giới của chùa Horyuji rất nổi tiếng với tư cách là Di sản Thế giới. — Từ「とう」trong câu viết chữ Hán là「塔」.', 23, NOW()),
        (v_ch_id, 'WRITING', '友人がプールつきの立派な[ていたく]をかまえたそうだ。', 'ていたく', '邸宅', '["自宅", "住宅", "邸宅", "定宅"]', 'Nghe nói người bạn tôi vừa tậu một dinh thự bề thế có cả hồ bơi. — Từ「ていたく」trong câu viết chữ Hán là「邸宅」.', 24, NOW()),
        (v_ch_id, 'WRITING', '市民病院は老朽化が進んだ[びょうとう]を建て替えた。', 'びょうとう', '病棟', '["病塔", "病頭", "病室", "病棟"]', 'Bệnh viện thành phố đã xây lại khu nhà bệnh viện (bệnh đống) bị xuống cấp. — Từ「びょうとう」trong câu viết chữ Hán là「病棟」.', 25, NOW()),
        (v_ch_id, 'WRITING', '[そうこ]に搬入した荷物を仕分けして、各地へ配送する。', 'そうこ', '倉庫', '["倉庫", "総庫", "創庫", "層庫"]', 'Phân loại hàng hóa được chuyển vào nhà kho rồi giao đi các nơi. — Từ「そうこ」trong câu viết chữ Hán là「倉庫」.', 26, NOW()),
        (v_ch_id, 'WRITING', '彼はお金を借りては返す[つな]渡りの生活をしている。', 'つな', '綱', '["綱", "線", "網", "縄"]', 'Anh ta sống cuộc đời bấp bênh như đi trên dây, cứ vay tiền chỗ này lại đập vào chỗ kia. — Từ「つな」trong câu viết chữ Hán là「綱」.', 27, NOW()),
        (v_ch_id, 'WRITING', '毎朝、ベランダの[はち]植えを手入れするのは私の日課だ。', 'はち', '鉢', '["枠", "鉢", "皿", "盆"]', 'Mỗi sáng, việc chăm sóc các chậu cây cảnh ngoài ban công là thói quen hàng ngày của tôi. — Từ「はち」trong câu viết chữ Hán là「鉢」.', 28, NOW()),
        (v_ch_id, 'WRITING', '部屋にある本が増えてきたので、[ほんだな]を購入した。', 'ほんだな', '本棚', '["本箱", "本庫", "本台", "本棚"]', 'Vì sách trong phòng ngày một nhiều lên nên tôi đã mua một chiếc giá sách. — Từ「ほんだな」trong câu viết chữ Hán là「本棚」.', 29, NOW()),
        (v_ch_id, 'WRITING', '運動の後は汗[くさく]なるので、着替えを持って行こう。', 'くさく', '臭く', '["臭く", "匂く", "腐く", "香く"]', 'Sau khi vận động cơ thể sẽ có mùi mồ hôi nên hãy mang theo quần áo để thay nhé. — Từ「くさく」trong câu viết chữ Hán là「臭く」.', 30, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 5;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_exercises WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', '[穏やかな]春の海を車窓からのんびり眺める。', '穏やかな', 'おだやかな', '["おだやかな", "さわやかな", "あざやかな", "なごやかな"]', 'Thong thả ngắm nhìn biển xuân êm đềm qua khung cửa sổ tàu. — Từ「穏やかな」trong câu đọc là「おだやかな」.', 1, NOW()),
        (v_ch_id, 'READING', '彼女は[裕福な]家庭に育ち、家事をしたことがない。', '裕福な', 'ゆうふくな', '["ゆうふくな", "じゅうふくな", "ゆたかな", "こうふくな"]', 'Cô ấy lớn lên trong một gia đình giàu có sung túc nên chưa từng làm việc nhà. — Từ「裕福な」trong câu đọc là「ゆうふくな」.', 2, NOW()),
        (v_ch_id, 'READING', '[愚かな]政策を批判するために、デモ隊が組織された。', '愚かな', 'おろかな', '["はるかな", "かすかな", "おろそかな", "おろかな"]', 'Đoàn biểu tình đã được tổ chức nhằm phê phán chính sách ngu xuẩn. — Từ「愚かな」trong câu đọc là「おろかな」.', 3, NOW()),
        (v_ch_id, 'READING', 'あの人はけちでお金に[卑しい]と言われている。', '卑しい', 'いやしい', '["貧しい", "いやしい", "きびしい", "くやしい"]', 'Người đó bị nói là keo kiệt và bủn xỉn (hèn kém) chuyện tiền bạc. — Từ「卑しい」trong câu đọc là「いやしい」.', 4, NOW()),
        (v_ch_id, 'READING', '下田選手は各地を訪れ、[熱烈な]歓迎を受けた。', '熱烈な', 'ねつれつな', '["もうれつな", "ねつれつな", "げきれつな", "きょうれつな"]', 'Tuyển thủ Shimoda đi thăm khắp nơi và nhận được sự chào đón nồng nhiệt. — Từ「熱烈な」trong câu đọc là「ねつれつな」.', 5, NOW()),
        (v_ch_id, 'READING', '宇宙開発には[膨大な]費用が必要なため、削減が検討された。', '膨大な', 'ぼうだいな', '["そうだいな", "ぼうだいな", "ばくだいな", "きょだいな"]', 'Vì phát triển vũ trụ đòi hỏi chi phí khổng lồ nên việc cắt giảm đã được đưa ra xem xét. — Từ「膨大な」trong câu đọc là「ぼうだいな」.', 6, NOW()),
        (v_ch_id, 'READING', 'あの大学では文化祭に歌手を招くのが[恒例]になっている。', '恒例', 'こうれい', '["ぜんれい", "こうれい", "つうれい", "かんれい"]', 'Ở trường đại học kia, việc mời ca sĩ tới lễ hội văn hóa đã trở thành thông lệ hàng năm. — Từ「恒例」trong câu đọc là「こうれい」.', 7, NOW()),
        (v_ch_id, 'READING', '[日頃]の感謝の気持ちを込めて母に贈り物をした。', '日頃', 'ひごろ', '["ひび", "まいにち", "ひごろ", "にちじょう"]', 'Tôi tặng quà cho mẹ gói trọn tấm lòng biết ơn thường ngày. — Từ「日頃」trong câu đọc là「ひごろ」.', 8, NOW()),
        (v_ch_id, 'READING', 'この漢字は[使用頻度]が高いので覚えてください。', '使用頻度', 'しようひんど', '["しようていど", "しようひんど", "しようひんりつ", "しようかいすう"]', 'Chữ Hán này có tần suất sử dụng cao nên hãy ghi nhớ nhé. — Từ「使用頻度」trong câu đọc là「しようひんど」.', 9, NOW()),
        (v_ch_id, 'READING', '父の[唯一]の趣味は切手収集だ。', '唯一', 'ゆいいつ', '["ゆいいつ", "ゆいち", "ただひとつ", "だいいち"]', 'Sở thích duy nhất của bố tôi là sưu tầm tem. — Từ「唯一」trong câu đọc là「ゆいいつ」.', 10, NOW()),
        (v_ch_id, 'READING', '学生時代の友達とは[疎遠]で、何をしているか不明だ。', '疎遠', 'そえん', '["とおえん", "そえん", "ふえん", "むえん"]', 'Tôi đã xa cách ít liên lạc với người bạn thời sinh viên nên không rõ giờ bạn ấy đang làm gì. — Từ「疎遠」trong câu đọc là「そえん」.', 11, NOW()),
        (v_ch_id, 'READING', '彼女は昔から[自信過剰]なところがある。', '自信過剰', 'じしんかじょう', '["じしんまんまん", "じしんかだい", "じしんかど", "じしんかじょう"]', 'Cô ấy từ xưa đã có tính tự tin thái quá. — Từ「自信過剰」trong câu đọc là「じしんかじょう」.', 12, NOW()),
        (v_ch_id, 'READING', '他人の意見は[偏見]を持たずに聞くべきだ。', '偏見', 'へんけん', '["せんけん", "かいけん", "いけん", "へんけん"]', 'Nên lắng nghe ý kiến của người khác mà không mang định kiến thiên vị. — Từ「偏見」trong câu đọc là「へんけん」.', 13, NOW()),
        (v_ch_id, 'READING', '博物館を見学した後、[適宜]解散してください。', '適宜', 'てきぎ', '["てきとう", "ずいじ", "てきせつ", "てきぎ"]', 'Sau khi tham quan bảo tàng xong, mọi người hãy tự giải tán sao cho phù hợp. — Từ「適宜」trong câu đọc là「てきぎ」.', 14, NOW()),
        (v_ch_id, 'READING', '手が[滑って]ワイングラスが割れてしまった。', '滑って', 'すべって', '["ふるえて", "すべって", "はずれて", "ころんで"]', 'Bị trượt tay nên chiếc ly rượu vang đã rơi vỡ mất. — Từ「滑って」trong câu đọc là「すべって」.', 15, NOW()),
        (v_ch_id, 'WRITING', '彼は[ひま]さえあればテレビゲームをしている。', 'ひま', '暇', '["休", "間", "隙", "暇"]', 'Anh ta cứ hễ có thời gian rảnh là lại chơi điện tử. — Từ「ひま」trong câu viết chữ Hán là「暇」.', 16, NOW()),
        (v_ch_id, 'WRITING', 'この店は[ふんいき]がいいので、女性客に人気がある。', 'ふんいき', '雰囲気', '["分囲気", "雰囲気", "噴囲気", "風囲気"]', 'Quán này có bầu không khí rất tuyệt nên được khách hàng nữ ưa chuộng. — Từ「ふんいき」trong câu viết chữ Hán là「雰囲気」.', 17, NOW()),
        (v_ch_id, 'WRITING', '経済に関する知識が[とぼしい]ので、入門書を読み始めた。', 'とぼしい', '乏しい', '["乏しい", "寂しい", "貧しい", "惜しい"]', 'Vì kiến thức về kinh tế còn nghèo nàn hạn hẹp nên tôi đã bắt đầu đọc sách nhập môn. — Từ「とぼしい」trong câu viết chữ Hán là「乏しい」.', 18, NOW()),
        (v_ch_id, 'WRITING', '遠藤さんの声は[とくちょう]的で、遠くからでもわかる。', 'とくちょう', '特徴', '["特兆", "特徴", "特調", "特長"]', 'Giọng của anh Endo rất đặc trưng nên dù ở xa cũng nhận ra ngay. — Từ「とくちょう」trong câu viết chữ Hán là「特徴」.', 19, NOW()),
        (v_ch_id, 'WRITING', '娘を私立の[ようちえん]に通わせている。', 'ようちえん', '幼稚園', '["養稚園", "用稚園", "幼知園", "幼稚園"]', 'Tôi đang cho con gái theo học tại trường mẫu giáo tư thục. — Từ「ようちえん」trong câu viết chữ Hán là「幼稚園」.', 20, NOW()),
        (v_ch_id, 'WRITING', 'この部屋は日当たりが悪く、暗くて[いんき]臭い。', 'いんき', '陰気', '["暗気", "陰気", "院気", "隠気"]', 'Căn phòng này thiếu ánh nắng, tối tăm và mang vẻ u ám. — Từ「いんき」trong câu viết chữ Hán là「陰気」.', 21, NOW()),
        (v_ch_id, 'WRITING', '彼女の笑顔は[みりょくてき]で、幸せな気持ちになる。', 'みりょくてき', '魅力的', '["魅力的", "美力的", "味力的", "魔力的"]', 'Nụ cười của cô ấy thật quyến rũ cuốn hút, khiến người nhìn cảm thấy hạnh phúc. — Từ「みりょくてき」trong câu viết chữ Hán là「魅力的」.', 22, NOW()),
        (v_ch_id, 'WRITING', 'ここは宇宙人の目撃情報が多い[きみょうな]場所だ。', 'きみょうな', '奇妙な', '["奇妙な", "希妙な", "気妙な", "奇明な"]', 'Đây là một địa điểm kỳ lạ có nhiều thông tin bắt gặp người ngoài hành tinh. — Từ「きみょうな」trong câu viết chữ Hán là「奇妙な」.', 23, NOW()),
        (v_ch_id, 'WRITING', '犯人逮捕の決定的[しゅんかん]をカメラに収めた。', 'しゅんかん', '瞬間', '["瞬間", "巡間", "春間", "旬間"]', 'Khoảnh khắc mang tính quyết định khi bắt giữ thủ phạm đã được ghi lại bằng máy ảnh. — Từ「しゅんかん」trong câu viết chữ Hán là「瞬間」.', 24, NOW()),
        (v_ch_id, 'WRITING', '東京の桜は3月[げじゅん]から咲き始める。', 'げじゅん', '下旬', '["下准", "下巡", "下旬", "下順"]', 'Hoa anh đào ở Tokyo bắt đầu nở từ hạ tuần (cuối) tháng 3. — Từ「げじゅん」trong câu viết chữ Hán là「下旬」.', 25, NOW()),
        (v_ch_id, 'WRITING', '女性の地位が[じょじょに]向上し、待遇も改善した。', 'じょじょに', '徐々に', '["序々に", "除々に", "叙々に", "徐々に"]', 'Địa vị của phụ nữ dần dần được nâng cao và chế độ đãi ngộ cũng được cải thiện. — Từ「じょじょに」trong câu viết chữ Hán là「徐々に」.', 26, NOW()),
        (v_ch_id, 'WRITING', '負けが続き、優勝できるかどうかは[びみょう]だ。', 'びみょう', '微妙', '["微妙", "徴妙", "尾妙", "美妙"]', 'Do thua liên tiếp nên khả năng có giành được chức vô địch hay không rất mong manh (vi diệu). — Từ「びみょう」trong câu viết chữ Hán là「微妙」.', 27, NOW()),
        (v_ch_id, 'WRITING', '輸出の制限が[かんわ]され、貿易量が増えた。', 'かんわ', '緩和', '["寛和", "暖和", "簡和", "緩和"]', 'Hạn chế xuất khẩu được nới lỏng giúp kim ngạch thương mại tăng lên. — Từ「かんわ」trong câu viết chữ Hán là「緩和」.', 28, NOW()),
        (v_ch_id, 'WRITING', '一輪車は[へいこうかんかく]がないと、乗れない。', 'へいこうかんかく', '平衡感覚', '["平衡感覚", "平衝感覚", "平行感覚", "閉口感覚"]', 'Nếu không có cảm giác giữ thăng bằng thì không thể đi xe đạp một bánh được. — Từ「へいこうかんかく」trong câu viết chữ Hán là「平衡感覚」.', 29, NOW()),
        (v_ch_id, 'WRITING', '携帯電話には[とくしゅな]部品が使われている。', 'とくしゅな', '特殊な', '["特殊な", "特首な", "特珠な", "特種な"]', 'Trong điện thoại di động có sử dụng những linh kiện đặc thù. — Từ「とくしゅな」trong câu viết chữ Hán là「特殊な」.', 30, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 6;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_exercises WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', '病気で働けないのに、[怠惰な]人と誤解されてしまう。', '怠惰な', 'たいだな', '["らんだな", "たいだな", "むだな", "ふだな"]', 'Dù vì bệnh tật không thể làm việc nhưng lại bị hiểu lầm là kẻ lười biếng. — Từ「怠惰な」trong câu đọc là「たいだな」.', 1, NOW()),
        (v_ch_id, 'READING', '秋祭りで少年たちが笛を吹き、[哀愁]漂う音色を響かせた。', '哀愁', 'あいしゅう', '["あいしゅう", "かいしゅう", "ばんしゅう", "きょうしゅう"]', 'Trong lễ hội mùa thu, các thiếu niên thổi sáo ngân vang giai điệu phảng phất nỗi buồn man mác. — Từ「哀愁」trong câu đọc là「あいしゅう」.', 2, NOW()),
        (v_ch_id, 'READING', '信じていた友人の裏切りに[憤慨]し、絶交を決意した。', '憤慨', 'ふんがい', '["ふんぱつ", "がいたん", "ふんがい", "こうがい"]', 'Phẫn nộ trước sự phản bội của người bạn hằng tin tưởng, tôi quyết định tuyệt giao. — Từ「憤慨」trong câu đọc là「ふんがい」.', 3, NOW()),
        (v_ch_id, 'READING', '夜の[静寂]を破って、けたたましいサイレンの音が鳴り響いた。', '静寂', 'せいじゃく', '["せいじゃく", "ちんもく", "しじま", "せいしゅく"]', 'Phá tan sự tĩnh mịch của màn đêm, tiếng còi báo động inh ỏi vang vọng. — Từ「静寂」trong câu đọc là「せいじゃく」.', 4, NOW()),
        (v_ch_id, 'READING', 'その大学は、[質実剛健な]校風として知られている。', '質実剛健な', 'しつじつごうけんな', '["しつじつこうけんな", "しつじつごうけんな", "せいじつごうけんな", "しつぼくごうけんな"]', 'Trường đại học đó nổi tiếng với truyền thống học đường mộc mạc, chân chất và kiên cường mạnh mẽ. — Từ「質実剛健な」trong câu đọc là「しつじつごうけんな」.', 5, NOW()),
        (v_ch_id, 'READING', '彼の[巧妙な]話し方に、危うくだまされそうになった。', '巧妙な', 'こうみょうな', '["びみょうな", "きみょうな", "こうかつな", "こうみょうな"]', 'Tôi suýt chút nữa đã bị lừa bởi lối nói chuyện khéo léo tinh vi của anh ta. — Từ「巧妙な」trong câu đọc là「こうみょうな」.', 6, NOW()),
        (v_ch_id, 'READING', '肌が[敏感な]ので、化粧品に気を遣っている。', '敏感な', 'びんかんな', '["しんかんな", "びんかんな", "えいかんな", "どんかんな"]', 'Vì làn da nhạy cảm nên tôi rất cẩn thận khi chọn mỹ phẩm. — Từ「敏感な」trong câu đọc là「びんかんな」.', 7, NOW()),
        (v_ch_id, 'READING', '窓に[怪しい]人影が映り、思わず声を上げた。', '怪しい', 'あやしい', '["めずらしい", "あやしい", "おそろしい", "おかしい"]', 'Bóng người khả nghi in lên khung cửa sổ khiến tôi bất giác hét lên. — Từ「怪しい」trong câu đọc là「あやしい」.', 8, NOW()),
        (v_ch_id, 'READING', '父は[寛大]で、どんな時も温かく見守ってくれた。', '寛大', 'かんだい', '["かんだい", "ぼうだい", "こうだい", "そうだい"]', 'Bố tôi rất khoan dung độ lượng, lúc nào cũng ấm áp dõi theo tôi. — Từ「寛大」trong câu đọc là「かんだい」.', 9, NOW()),
        (v_ch_id, 'READING', '私は一人っ子なので、兄弟が多い友人が[羨ましい]。', '羨ましい', 'うらやましい', '["ほほえましい", "なやましい", "うらやましい", "いさましい"]', 'Vì là con một nên tôi rất ngưỡng mộ (ghen tị) với những người bạn có đông anh chị em. — Từ「羨ましい」trong câu đọc là「うらやましい」.', 10, NOW()),
        (v_ch_id, 'READING', '都会生活に[憧れて]、田舎から東京に出てきた。', '憧れて', 'あこがれて', '["あこがれて", "めざして", "ひかれて", "のぞんで"]', 'Khao khát cuộc sống nơi đô thị, tôi đã từ quê lên Tokyo. — Từ「憧れて」trong câu đọc là「あこがれて」.', 11, NOW()),
        (v_ch_id, 'READING', '大学中退を[後悔]しているなら、再挑戦すればいい。', '後悔', 'こうかい', '["こうかい", "はんせい", "くい", "ざんげ"]', 'Nếu đang hối hận vì đã bỏ học đại học giữa chừng thì cứ thử sức lại xem sao. — Từ「後悔」trong câu đọc là「こうかい」.', 12, NOW()),
        (v_ch_id, 'READING', '父は定年後、[悠悠]自適な生活をしている。', '悠悠', 'ゆうゆう', '["ようよう", "じょじょ", "とうとう", "ゆうゆう"]', 'Sau khi nghỉ hưu, bố tôi sống cuộc đời ung dung tự tại. — Từ「悠悠」trong câu đọc là「ゆうゆう」.', 13, NOW()),
        (v_ch_id, 'READING', 'フィギュアスケートの[華麗な]演技に夢中になる。', '華麗な', 'かれいな', '["びれいな", "かれいな", "きれいな", "そうれいな"]', 'Say mê trước màn trình diễn hoa lệ tuyệt đẹp của môn trượt băng nghệ thuật. — Từ「華麗な」trong câu đọc là「かれいな」.', 14, NOW()),
        (v_ch_id, 'READING', '遺産を巡る兄弟の[醜い]争いが起こった。', '醜い', 'みにくい', '["くるしい", "みにくい", "わるい", "ひどい"]', 'Cuộc tranh giành xấu xí giữa các anh em xoay quanh khối tài sản thừa kế đã nổ ra. — Từ「醜い」trong câu đọc là「みにくい」.', 15, NOW()),
        (v_ch_id, 'WRITING', '彼は全財産のほとんどを[じぜん]事業に寄付した。', 'じぜん', '慈善', '["自然", "事前", "次善", "慈善"]', 'Ông ấy đã quyên góp hầu hết toàn bộ tài sản của mình cho sự nghiệp từ thiện. — Từ「じぜん」trong câu viết chữ Hán là「慈善」.', 16, NOW()),
        (v_ch_id, 'WRITING', '高校時代の先輩を[したって]、上京した。', 'したって', '慕って', '["習って", "追って", "慕って", "頼って"]', 'Ngưỡng mộ và quý mến tiền bối thời cấp 3, tôi đã lên Tokyo. — Từ「したって」trong câu viết chữ Hán là「慕って」.', 17, NOW()),
        (v_ch_id, 'WRITING', '父はいつも冗談を言う[ゆかいな]人だ。', 'ゆかいな', '愉快な', '["愉快な", "友快な", "由快な", "優快な"]', 'Bố tôi là người vui tính lúc nào cũng nói đùa. — Từ「ゆかいな」trong câu viết chữ Hán là「愉快な」.', 18, NOW()),
        (v_ch_id, 'WRITING', '彼女は[かんせいな]住宅街に住んでいる。', 'かんせいな', '閑静な', '["閑静な", "簡静な", "完静な", "寛静な"]', 'Cô ấy đang sống trong một khu dân cư yên tĩnh thanh bình. — Từ「かんせいな」trong câu viết chữ Hán là「閑静な」.', 19, NOW()),
        (v_ch_id, 'WRITING', '試合の動向に[いっきいちゆう]し、興奮した。', 'いっきいちゆう', '一喜一憂', '["一喜一優", "一気一憂", "一喜一憂", "一期一憂"]', 'Vừa mừng vừa lo (nhất hỷ nhất ưu) theo từng diễn biến của trận đấu và vô cùng phấn khích. — Từ「いっきいちゆう」trong câu viết chữ Hán là「一喜一憂」.', 20, NOW()),
        (v_ch_id, 'WRITING', 'たくさんありますから、どうぞ[えんりょ]なく召し上がってください。', 'えんりょ', '遠慮', '["園慮", "遠路", "縁慮", "遠慮"]', 'Còn nhiều lắm nên xin cứ tự nhiên đừng khách sáo mà thưởng thức nhé. — Từ「えんりょ」trong câu viết chữ Hán là「遠慮」.', 21, NOW()),
        (v_ch_id, 'WRITING', '彼は仕事も見つからず、[みじめな]生活を送っている。', 'みじめな', '惨めな', '["悲めな", "痛めな", "惨めな", "苦めな"]', 'Anh ta không tìm được việc làm, đang phải sống cuộc sống thê thảm cơ cực. — Từ「みじめな」trong câu viết chữ Hán là「惨めな」.', 22, NOW()),
        (v_ch_id, 'WRITING', '古いアルバムを見ながら、昔を思い出して[かんがい]にふける。', 'かんがい', '感慨', '["感慨", "憤慨", "感害", "感概"]', 'Vừa xem cuốn album cũ vừa nhớ lại chuyện xưa và chìm đắm trong nỗi xúc động bồi hồi. — Từ「かんがい」trong câu viết chữ Hán là「感慨」.', 23, NOW()),
        (v_ch_id, 'WRITING', '彼は失敗を恐れず、何度も[かかんに]挑戦する。', 'かかんに', '果敢に', '["科敢に", "過敢に", "果敢に", "可敢に"]', 'Anh ấy không sợ thất bại, nhiều lần quả cảm thử thách bản thân. — Từ「かかんに」trong câu viết chữ Hán là「果敢に」.', 24, NOW()),
        (v_ch_id, 'WRITING', '[ごうか]客船に乗って、世界一周するのが夢だ。', 'ごうか', '豪華', '["業華", "剛華", "高価", "豪華"]', 'Ước mơ của tôi là được lên du thuyền hạng sang đi vòng quanh thế giới. — Từ「ごうか」trong câu viết chữ Hán là「豪華」.', 25, NOW()),
        (v_ch_id, 'WRITING', '石川さんは子供の時の[じゅんすいな]気持ちを持ち続けている。', 'じゅんすいな', '純粋な', '["純酔な", "純推な", "順粋な", "純粋な"]', 'Anh Ishikawa vẫn luôn giữ mãi tâm hồn thuần khiết như thuở thiếu thời. — Từ「じゅんすいな」trong câu viết chữ Hán là「純粋な」.', 26, NOW()),
        (v_ch_id, 'WRITING', '飽食の時代だが、食べ物を[そまつ]にしてはいけない。', 'そまつ', '粗末', '["粗末", "素末", "疎末", "祖末"]', 'Dù đang ở thời đại thừa thãi thức ăn nhưng không được lãng phí coi nhẹ thực phẩm. — Từ「そまつ」trong câu viết chữ Hán là「粗末」.', 27, NOW()),
        (v_ch_id, 'WRITING', '何だか顔色が悪いですよ。[だいじょうぶ]ですか。', 'だいじょうぶ', '大丈夫', '["大丈夫", "台丈夫", "大上夫", "代丈夫"]', 'Trông sắc mặt bạn có vẻ không tốt lắm. Bạn có ổn không đấy? — Từ「だいじょうぶ」trong câu viết chữ Hán là「大丈夫」.', 28, NOW()),
        (v_ch_id, 'WRITING', '都市の人口は[ほうわ]状態で、どこへ行っても人が多い。', 'ほうわ', '飽和', '["抱和", "包和", "飽和", "豊和"]', 'Dân số đô thị đang ở trạng thái bão hòa, đi đâu cũng thấy đông người. — Từ「ほうわ」trong câu viết chữ Hán là「飽和」.', 29, NOW()),
        (v_ch_id, 'WRITING', '高校の同窓会に参加し、[なつかしい]顔ぶれに再会した。', 'なつかしい', '懐かしい', '["親かしい", "惜かしい", "慕かしい", "懐かしい"]', 'Tham gia buổi họp lớp cấp 3, tôi đã gặp lại những gương mặt thân thương đáng nhớ. — Từ「なつかしい」trong câu viết chữ Hán là「懐かしい」.', 30, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 7;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_exercises WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', '春は恋が[芽生える]季節で、出会いも多い。', '芽生える', 'めばえる', '["めばえる", "はえる", "さかえる", "そびえる"]', 'Mùa xuân là mùa tình yêu đơm chồi nảy lộc và cũng có nhiều cuộc gặp gỡ. — Từ「芽生える」trong câu đọc là「めばえる」.', 1, NOW()),
        (v_ch_id, 'READING', '佐藤さんは[芝居]が好きで、演劇の道に進んだそうだ。', '芝居', 'しばい', '["えんげき", "しばい", "しばかり", "きょうげき"]', 'Nghe nói anh Sato rất thích kịch nghệ nên đã tiến bước theo con đường sân khấu. — Từ「芝居」trong câu đọc là「しばい」.', 2, NOW()),
        (v_ch_id, 'READING', '週末、家族と一緒にぶどう[狩り]に出かける予定だ。', '狩り', 'がり', '["つみ", "がり", "とり", "かり"]', 'Cuối tuần này tôi dự định cùng gia đình đi hái nho. — Từ「狩り」trong câu đọc là「がり」.', 3, NOW()),
        (v_ch_id, 'READING', '両チームは勝ち進み、決勝で[雌雄]を決することとなった。', '雌雄', 'しゆう', '["めすおす", "しゆう", "ゆうれつ", "しょうぶ"]', 'Cả hai đội đều thắng tiến và sẽ phân định thắng bại (thư hùng) tại trận chung kết. — Từ「雌雄」trong câu đọc là「しゆう」.', 4, NOW()),
        (v_ch_id, 'READING', '新聞記者の夫は、取材で全国[津津浦浦]を飛びまわっている。', '津津浦浦', 'つつうらうら', '["つつうらうら", "しんしんほほ", "つづうらうら", "すみずみ"]', 'Người chồng làm phóng viên báo chí của tôi đang bay đi khắp mọi miền đất nước để lấy tin. — Từ「津津浦浦」trong câu đọc là「つつうらうら」.', 5, NOW()),
        (v_ch_id, 'READING', '些細な行き違いがもとで、二人の間に[溝]ができた。', '溝', 'みぞ', '["みぞ", "へだたり", "かべ", "すきま"]', 'Chỉ vì một hiểu lầm nhỏ nhặt mà giữa hai người đã hình thành khoảng cách (rãnh ngăn). — Từ「溝」trong câu đọc là「みぞ」.', 6, NOW()),
        (v_ch_id, 'READING', '[曇った]ガラスに、絵を書いたりして遊んだものだ。', '曇った', 'くもった', '["にごった", "しめった", "こおった", "くもった"]', 'Ngày xưa tôi từng hayเล่น vẽ hình lên mặt kính bị mờ hơi nước. — Từ「曇った」trong câu đọc là「くもった」.', 7, NOW()),
        (v_ch_id, 'READING', 'りんごをかじったら歯[茎]から血が出たので歯医者へ行った。', '茎', 'ぐき', '["ぐき", "くき", "ね", "は"]', 'Vì cắn quả táo bị chảy máu chân răng (nướu/lợi: はぐき) nên tôi đã đi khám nha sĩ. — Từ「茎」trong câu đọc là「ぐき」.', 8, NOW()),
        (v_ch_id, 'READING', '酸性雨で[樹木]が枯れる問題が深刻化している。', '樹木', 'じゅもく', '["くさき", "しんりん", "きぎ", "じゅもく"]', 'Vấn đề cây cối khô héo do mưa axit đang ngày càng trở nên nghiêm trọng. — Từ「樹木」trong câu đọc là「じゅもく」.', 9, NOW()),
        (v_ch_id, 'READING', '沖縄諸島は[亜熱帯]に属し、冬でも雪は降らない。', '亜熱帯', 'あねったい', '["ねったい", "おんたい", "じゅんねったい", "あねったい"]', 'Quần đảo Okinawa thuộc vùng cận nhiệt đới nên ngay cả mùa đông cũng không có tuyết rơi. — Từ「亜熱帯」trong câu đọc là「あねったい」.', 10, NOW()),
        (v_ch_id, 'READING', 'この温泉は[硫黄]の匂いが強いが、入ると肌がすべすべになるらしい。', '硫黄', 'いおう', '["いおう", "りゅうこう", "りゅうおう", "ゆおう"]', 'Suối nước nóng này tuy nặng mùi lưu huỳnh nhưng nghe nói tắm vào da sẽ mịn màng. — Từ「硫黄」trong câu đọc là「いおう」.', 11, NOW()),
        (v_ch_id, 'READING', '大雨が降った後、川の水が[濁り]増水した。', '濁り', 'にごり', '["あふれ", "よどみ", "にごり", "しずみ"]', 'Sau trận mưa lớn, nước sông trở nên đục ngầu và dâng cao. — Từ「濁り」trong câu đọc là「にごり」.', 12, NOW()),
        (v_ch_id, 'READING', '結婚式は神社で、[披露宴]はホテルで行う予定だ。', '披露宴', 'ひろうえん', '["ひろうえん", "けっこんえん", "しゅくがえん", "ばんさんかい"]', 'Lễ cưới dự kiến tổ chức tại đền Thần đạo, còn tiệc cưới chiêu đãi sẽ diễn ra ở khách sạn. — Từ「披露宴」trong câu đọc là「ひろうえん」.', 13, NOW()),
        (v_ch_id, 'READING', '雨が上がり、空に[虹]がかかっているのが見えた。', '虹', 'にじ', '["くも", "きり", "かすみ", "にじ"]', 'Mưa tạnh, tôi nhìn thấy cầu vồng bắc ngang bầu trời. — Từ「虹」trong câu đọc là「にじ」.', 14, NOW()),
        (v_ch_id, 'READING', '容疑者を[尾行]するため、刑事が張り込みを続けている。', '尾行', 'びこう', '["びこう", "ついせき", "どうこう", "せんこう"]', 'Để bám đuôi theo dõi nghi phạm, các cảnh sát hình sự vẫn đang tiếp tục mật phục. — Từ「尾行」trong câu đọc là「びこう」.', 15, NOW()),
        (v_ch_id, 'WRITING', '彼の息子は大企業の[かんぶ]候補生として期待されている。', 'かんぶ', '幹部', '["管部", "肝部", "冠部", "幹部"]', 'Con trai ông ấy đang được kỳ vọng với tư cách là ứng viên cán bộ nguồn của tập đoàn lớn. — Từ「かんぶ」trong câu viết chữ Hán là「幹部」.', 16, NOW()),
        (v_ch_id, 'WRITING', '同僚の岸さんはローンを組んで、東京の[こうがい]に家を買った。', 'こうがい', '郊外', '["構外", "郊外", "港外", "校外"]', 'Đồng nghiệp Kishi đã vay trả góp để mua một căn nhà ở ngoại ô Tokyo. — Từ「こうがい」trong câu viết chữ Hán là「郊外」.', 17, NOW()),
        (v_ch_id, 'WRITING', '斉藤選手はマラソンで、金メダルを[かくとく]した。', 'かくとく', '獲得', '["画得", "拡得", "確得", "獲得"]', 'Tuyển thủ Saito đã giành được huy chương vàng ở môn chạy Marathon. — Từ「かくとく」trong câu viết chữ Hán là「獲得」.', 18, NOW()),
        (v_ch_id, 'WRITING', '高温で危険なため、[すで]で触らないでください。', 'すで', '素手', '["空手", "直手", "素手", "生手"]', 'Do nhiệt độ cao rất nguy hiểm nên xin đừng chạm vào bằng tay trần. — Từ「すで」trong câu viết chữ Hán là「素手」.', 19, NOW()),
        (v_ch_id, 'WRITING', 'テストはペンでなく、[えんぴつ]を使って書いてください。', 'えんぴつ', '鉛筆', '["鉛筆", "沿筆", "延筆", "縁筆"]', 'Khi làm bài thi xin hãy viết bằng bút chì chứ không dùng bút mực. — Từ「えんぴつ」trong câu viết chữ Hán là「鉛筆」.', 20, NOW()),
        (v_ch_id, 'WRITING', '畑にトマトの[なえ]を植えた。実がなるのが楽しみだ。', 'なえ', '苗', '["茎", "芽", "種", "苗"]', 'Tôi đã trồng cây cà chua non (cây giống) ngoài vườn. Rất mong chờ đến lúc cây結 trái. — Từ「なえ」trong câu viết chữ Hán là「苗」.', 21, NOW()),
        (v_ch_id, 'WRITING', '雪の[けっしょう]をデザインした電灯を、店の前に飾った。', 'けっしょう', '結晶', '["結唱", "結晶", "血晶", "決勝"]', 'Tôi đã trang trí chiếc đèn điện thiết kế hình bông tuyết (tinh thể tuyết) ở trước cửa tiệm. — Từ「けっしょう」trong câu viết chữ Hán là「結晶」.', 22, NOW()),
        (v_ch_id, 'WRITING', '大学時代は研究室でロボット製作に[ぼっとう]した。', 'ぼっとう', '没頭', '["没頭", "冒頭", "没倒", "暴投"]', 'Thời đại học tôi từng vùi đầu (mê mẩn) chế tạo robot trong phòng thí nghiệm. — Từ「ぼっとう」trong câu viết chữ Hán là「没頭」.', 23, NOW()),
        (v_ch_id, 'WRITING', '耳を[すます]と鳥の声が聞こえる。', 'すます', '澄ます', '["清ます", "済ます", "住ます", "澄ます"]', 'Lắng tai nghe kỹ sẽ thấy tiếng chim hót. — Từ「すます」trong câu viết chữ Hán là「澄ます」.', 24, NOW()),
        (v_ch_id, 'WRITING', '景気低迷により、[しゅとけん]全域で地価が下落した。', 'しゅとけん', '首都圏', '["首都県", "首都圏", "主都圏", "首途圏"]', 'Do suy thoái kinh tế, giá đất trên toàn khu vực vùng thủ đô đã sụt giảm. — Từ「しゅとけん」trong câu viết chữ Hán là「首都圏」.', 25, NOW()),
        (v_ch_id, 'WRITING', 'このワインは[さんみ]が強いので、料理に入れると良い。', 'さんみ', '酸味', '["散味", "酸味", "賛味", "産味"]', 'Loại rượu vang này có vị chua đậm nên cho vào món ăn khi nấu sẽ rất hợp. — Từ「さんみ」trong câu viết chữ Hán là「酸味」.', 26, NOW()),
        (v_ch_id, 'WRITING', '庭に雑草が[しげって]いるので、刈ることにした。', 'しげって', '茂って', '["成って", "盛って", "繁って", "茂って"]', 'Vì cỏ dại mọc um tùm trong sân vườn nên tôi quyết định cắt cỏ. — Từ「しげって」trong câu viết chữ Hán là「茂って」.', 27, NOW()),
        (v_ch_id, 'WRITING', 'このまま環境破壊が進むと、人類は[めつぼう]するだろう。', 'めつぼう', '滅亡', '["滅亡", "迷亡", "絶亡", "減亡"]', 'Nếu tình trạng tàn phá môi trường cứ tiếp diễn thế này, nhân loại có lẽ sẽ diệt vong. — Từ「めつぼう」trong câu viết chữ Hán là「滅亡」.', 28, NOW()),
        (v_ch_id, 'WRITING', '会社の方針に[そって]プロジェクトを進める。', 'そって', '沿って', '["従って", "伴って", "沿って", "添って"]', 'Triển khai dự án bám sát theo phương châm của công ty. — Từ「そって」trong câu viết chữ Hán là「沿って」.', 29, NOW()),
        (v_ch_id, 'WRITING', '事件の[けいい]を説明するために、資料を作成した。', 'けいい', '経緯', '["経緯", "敬意", "計位", "軽易"]', 'Tôi đã lập tài liệu để giải thích đầu đuôi diễn biến (kinh vĩ) của sự việc. — Từ「けいい」trong câu viết chữ Hán là「経緯」.', 30, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 8;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_exercises WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', '彼の趣味は[蝶]の採集で、家にはたくさんの標本がある。', '蝶', 'ちょう', '["はち", "ちょう", "が", "ほたる"]', 'Sở thích của anh ấy là sưu tầm bướm, ở nhà có rất nhiều tiêu bản. — Từ「蝶」trong câu đọc là「ちょう」.', 1, NOW()),
        (v_ch_id, 'READING', '[鯨]が潮を吹いた瞬間を見た。', '鯨', 'くじら', '["まぐろ", "いるか", "さめ", "くじら"]', 'Tôi đã nhìn thấy khoảnh khắc cá voi phun nước. — Từ「鯨」trong câu đọc là「くじら」.', 2, NOW()),
        (v_ch_id, 'READING', '釣りに行く前に魚の[餌]を買った。', '餌', 'えさ', '["えさ", "はりがね", "さお", "あみ"]', 'Trước khi đi câu cá, tôi đã mua mồi câu. — Từ「餌」trong câu đọc là「えさ」.', 3, NOW()),
        (v_ch_id, 'READING', 'スイスへ行ったお土産に[鳩時計]を買って、両親に贈った。', '鳩時計', 'はとどけい', '["かもどけい", "すずめどけい", "とりどけい", "はとどけい"]', 'Tôi đã mua đồng hồ chim cúc cu (chim bồ câu) làm quà lưu niệm chuyến đi Thụy Sĩ để tặng bố mẹ. — Từ「鳩時計」trong câu đọc là「はとどけい」.', 4, NOW()),
        (v_ch_id, 'READING', 'ゴミ置き場にたくさんの[烏]が群がっていて、不気味だ。', '烏', 'からす', '["つばめ", "すずめ", "からす", "かもめ"]', 'Rất nhiều quạ đang tụ tập ở bãi rác trông thật rợn người. — Từ「烏」trong câu đọc là「からす」.', 5, NOW()),
        (v_ch_id, 'READING', 'この卵は近くの[養鶏場]で買ったので、とても新鮮だ。', '養鶏場', 'ようけいじょう', '["ようぎょじょう", "ようとんじょう", "ぼくじょう", "ようけいじょう"]', 'Trứng này mua ở trại chăn nuôi gà gần đây nên vô cùng tươi ngon. — Từ「養鶏場」trong câu đọc là「ようけいじょう」.', 6, NOW()),
        (v_ch_id, 'READING', '都会では[蛍]は滅多に見られなくなった。', '蛍', 'ほたる', '["せみ", "こおろぎ", "とんぼ", "ほたる"]', 'Ở thành phố, đom đóm gần như rất hiếm khi còn được nhìn thấy. — Từ「蛍」trong câu đọc là「ほたる」.', 7, NOW()),
        (v_ch_id, 'READING', 'まだ将来のことは、[漠然]としか考えていない。', '漠然', 'ばくぜん', '["とうぜん", "まんぜん", "ぐうぜん", "ばくぜん"]', 'Tôi vẫn chỉ mới nghĩ một cách mơ hồ về chuyện tương lai. — Từ「漠然」trong câu đọc là「ばくぜん」.', 8, NOW()),
        (v_ch_id, 'READING', '自分が投稿した[川柳]が、雑誌に掲載された。', '川柳', 'せんりゅう', '["せんりゅう", "わか", "たんか", "はいく"]', 'Bài thơ Senryu do tôi gửi đi đã được đăng trên tạp chí. — Từ「川柳」trong câu đọc là「せんりゅう」.', 9, NOW()),
        (v_ch_id, 'READING', 'この印鑑は[象牙]でできている貴重な品だ。', '象牙', 'ぞうげ', '["ぎんが", "ぞうげ", "ぞうきば", "しょうげ"]', 'Con dấu này là món đồ quý giá được làm bằng ngà voi. — Từ「象牙」trong câu đọc là「ぞうげ」.', 10, NOW()),
        (v_ch_id, 'READING', '[蚊]に刺されたあとがかゆいので、薬を塗った。', '蚊', 'か', '["だに", "か", "のみ", "はえ"]', 'Vì vết muỗi đốt bị ngứa nên tôi đã bôi thuốc. — Từ「蚊」trong câu đọc là「か」.', 11, NOW()),
        (v_ch_id, 'READING', 'この辺りは織物が盛んで、[蚕]を飼っている家も多い。', '蚕', 'かいこ', '["くも", "みつばち", "まゆ", "かいこ"]', 'Vùng này nghề dệt rất phát triển nên nhiều hộ gia đình nuôi tằm. — Từ「蚕」trong câu đọc là「かいこ」.', 12, NOW()),
        (v_ch_id, 'READING', '[鴨]の親子が水面を気持ちよさそうに泳いでいる。', '鴨', 'かも', '["つる", "あひる", "かも", "はくちょう"]', 'Mẹ con đàn vịt trời đang bơi lội trông thật thích thú trên mặt nước. — Từ「鴨」trong câu đọc là「かも」.', 13, NOW()),
        (v_ch_id, 'READING', '今年は[猪突猛進]、何事にも積極的に取り組むつもりだ。', '猪突猛進', 'ちょとつもうしん', '["しとつもうしん", "いのししもうしん", "ちょとつゆうしん", "ちょとつもうしん"]', 'Năm nay tôi dự định sẽ hăng hái xông pha (trư đột mãnh tiến) trong mọi việc. — Từ「猪突猛進」trong câu đọc là「ちょとつもうしん」.', 14, NOW()),
        (v_ch_id, 'READING', '台風で波が[防波堤]を越え、民家に襲いかかった。', '防波堤', 'ぼうはてい', '["ていぼう", "ぼうすいてい", "かいがんてい", "ぼうはてい"]', 'Do bão lớn, sóng biển đã vượt qua đê chắn sóng và ập vào nhà dân. — Từ「防波堤」trong câu đọc là「ぼうはてい」.', 15, NOW()),
        (v_ch_id, 'WRITING', '今日はセール初日なので、開店前から[ちょうだ]の列ができている。', 'ちょうだ', '長蛇', '["長駄", "長蛇", "超蛇", "張蛇"]', 'Hôm nay là ngày đầu tiên giảm giá nên trước giờ mở cửa đã có hàng người xếp dài như rắn (trường xà). — Từ「ちょうだ」trong câu viết chữ Hán là「長蛇」.', 16, NOW()),
        (v_ch_id, 'WRITING', '聴衆の突然の質問に[ろうばい]し、冷や汗をかいた。', 'ろうばい', '狼狽', '["労働", "狼狽", "老廃", "浪費"]', 'Trước câu hỏi bất ngờ của khán giả, tôi luống cuống bối rối (lang bái) toát cả mồ hôi lạnh. — Từ「ろうばい」trong câu viết chữ Hán là「狼狽」.', 17, NOW()),
        (v_ch_id, 'WRITING', '山菜取りに行った人が、[くま]に襲われたそうだ。', 'くま', '熊', '["狼", "熊", "虎", "猪"]', 'Nghe nói người đi hái rau rừng đã bị gấu tấn công. — Từ「くま」trong câu viết chữ Hán là「熊」.', 18, NOW()),
        (v_ch_id, 'WRITING', '船で[かいきょう]を渡って、北海道へ行った。', 'かいきょう', '海峡', '["海狭", "海挟", "界峡", "海峡"]', 'Tôi đã đi tàu vượt qua eo biển để tới Hokkaido. — Từ「かいきょう」trong câu viết chữ Hán là「海峡」.', 19, NOW()),
        (v_ch_id, 'WRITING', '山の[みね]から太陽が昇ると、雪が一斉に輝きだした。', 'みね', '峰', '["峰", "崖", "峠", "嶺"]', 'Khi mặt trời mọc lên từ đỉnh núi, tuyết đồng loạt tỏa sáng lấp lánh. — Từ「みね」trong câu viết chữ Hán là「峰」.', 20, NOW()),
        (v_ch_id, 'WRITING', '伐採や酸性雨で森林面積が減り、[さばくか]が進んでいる。', 'さばくか', '砂漠化', '["砂幕化", "砂漠化", "砂縛化", "沙幕化"]', 'Do chặt phá rừng và mưa axit làm diện tích rừng suy giảm, tình trạng sa mạc hóa đang ngày càng lan rộng. — Từ「さばくか」trong câu viết chữ Hán là「砂漠化」.', 21, NOW()),
        (v_ch_id, 'WRITING', 'この山脈は何千万年も前に地面が[りゅうき]した結果だ。', 'りゅうき', '隆起', '["粒起", "立起", "流起", "隆起"]', 'Dãy núi này là kết quả của quá trình mặt đất trồi sụt nâng cao lên từ hàng chục triệu năm trước. — Từ「りゅうき」trong câu viết chữ Hán là「隆起」.', 22, NOW()),
        (v_ch_id, 'WRITING', '彼は意に反して、権力争いの[うず]に巻き込まれてしまった。', 'うず', '渦', '["輪", "鍋", "禍", "渦"]', 'Trái với ý muốn của mình, anh ấy đã bị cuốn vào vòng xoáy tranh giành quyền lực. — Từ「うず」trong câu viết chữ Hán là「渦」.', 23, NOW()),
        (v_ch_id, 'WRITING', 'パンには[はちみつ]を塗って食べるのが好きだ。', 'はちみつ', '蜂蜜', '["蜂密", "蜂蜜", "芳蜜", "豊蜜"]', 'Tôi thích phết mật ong lên bánh mì để ăn. — Từ「はちみつ」trong câu viết chữ Hán là「蜂蜜」.', 24, NOW()),
        (v_ch_id, 'WRITING', '仲がよかった二人の関係に、ふとしたことで[きれつ]が入る。', 'きれつ', '亀裂', '["気裂", "危裂", "奇裂", "亀裂"]', 'Mối quan hệ vốn tốt đẹp của hai người bỗng xuất hiện vết rạn nứt chỉ vì một chuyện tình cờ. — Từ「きれつ」trong câu viết chữ Hán là「亀裂」.', 25, NOW()),
        (v_ch_id, 'WRITING', '祖父の病気の早期回復を願って、[せんばづる]をおった。', 'せんばづる', '千羽鶴', '["千波鶴", "千葉鶴", "千羽鶴", "仙羽鶴"]', 'Cầu mong bệnh tình của ông nội sớm bình phục, tôi đã gấp một nghìn con hạc giấy. — Từ「せんばづる」trong câu viết chữ Hán là「千羽鶴」.', 26, NOW()),
        (v_ch_id, 'WRITING', '鳥が大きく[つばさ]を広げて、飛び立った。', 'つばさ', '翼', '["翼", "脚", "尾", "羽"]', 'Con chim sải rộng đôi cánh lớn rồi bay vút lên. — Từ「つばさ」trong câu viết chữ Hán là「翼」.', 27, NOW()),
        (v_ch_id, 'WRITING', 'あの二人は[けんえん]の仲と言われていて、全く話さない。', 'けんえん', '犬猿', '["見遠", "犬猿", "嫌遠", "険遠"]', 'Hai người đó được gọi là mối quan hệ như chó với khỉ (ghét nhau như chó với mèo), hoàn toàn không nói chuyện với nhau. — Từ「けんえん」trong câu viết chữ Hán là「犬猿」.', 28, NOW()),
        (v_ch_id, 'WRITING', '[たつまき]がおき、家の屋根が吹き飛びそうになった。', 'たつまき', '竜巻', '["滝巻", "立巻", "辰巻", "竜巻"]', 'Vòi rồng (lốc xoáy) nổi lên khiến mái nhà suýt bị thổi bay. — Từ「たつまき」trong câu viết chữ Hán là「竜巻」.', 29, NOW()),
        (v_ch_id, 'WRITING', '海外への投資で、十分な[りじゅん]を上げることができた。', 'りじゅん', '利潤', '["利潤", "利順", "利純", "理潤"]', 'Nhờ đầu tư ra nước ngoài, công ty đã thu về khoản lợi nhuận dồi dào. — Từ「りじゅん」trong câu viết chữ Hán là「利潤」.', 30, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 9;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_exercises WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[面倒くさい]」trong ngữ cảnh: (phức tạp)', '面倒くさい', 'めんどうくさい', '["めんどうくさい", "かんげんする", "きんぞくがふしょくする", "さいばいする"]', '「面倒くさい」đọc là「めんどうくさい」(mendoukusai) — Nghĩa: phức tạp.', 1, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[朝令暮改]」trong ngữ cảnh: (Triêu lệnh mộ cải (mệnh lệnh thay đổi liên tục))', '朝令暮改', 'ちょうれいぼかい', '["きしゃ", "かんべんする", "とくさんひんをけんじょうする", "ちょうれいぼかい"]', '「朝令暮改」đọc là「ちょうれいぼかい」(choureobokai) — Nghĩa: Triêu lệnh mộ cải (mệnh lệnh thay đổi liên tục).', 2, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[因果応報]」trong ngữ cảnh: (Nhân quả ứng báo (gieo nhân nào gặt quả nấy))', '因果応報', 'いんがおうほう', '["こうしょうがまとまる", "たいがい", "いんがおうほう", "けつぎをさいたくする"]', '「因果応報」đọc là「いんがおうほう」(ingaouhou) — Nghĩa: Nhân quả ứng báo (gieo nhân nào gặt quả nấy).', 3, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[一進一退]」trong ngữ cảnh: (Nhất tiến nhất thoái (lúc tiến lúc lùi))', '一進一退', 'いっしんいったい', '["だきょうてん", "いっしんいったい", "がいりゃく", "たくじしょ"]', '「一進一退」đọc là「いっしんいったい」(isshin-ittai) — Nghĩa: Nhất tiến nhất thoái (lúc tiến lúc lùi).', 4, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[右往左往]」trong ngữ cảnh: (Hữu vãng tả vãng (chạy ngược chạy xuôi hỗn loạn))', '右往左往', 'うおうさおう', '["うおうさおう", "きんぞくアレルギあれるぎー", "ひょうりいったい", "あくせんくとう"]', '「右往左往」đọc là「うおうさおう」(uousaou) — Nghĩa: Hữu vãng tả vãng (chạy ngược chạy xuôi hỗn loạn).', 5, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[危機一髪]」trong ngữ cảnh: (Nguy cơ nhất phát (ngàn cân treo sợi tóc))', '危機一髪', 'ききいっぱつ', '["かんじょうをすませる", "みっこうしゃをきょうせいそうかんする", "にっしんげっぽ", "ききいっぱつ"]', '「危機一髪」đọc là「ききいっぱつ」(kikiippatsu) — Nghĩa: Nguy cơ nhất phát (ngàn cân treo sợi tóc).', 6, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[急転直下]」trong ngữ cảnh: (Cấp chuyển trực hạ (chuyển biến đột ngột))', '急転直下', 'きゅうてんちょっか', '["かぞくをかえりみない", "たいぐう", "きゅうてんちょっか", "チームのじくとなる"]', '「急転直下」đọc là「きゅうてんちょっか」(kyuutenchokka) — Nghĩa: Cấp chuyển trực hạ (chuyển biến đột ngột).', 7, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[四面楚歌]」trong ngữ cảnh: (Tứ diện sở ca (bị cô lập bốn bề))', '四面楚歌', 'しめんそか', '["こんだて", "しめんそか", "せんぱく", "こくるい"]', '「四面楚歌」đọc là「しめんそか」(shimensoka) — Nghĩa: Tứ diện sở ca (bị cô lập bốn bề).', 8, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[自業自得]」trong ngữ cảnh: (Tự nghiệp tự đắc (tự làm tự chịu))', '自業自得', 'じごうじとく', '["じごうじとく", "しゅうかくする", "かこをかえりみる", "いたくする"]', '「自業自得」đọc là「じごうじとく」(jigoujitoku) — Nghĩa: Tự nghiệp tự đắc (tự làm tự chịu).', 9, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[千変万化]」trong ngữ cảnh: (Thiên biến vạn hóa (biến hóa khôn lường))', '千変万化', 'せんぺんばんか', '["のうこうみんぞく", "かいこする", "だけつする", "せんぺんばんか"]', '「千変万化」đọc là「せんぺんばんか」(senpenbanka) — Nghĩa: Thiên biến vạn hóa (biến hóa khôn lường).', 10, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[絶体絶命]」trong ngữ cảnh: (Tuyệt thể tuyệt mệnh (tình thế tuyệt vọng))', '絶体絶命', 'ぜったいぜつめい', '["ゆるしをこう", "かばんをかたからさげる", "ぜったいぜつめい", "せんたくする"]', '「絶体絶命」đọc là「ぜったいぜつめい」(zettaizetsumei) — Nghĩa: Tuyệt thể tuyệt mệnh (tình thế tuyệt vọng).', 11, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[他力本願]」trong ngữ cảnh: (Tha lực bản nguyện (ỷ lại vào người khác))', '他力本願', 'たりきほんがん', '["じんざいはけん", "たりきほんがん", "りっぱなおこない", "どくりつをせんげんする"]', '「他力本願」đọc là「たりきほんがん」(tarikihongan) — Nghĩa: Tha lực bản nguyện (ỷ lại vào người khác).', 12, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[適材適所]」trong ngữ cảnh: (Thích tài thích sở (đúng người đúng việc))', '適材適所', 'てきざいてきしょ', '["てきざいてきしょ", "そうはとんやがおろさない", "サークルにしょぞくする", "きせきをたどる"]', '「適材適所」đọc là「てきざいてきしょ」(tekizaitekisho) — Nghĩa: Thích tài thích sở (đúng người đúng việc).', 13, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[日進月歩]」trong ngữ cảnh: (Nhật tiến nguyệt bộ (tiến bộ từng ngày))', '日進月歩', 'にっしんげっぽ', '["だきょうする", "みみざわりなおと", "だとうせいにかける", "にっしんげっぽ"]', '「日進月歩」đọc là「にっしんげっぽ」(nisshingeppo) — Nghĩa: Nhật tiến nguyệt bộ (tiến bộ từng ngày).', 14, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[表裏一体]」trong ngữ cảnh: (Biểu lý nhất thể (hai mặt của một vấn đề))', '表裏一体', 'ひょうりいったい', '["ていあんする", "きにさわる", "ひょうりいったい", "ししゃをつかわす"]', '「表裏一体」đọc là「ひょうりいったい」(hyouriittai) — Nghĩa: Biểu lý nhất thể (hai mặt của một vấn đề).', 15, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[KHÍ]」(tàu hỏa, thổi còi) — Mẹo nhớ: THUỶ chuyển sang KHÍ gọi là hơi nước?', 'KHÍ', '汽', '["舶", "搬", "巡", "汽"]', 'Chữ「汽」(KHÍ) — tàu hỏa, thổi còi. Ví dụ: 汽車（きしゃ）.', 16, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[BẠC]」(tàu bè, hàng nhập khẩu) — Mẹo nhớ: Thuyền trắng là thuyền BẠC lớn?', 'BẠC', '舶', '["貢", "献", "舶", "巡"]', 'Chữ「舶」(BẠC) — tàu bè, hàng nhập khẩu. Ví dụ: 船舶（せんぱく）.', 17, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[BÀN]」(vận chuyển, đưa vào) — Mẹo nhớ: Dùng tay ném đồ lên thuyền để vận chuyển?', 'BÀN', '搬', '["拓", "搬", "献", "繁"]', 'Chữ「搬」(BÀN) — vận chuyển, đưa vào. Ví dụ: 運搬する（うんぱんする）.', 18, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TUẦN]」(đi dạo quanh, tình cờ gặp được người định mệnh của đời mình) — Mẹo nhớ: Đi lại dọc bờ sông TUẦN tra?', 'TUẦN', '巡', '["巡", "拓", "刈", "稲"]', 'Chữ「巡」(TUẦN) — đi dạo quanh, tình cờ gặp được người định mệnh của đời mình. Ví dụ: 巡る（めぐる）.', 19, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[CỐNG]」(giúp đỡ về tiền bạc, đồ cống nạp) — Mẹo nhớ: Tiền công để CỐNG nạp?', 'CỐNG', '貢', '["稲", "穂", "耕", "貢"]', 'Chữ「貢」(CỐNG) — giúp đỡ về tiền bạc, đồ cống nạp. Ví dụ: 貢ぐ（みつぐ）.', 20, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[HIẾN]」(dâng tặng đặc sản, dâng hoa lên mộ) — Mẹo nhớ: HIẾN tặng chó cho miền nam?', 'HIẾN', '献', '["穫", "穀", "献", "耕"]', 'Chữ「献」(HIẾN) — dâng tặng đặc sản, dâng hoa lên mộ. Ví dụ: 特産品を献上する（とくさんひんをけんじょうする）.', 21, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[HỆ]」(thành phố phồn vinh, cửa hàng buôn bán phát đạt) — Mẹo nhớ: lấy Dây buộc Xe của kẻ Thù phải thật HỆ trọng?', 'HỆ', '繁', '["培", "繁", "穀", "栽"]', 'Chữ「繁」(HỆ) — thành phố phồn vinh, cửa hàng buôn bán phát đạt. Ví dụ: 町が繫栄する（まちがはんえいする）.', 22, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[THÁC]」(khai thác, dự án khai thác hồ) — Mẹo nhớ: Khai THÁC ĐÁ thì phải dùng TAY?', 'THÁC', '拓', '["拓", "培", "渉", "提"]', 'Chữ「拓」(THÁC) — khai thác, dự án khai thác hồ. Ví dụ: 開拓する（かいたくする）.', 23, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[NGẢI]」(cắt cỏ, cắt lông cừu) — Mẹo nhớ: Bộ nghệ nhìn giống chữ メnhỉ , MÊ ĐAO như bị bùa NGẢI?', 'NGẢI', '刈', '["提", "摘", "択", "刈"]', 'Chữ「刈」(NGẢI) — cắt cỏ, cắt lông cừu. Ví dụ: 草を刈る（くさをかる）.', 24, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[ĐẠO]」(gặt lúa, nông dân trồng lúa) — Mẹo nhớ: lúa gặt một ngày có thể nhận đc gạo?', 'ĐẠO', '稲', '["把", "妥", "稲", "択"]', 'Chữ「稲」(ĐẠO) — gặt lúa, nông dân trồng lúa. Ví dụ: 稲を刈る（いねをかる）.', 25, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 10;
