        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[怠惰な生活]」trong ngữ cảnh: (cuộc sống lười biếng)', '怠惰な生活', 'たいだなせいかつ', '["たいだなせいかつ", "けねんする", "れいせいちんちゃく", "うんめいにほんろうされる"]', '「怠惰な生活」đọc là「たいだなせいかつ」(taidanaseikatsu) — Nghĩa: cuộc sống lười biếng.', 1, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[意気消沈]」trong ngữ cảnh: (Ý khí tiêu trầm (chán nản rầu rĩ))', '意気消沈', 'いきしょうちん', '["ていせいする", "せんせんきょうきょう", "こうろうしゃ", "いきしょうちん"]', '「意気消沈」đọc là「いきしょうちん」(ikishouchin) — Nghĩa: Ý khí tiêu trầm (chán nản rầu rĩ).', 2, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[意気投合]」trong ngữ cảnh: (Ý khí đầu hợp (tâm đầu ý hợp))', '意気投合', 'いきとうごう', '["はっきする", "きょうつうこう", "いきとうごう", "チームのかんとく"]', '「意気投合」đọc là「いきとうごう」(ikitougou) — Nghĩa: Ý khí đầu hợp (tâm đầu ý hợp).', 3, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[感無量]」trong ngữ cảnh: (Cảm vô lượng (xúc động khôn nguôi))', '感無量', 'かんむりょう', '["ねんこうじょれつ", "かんむりょう", "しぼうこう", "たてもののそせき"]', '「感無量」đọc là「かんむりょう」(kanmuryou) — Nghĩa: Cảm vô lượng (xúc động khôn nguôi).', 4, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[切歯扼腕]」trong ngữ cảnh: (Thiết xỉ ách oãn (nghiến răng căm phẫn))', '切歯扼腕', 'せっしやくわん', '["せっしやくわん", "じこけいはつ", "けんたいき", "あくせんくとう"]', '「切歯扼腕」đọc là「せっしやくわん」(sesshiyakuwan) — Nghĩa: Thiết xỉ ách oãn (nghiến răng căm phẫn).', 5, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[戦々恐々]」trong ngữ cảnh: (Chiến chiến khủng khủng (nơm nớp lo sợ))', '戦々恐々', 'せんせんきょうきょう', '["へいきへいぜん", "りんり", "しゃくぜん", "せんせんきょうきょう"]', '「戦々恐々」đọc là「せんせんきょうきょう」(sensenkyoukyou) — Nghĩa: Chiến chiến khủng khủng (nơm nớp lo sợ).', 6, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[平気平然]」trong ngữ cảnh: (Bình khí bình nhiên (bình thản như không))', '平気平然', 'へいきへいぜん', '["けんしょうにあたる", "こくふくする", "へいきへいぜん", "ぎおんご"]', '「平気平然」đọc là「へいきへいぜん」(heikiheizen) — Nghĩa: Bình khí bình nhiên (bình thản như không).', 7, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[抱腹絶倒]」trong ngữ cảnh: (Bão phúc tuyệt đảo (cười ôm bụng lăn lộn))', '抱腹絶倒', 'ほうふくぜっとう', '["けいとをくる", "ほうふくぜっとう", "こくふくする", "ブランドぶらんどしこう"]', '「抱腹絶倒」đọc là「ほうふくぜっとう」(houfukuzettou) — Nghĩa: Bão phúc tuyệt đảo (cười ôm bụng lăn lộn).', 8, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[無念無想]」trong ngữ cảnh: (Vô niệm vô tưởng (tâm trí tĩnh lặng hoàn toàn))', '無念無想', 'むねんむそう', '["むねんむそう", "じんせいてつがく", "きこう", "せいこうはどりょくのたまものだ"]', '「無念無想」đọc là「むねんむそう」(munenmusou) — Nghĩa: Vô niệm vô tưởng (tâm trí tĩnh lặng hoàn toàn).', 9, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[冷静沈着]」trong ngữ cảnh: (Lãnh tĩnh trầm착 (bình tĩnh điềm đạm))', '冷静沈着', 'れいせいちんちゃく', '["はだがすける", "しんぶんにかいしゃのこうこくがのる", "げんばのしきをとる", "れいせいちんちゃく"]', '「冷静沈着」đọc là「れいせいちんちゃく」(reiseichinchaku) — Nghĩa: Lãnh tĩnh trầm착 (bình tĩnh điềm đạm).', 10, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[和気藹々]」trong ngữ cảnh: (Hòa khí ái ái (bầu không khí đầm ấm hòa thuận))', '和気藹々', 'わきあいあい', '["ちちをほこりにおもう", "みじゅくじ", "わきあいあい", "げんばのしきをとる"]', '「和気藹々」đọc là「わきあいあい」(wakiaiai) — Nghĩa: Hòa khí ái ái (bầu không khí đầm ấm hòa thuận).', 11, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[半信半疑]」trong ngữ cảnh: (Bán tín bán nghi (nửa tin nửa ngờ))', '半信半疑', 'はんしんはんぎ', '["もはん", "はんしんはんぎ", "きぎょうりんり", "かきょう"]', '「半信半疑」đọc là「はんしんはんぎ」(hanshinhangi) — Nghĩa: Bán tín bán nghi (nửa tin nửa ngờ).', 12, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[心機一転]」trong ngữ cảnh: (Tâm cơ nhất chuyển (đổi mới tâm thế))', '心機一転', 'しんきいってん', '["しんきいってん", "もほうする", "とうこう", "いちばんのしゅうさい"]', '「心機一転」đọc là「しんきいってん」(shinkiitten) — Nghĩa: Tâm cơ nhất chuyển (đổi mới tâm thế).', 13, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[暗中模索]」trong ngữ cảnh: (Ám trung mô tác (mò mẫm trong bóng tối))', '暗中模索', 'あんちゅうもさく', '["はんしんはんぎ", "データをかいせきする", "じっせんてきな", "あんちゅうもさく"]', '「暗中模索」đọc là「あんちゅうもさく」(anchuumosaku) — Nghĩa: Ám trung mô tác (mò mẫm trong bóng tối).', 14, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[怠惰な生活]」trong ngữ cảnh: (cuộc sống lười biếng)', '怠惰な生活', 'たいだなせいかつ', '["なまけもの", "功徳を積む", "たいだなせいかつ", "かいていばん"]', '「怠惰な生活」đọc là「たいだなせいかつ」(taidanaseikatsu) — Nghĩa: cuộc sống lười biếng.', 15, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[SỞ]」(Đá tảng kê cột, nền tảng) — Mẹo nhớ: Tảng đá (石) đặt dưới rừng cây (林) làm nền móng vững chãi (SỞ).?', 'SỞ', '礎', '["践", "模", "範", "礎"]', 'Chữ「礎」(SỞ) — Đá tảng kê cột, nền tảng. Ví dụ: 基礎からしっかり勉強する（きそからしっかりべんきょうする）.', 16, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TIỄN]」(thực tiễn, tính thực tiễn) — Mẹo nhớ: TIỄN chân anh đi đánh giặc?', 'TIỄN', '践', '["釈", "拠", "践", "範"]', 'Chữ「践」(TIỄN) — thực tiễn, tính thực tiễn. Ví dụ: 実践（じっせん）.', 17, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[MÔ]」(quy mô, mô hình) — Mẹo nhớ: Người xưa khi MÔ tả lại lúc khai sơ trái đất chỉ có cỏ cây và mặt trời lớn?', 'MÔ', '模', '["擬", "模", "拠", "克"]', 'Chữ「模」(MÔ) — quy mô, mô hình. Ví dụ: 規模（きぼ）.', 18, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[PHẠM]」(mô hình, câu trả lời mẫu) — Mẹo nhớ: Ở rừng TRÚC Xe chỉ được chạy trong PHẠM VI cho phép?', 'PHẠM', '範', '["範", "擬", "哲", "倫"]', 'Chữ「範」(PHẠM) — mô hình, câu trả lời mẫu. Ví dụ: 模範（もはん）.', 19, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[THÍCH]」(giải thích, thêm chú thích) — Mẹo nhớ: không cần phải giải THÍCH hay biện luận gì cả, hãy XÍCH hắn lại!?', 'THÍCH', '釈', '["倫", "志", "功", "釈"]', 'Chữ「釈」(THÍCH) — giải thích, thêm chú thích. Ví dụ: 解釈する（かいしゃくする）.', 20, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[CỨ]」(căn cứ, cứ điểm) — Mẹo nhớ: Muốn xử lí 処 trong tay 扌 phải có chứng CỨ 拠?', 'CỨ', '拠', '["佳", "秀", "拠", "功"]', 'Chữ「拠」(CỨ) — căn cứ, cứ điểm. Ví dụ: 根拠（こんきょ）.', 21, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[KHẮC]」(khắc phục, chi tiết) — Mẹo nhớ: 10 sư Huynh cùng nhau KHẮC phục?', 'KHẮC', '克', '["薦", "克", "秀", "推"]', 'Chữ「克」(KHẮC) — khắc phục, chi tiết. Ví dụ: 克服する（こくふくする）.', 22, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[NGHĨ]」(thi thử, từ tượng thanh) — Mẹo nhớ: Còn nghi ngờ gì nữa hãy bắt tay 扌 làm theo những gì bạn NGHĨ?', 'NGHĨ', '擬', '["擬", "薦", "訂", "項"]', 'Chữ「擬」(NGHĨ) — thi thử, từ tượng thanh. Ví dụ: 模擬試験（もぎしけん）.', 23, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TRIẾT]」(triết học, triết lý sống) — Mẹo nhớ: Tay  扌 cầm rìu 斤  mồm 口 nói chuyện TRIẾT lí?', 'TRIẾT', '哲', '["項", "索", "稿", "哲"]', 'Chữ「哲」(TRIẾT) — triết học, triết lý sống. Ví dụ: 哲学（てつがく）.', 24, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LUÂN]」(đạo lý, đạo đức doanh nghiệp) — Mẹo nhớ: NGƯỜI vào nhà SÁCH tìm đọc LUÂN lí?', 'LUÂN', '倫', '["翻", "欄", "倫", "稿"]', 'Chữ「倫」(LUÂN) — đạo lý, đạo đức doanh nghiệp. Ví dụ: 倫理（りんり）.', 25, NOW());
    END IF;
