        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[紙幣を透かす]」trong ngữ cảnh: (xuyên qua tờ tiền giấy)', '紙幣を透かす', 'しへいをすかす', '["しへいをすかす", "しゅさいする", "えつらん", "しへい"]', '「紙幣を透かす」đọc là「しへいをすかす」(shiheiosukasu) — Nghĩa: xuyên qua tờ tiền giấy.', 1, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[累積赤字]」trong ngữ cảnh: (lỗ lũy kế)', '累積赤字', 'るいせきあかじ', '["さいはいをふる", "さいしょう", "ひじゅん", "るいせきあかじ"]', '「累積赤字」đọc là「るいせきあかじ」(ruisekiakaji) — Nghĩa: lỗ lũy kế.', 2, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[累計]」trong ngữ cảnh: (lũy kế)', '累計', 'るいけい', '["しんちょく", "ちゅうすう", "るいけい", "こくさいじょうやくをこっかいでひじゅんする"]', '「累計」đọc là「るいけい」(ruikei) — Nghĩa: lũy kế.', 3, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[将来に累を及ぼす]」trong ngữ cảnh: (làm ảnh hưởng liên lụy tới tương lai)', '将来に累を及ぼす', 'しょうらいにるいをおよぼす', '["けんやくする", "しょうらいにるいをおよぼす", "ひへい", "ふじょ"]', '「将来に累を及ぼす」đọc là「しょうらいにるいをおよぼす」(shourainiruiooyobosu) — Nghĩa: làm ảnh hưởng liên lụy tới tương lai.', 4, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[貨幣]」trong ngữ cảnh: (đồng tiền)', '貨幣', 'かへい', '["かへい", "あくせんくとう", "しょくぼう", "いつわ"]', '「貨幣」đọc là「かへい」(kahei) — Nghĩa: đồng tiền.', 5, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[紙幣]」trong ngữ cảnh: (tiền giấy)', '紙幣', 'しへい', '["じゅだくする", "とうがい", "てんぷ", "しへい"]', '「紙幣」đọc là「しへい」(shihei) — Nghĩa: tiền giấy.', 6, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[造幣局]」trong ngữ cảnh: (sở đúc tiên xu)', '造幣局', 'ぞうへいきょく', '["しゅくしゅくと", "けんえつ", "ぞうへいきょく", "てんぷ"]', '「造幣局」đọc là「ぞうへいきょく」(zouheikyoku) — Nghĩa: sở đúc tiên xu.', 7, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[俸給]」trong ngữ cảnh: (lương)', '俸給', 'ほうきゅう', '["にんちにおもむく", "ほうきゅう", "ねんぽう", "せんりつ"]', '「俸給」đọc là「ほうきゅう」(houkyuu) — Nghĩa: lương.', 8, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[年俸]」trong ngữ cảnh: (mức lương hàng năm)', '年俸', 'ねんぽう', '["ねんぽう", "きゅうへい", "こせきとうほんをやくしょでしゅとくする", "しもん"]', '「年俸」đọc là「ねんぽう」(nenpou) — Nghĩa: mức lương hàng năm.', 9, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[減俸される]」trong ngữ cảnh: (bị cắt giảm lương)', '減俸される', 'げんぽうされる', '["しもん", "ばいかい", "はんぷ", "げんぽうされる"]', '「減俸される」đọc là「げんぽうされる」(genpousareru) — Nghĩa: bị cắt giảm lương.', 10, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[報酬]」trong ngữ cảnh: (thù lao)', '報酬', 'ほうしゅう', '["こんだん", "じゅんきょうじゅ", "ほうしゅう", "かんりにつく"]', '「報酬」đọc là「ほうしゅう」(houshuu) — Nghĩa: thù lao.', 11, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[応酬]」trong ngữ cảnh: (đáp trả, hồi đáp)', '応酬', 'おうしゅう', '["そぜい", "おうしゅう", "じゅんきょうじゅ", "せんもんかにちょうさをいしょくする"]', '「応酬」đọc là「おうしゅう」(oushuu) — Nghĩa: đáp trả, hồi đáp.', 12, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[無報酬]」trong ngữ cảnh: (không thù lao)', '無報酬', 'むほうしゅう', '["むほうしゅう", "こうきしゅくせい", "はたん", "るいけい"]', '「無報酬」đọc là「むほうしゅう」(muhoushuu) — Nghĩa: không thù lao.', 13, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[倹約する]」trong ngữ cảnh: (tiết kiệm (tiền))', '倹約する', 'けんやくする', '["ふか", "おうしゅう", "きょそ", "けんやくする"]', '「倹約する」đọc là「けんやくする」(kenyakusuru) — Nghĩa: tiết kiệm (tiền).', 14, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[倹約家]」trong ngữ cảnh: (người tiết kiệm)', '倹約家', 'けんやくいえ', '["とうほん", "こんがん", "けんやくいえ", "きょそ"]', '「倹約家」đọc là「けんやくいえ」(kenyakuie) — Nghĩa: người tiết kiệm.', 15, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LŨY]」(lỗ lũy kế, lũy kế) — Mẹo nhớ: Làm Ruộng để Tích LŨY mua Chỉ?', 'LŨY', '累', '["幣", "俸", "酬", "累"]', 'Chữ「累」(LŨY) — lỗ lũy kế, lũy kế. Ví dụ: 累積赤字（るいせきあかじ）.', 16, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TỆ]」(đồng tiền, tiền giấy) — Mẹo nhớ: dùng gạo và vải để thay cho tiền TỆ?', 'TỆ', '幣', '["倹", "廉", "幣", "酬"]', 'Chữ「幣」(TỆ) — đồng tiền, tiền giấy. Ví dụ: 貨幣（かへい）.', 17, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[BỔNG]」(lương, mức lương hàng năm) — Mẹo nhớ: người hay phụng sự người khác sẽ được nhận lương BỔNG?', 'BỔNG', '俸', '["賦", "俸", "廉", "租"]', 'Chữ「俸」(BỔNG) — lương, mức lương hàng năm. Ví dụ: 俸給（ほうきゅう）.', 18, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[THÙ]」(thù lao, đáp trả) — Mẹo nhớ: Sang châu âu buôn Rượu 10 năm sau qua về báoTHÙ?', 'THÙ', '酬', '["酬", "賦", "采", "逸"]', 'Chữ「酬」(THÙ) — thù lao, đáp trả. Ví dụ: 報酬（ほうしゅう）.', 19, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[KIỆM]」(tiết kiệm (tiền), người tiết kiệm) — Mẹo nhớ: chỉ cần 1 người tiết KIỆM thì 10 người sẽ đc ở trong nhà?', 'KIỆM', '倹', '["逸", "赴", "諾", "倹"]', 'Chữ「倹」(KIỆM) — tiết kiệm (tiền), người tiết kiệm. Ví dụ: 倹約する（けんやくする）.', 20, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LIÊM]」(sự trong sạch và liên khiết, giá thấp) — Mẹo nhớ: Ở dưới mái nhà kiêm 兼 nhiều việc một lúc là LIÊM khiết?', 'LIÊM', '廉', '["唆", "捗", "廉", "諾"]', 'Chữ「廉」(LIÊM) — sự trong sạch và liên khiết, giá thấp. Ví dụ: 清廉潔白（せいれんけっぱく）.', 21, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TÔ]」(tô thuế, thuế đất đai) — Mẹo nhớ: Hoà 禾đóng TÔ Thuế hoa cả Mắt (且)?', 'TÔ', '租', '["憾", "租", "捗", "粛"]', 'Chữ「租」(TÔ) — tô thuế, thuế đất đai. Ví dụ: 租税（そぜい）.', 22, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[PHÚ]」(thuế, trả góp hàng tháng) — Mẹo nhớ: tỉ PHÚ giải quyết vũ lực bằng tiền?', 'PHÚ', '賦', '["賦", "憾", "該", "旋"]', 'Chữ「賦」(PHÚ) — thuế, trả góp hàng tháng. Ví dụ: 賦課（ふか）.', 23, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[THÁI]」(chỉ huy, ngoại hình không có gì nổi bật) — Mẹo nhớ: người quỳ gối (己) phân PHỐI rượu (酉) cho người khác?', 'THÁI', '采', '["旋", "扶", "媒", "采"]', 'Chữ「采」(THÁI) — chỉ huy, ngoại hình không có gì nổi bật. Ví dụ: 采配を振る（さいはいをふる）.', 24, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[DẬT]」(lỡ mất cơ hội, câu chuyện đi sai hướng) — Mẹo nhớ: Để Miễn thuế phải sống Ẩn DẬT?', 'DẬT', '逸', '["嘱", "懇", "逸", "媒"]', 'Chữ「逸」(DẬT) — lỡ mất cơ hội, câu chuyện đi sai hướng. Ví dụ: 好機を逸する（こうきをいっする）.', 25, NOW());
    END IF;
