        DELETE FROM kanji_exercises WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[抜本塞源]」trong ngữ cảnh: (Bạt bản tắc nguyên (diệt tận gốc rễ))', '抜本塞源', 'ばっぽんそくげん', '["ばっぽんそくげん", "ようさい", "かたをだっきゅうする", "おおまたであるく"]', '「抜本塞源」đọc là「ばっぽんそくげん」(bapponsokugen) — Nghĩa: Bạt bản tắc nguyên (diệt tận gốc rễ).', 1, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[孔雀]」trong ngữ cảnh: (con công)', '孔雀', 'くじゃく', '["びこうをふくらませる", "ぶんぴつ", "ざんがい", "くじゃく"]', '「孔雀」đọc là「くじゃく」(kujaku) — Nghĩa: con công.', 2, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[相撲の土俵]」trong ngữ cảnh: (võ đài sumo)', '相撲の土俵', 'すもうのどひょう', '["どうほうどうしのあらそい", "あくせんくとう", "すもうのどひょう", "だえき"]', '「相撲の土俵」đọc là「すもうのどひょう」(sumounodohyou) — Nghĩa: võ đài sumo.', 3, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[風貌]」trong ngữ cảnh: (diện mạo, vẻ bề ngoài)', '風貌', 'ふうぼう', '["顎関節症がくかんせつしょう", "ふうぼう", "へいそく", "きこう"]', '「風貌」đọc là「ふうぼう」(fuubou) — Nghĩa: diện mạo, vẻ bề ngoài.', 4, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[美貌]」trong ngữ cảnh: (khuôn mặt đẹp)', '美貌', 'びぼう', '["びぼう", "まゆつばもの", "いんとうがん", "とんざする"]', '「美貌」đọc là「びぼう」(bibou) — Nghĩa: khuôn mặt đẹp.', 5, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[変貌する]」trong ngữ cảnh: (biến đổi)', '変貌する', 'へんぼうする', '["痩身そうしんグッズ", "おんこうとくじつな", "しきんをねんしゅつする", "へんぼうする"]', '「変貌する」đọc là「へんぼうする」(henbousuru) — Nghĩa: biến đổi.', 6, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[ダイエットをして5kg痩やせた]」trong ngữ cảnh: (đã giảm 5kg nhờ ăn kiêng)', 'ダイエットをして5kg痩やせた', 'ダイエットをして5kg痩やせた', '["かいぼうする", "けいがいかする", "ダイエットをして5kg痩やせた", "てんねんとう"]', '「ダイエットをして5kg痩やせた」đọc là「ダイエットをして5kg痩やせた」(daiettooshite5kg痩yaseta) — Nghĩa: đã giảm 5kg nhờ ăn kiêng.', 7, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[痩やせた土地]」trong ngữ cảnh: (vùng đất khô cằn)', '痩やせた土地', '痩やせたとち', '["ほねのずい", "痩やせたとち", "しんきんこうそく", "るいせん"]', '「痩やせた土地」đọc là「痩やせたとち」(痩yasetatochi) — Nghĩa: vùng đất khô cằn.', 8, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[痩身そうしんグッズ]」trong ngữ cảnh: (hàng dành riêng cho người gầy)', '痩身そうしんグッズ', '痩身そうしんグッズ', '["痩身そうしんグッズ", "せきずい", "だぼくしょう", "なきはらす"]', '「痩身そうしんグッズ」đọc là「痩身そうしんグッズ」(痩身soushinguzzu) — Nghĩa: hàng dành riêng cho người gầy.', 9, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[分泌]」trong ngữ cảnh: (bài tiết hoóc môn)', '分泌', 'ぶんぴつ', '["こころのきずがいえる", "ばっぽんそくげん", "すもうのどひょう", "ぶんぴつ"]', '「分泌」đọc là「ぶんぴつ」(bunpitsu) — Nghĩa: bài tiết hoóc môn.', 10, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[泌尿器科]」trong ngữ cảnh: (khoa tiết niệu)', '泌尿器科', 'ひにょうきか', '["こつずいいしょく", "ちょうねんてん", "ひにょうきか", "すもうのどひょう"]', '「泌尿器科」đọc là「ひにょうきか」(hinyoukika) — Nghĩa: khoa tiết niệu.', 11, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[骨髄移植]」trong ngữ cảnh: (cấy ghép tủy)', '骨髄移植', 'こつずいいしょく', '["あしくびをねんざする", "こつずいいしょく", "またわり", "ダイエットをして5kg痩やせた"]', '「骨髄移植」đọc là「こつずいいしょく」(kotsuzuiishoku) — Nghĩa: cấy ghép tủy.', 12, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[骨の髄]」trong ngữ cảnh: (tủy xương)', '骨の髄', 'ほねのずい', '["ほねのずい", "ほうし", "あんちゅうもさく", "がんさいぼう"]', '「骨の髄」đọc là「ほねのずい」(honenozui) — Nghĩa: tủy xương.', 13, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[脊髄]」trong ngữ cảnh: (dây tủy sống)', '脊髄', 'せきずい', '["つばをのみこむ", "痩やせたとち", "こかんせつがいたい", "せきずい"]', '「脊髄」đọc là「せきずい」(sekizui) — Nghĩa: dây tủy sống.', 14, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[脊柱]」trong ngữ cảnh: (cột sống lưng)', '脊柱', 'せきちゅう', '["かんせん", "きとくじょうたい", "せきちゅう", "こかんせつがいたい"]', '「脊柱」đọc là「せきちゅう」(sekichuu) — Nghĩa: cột sống lưng.', 15, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[MẠO]」(diện mạo, khuôn mặt đẹp) — Mẹo nhớ: con sâu (豸) màu trắng có 2 chân (皃) dung MẠO khá đẹp?', 'MẠO', '貌', '["痩", "泌", "髄", "貌"]', 'Chữ「貌」(MẠO) — diện mạo, khuôn mặt đẹp. Ví dụ: 風貌（ふうぼう）.', 16, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[SẤU]」(đã giảm 5kg nhờ ăn kiêng, vùng đất khô cằn) — Mẹo nhớ: Đã Ốm rồi còn phải lê hai chân ra Ruộng cầy thì bảo sao không GẦY và xấu gái như con cá SẤU?', 'SẤU', '痩', '["脊", "椎", "痩", "髄"]', 'Chữ「痩」(SẤU) — đã giảm 5kg nhờ ăn kiêng, vùng đất khô cằn. Ví dụ: ダイエットをして5kg痩やせた（ダイエットをして5kg痩やせた）.', 17, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[BÍ]」(bài tiết hoóc môn, khoa tiết niệu) — Mẹo nhớ: BÍ quá thì phải bài tiết là điều tất (必) yếu?', 'BÍ', '泌', '["孔", "泌", "椎", "胞"]', 'Chữ「泌」(BÍ) — bài tiết hoóc môn, khoa tiết niệu. Ví dụ: 分泌（ぶんぴつ）.', 18, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TỦY]」(cấy ghép tủy, tủy xương) — Mẹo nhớ: Xương (骨)có (有) đường (辶) dẫn bên trong là TỦY?', 'TỦY', '髄', '["髄", "孔", "顎", "咽"]', 'Chữ「髄」(TỦY) — cấy ghép tủy, tủy xương. Ví dụ: 骨髄移植（こつずいいしょく）.', 19, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TÍCH]」(dây tủy sống, cột sống lưng) — Mẹo nhớ: Trong người (人) chị nguyệt (月) TÍCH tụ 4 cái đốt sống?', 'TÍCH', '脊', '["咽", "唾", "拳", "脊"]', 'Chữ「脊」(TÍCH) — dây tủy sống, cột sống lưng. Ví dụ: 脊髄（せきずい）.', 20, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[CHUY]」(động vật có xương sống, thoát vị đĩa đệm) — Mẹo nhớ: Dùng cây gỗ (木) đánh con chim (隹CHUY)?', 'CHUY', '椎', '["股", "腺", "椎", "拳"]', 'Chữ「椎」(CHUY) — động vật có xương sống, thoát vị đĩa đệm. Ví dụ: 脊椎動物（せきついどうぶつ）.', 21, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[BÀO]」(bao tử, cuộc chiến giữa những người đồng bào) — Mẹo nhớ: BÀO thai phải được Bao (包) bọc trong bụng mẹ trong 9 tháng(月)?', 'BÀO', '胞', '["篤", "胞", "腺", "癒"]', 'Chữ「胞」(BÀO) — bao tử, cuộc chiến giữa những người đồng bào. Ví dụ: 胞子（ほうし）.', 22, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[KHỔNG]」(phồng lỗ mũi, lỗ thông hơi) — Mẹo nhớ: Nuôi con nhỏ (子) chỉ có 乙ỗ , KHỔNG có lãi đâu!?', 'KHỔNG', '孔', '["孔", "篤", "剖", "醒"]', 'Chữ「孔」(KHỔNG) — phồng lỗ mũi, lỗ thông hơi. Ví dụ: 鼻孔を膨らませる（びこうをふくらませる）.', 23, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[NGẠC]」(cằm, bệnh xương khớp quai hàm) — Mẹo nhớ: cái đầu(頁) có 2 con mắt và 5 cái cằm thì kinh NGẠC quá?', 'NGẠC', '顎', '["醒", "骸", "痕", "顎"]', 'Chữ「顎」(NGẠC) — cằm, bệnh xương khớp quai hàm. Ví dụ: 顎あご（顎あご）.', 24, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[YẾT]」(cổ họng, ung thư vòm họng) — Mẹo nhớ: Cái Nhân (因) ở trong Miệng (口) là cái YẾT hầu?', 'YẾT', '咽', '["痘", "梗", "咽", "痕"]', 'Chữ「咽」(YẾT) — cổ họng, ung thư vòm họng. Ví dụ: 咽喉（いんこう）.', 25, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 27;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_exercises WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[一挙両得]」trong ngữ cảnh: (Nhất cử lưỡng tiện (một công đôi việc))', '一挙両得', 'いっきょりょうとく', '["いっきょりょうとく", "ひがた", "せんてひっしょう", "じよう"]', '「一挙両得」đọc là「いっきょりょうとく」(ikkyoryoutoku) — Nghĩa: Nhất cử lưỡng tiện (một công đôi việc).', 1, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[紆余曲折]」trong ngữ cảnh: (U dư khúc chiết (quanh co trắc trở))', '紆余曲折', 'うよきょくせつ', '["りんきおうへん", "しこうさくご", "せつなてき", "うよきょくせつ"]', '「紆余曲折」đọc là「うよきょくせつ」(uyokyokusetsu) — Nghĩa: U dư khúc chiết (quanh co trắc trở).', 2, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[七転八倒]」trong ngữ cảnh: (Thất điên bát đảo (lăn lộn đau đớn))', '七転八倒', 'しちてんばっとう', '["がでんいんすい", "ひっすかもく", "しちてんばっとう", "ひゃっぱつひゃくちゅう"]', '「七転八倒」đọc là「しちてんばっとう」(shichitenbattou) — Nghĩa: Thất điên bát đảo (lăn lộn đau đớn).', 3, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[手舞足蹈]」trong ngữ cảnh: (Thủ vũ túc đạo (vui mừng khôn xiết))', '手舞足蹈', 'しゅぶそくとう', '["きしかいせい", "しゅぶそくとう", "でんこうせっか", "きゅうす"]', '「手舞足蹈」đọc là「しゅぶそくとう」(shubusokutou) — Nghĩa: Thủ vũ túc đạo (vui mừng khôn xiết).', 4, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[先手必勝]」trong ngữ cảnh: (Tiên thủ tất thắng (ra tay trước ắt thắng))', '先手必勝', 'せんてひっしょう', '["せんてひっしょう", "しちてんばっとう", "ふとうふくつ", "あくせんくとう"]', '「先手必勝」đọc là「せんてひっしょう」(sentehisshou) — Nghĩa: Tiên thủ tất thắng (ra tay trước ắt thắng).', 5, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[電光石火]」trong ngữ cảnh: (Điện quang thạch hỏa (nhanh như chớp))', '電光石火', 'でんこうせっか', '["きんきちほう", "ゆうおうまいしん", "みぞうのだいじしん", "でんこうせっか"]', '「電光石火」đọc là「でんこうせっか」(denkousekka) — Nghĩa: Điện quang thạch hỏa (nhanh như chớp).', 6, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[百発百中]」trong ngữ cảnh: (Bách phát bách trúng (trăm phát trăm trúng))', '百発百中', 'ひゃっぱつひゃくちゅう', '["きそがわ", "しがけん", "ひゃっぱつひゃくちゅう", "けんこんいってき"]', '「百発百中」đọc là「ひゃっぱつひゃくちゅう」(hyappatsuhyakuchuu) — Nghĩa: Bách phát bách trúng (trăm phát trăm trúng).', 7, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[不撓不屈]」trong ngữ cảnh: (Bất náo bất khuất (kiên cường bất khuất))', '不撓不屈', 'ふとうふくつ', '["かまでくさをかる", "ふとうふくつ", "いっきょりょうとく", "うよきょくせつ"]', '「不撓不屈」đọc là「ふとうふくつ」(futoufukutsu) — Nghĩa: Bất náo bất khuất (kiên cường bất khuất).', 8, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[勇往邁進]」trong ngữ cảnh: (Dũng vãng mãi tiến (dũng cảm tiến lên))', '勇往邁進', 'ゆうおうまいしん', '["ゆうおうまいしん", "いちもうだじん", "あんちゅうもさく", "にいがたけん"]', '「勇往邁進」đọc là「ゆうおうまいしん」(yuuoumaishin) — Nghĩa: Dũng vãng mãi tiến (dũng cảm tiến lên).', 9, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[我田引水]」trong ngữ cảnh: (Ngã điền dẫn thủy (vun vén cho bản thân))', '我田引水', 'がでんいんすい', '["ひがた", "せんてひっしょう", "じよう", "がでんいんすい"]', '「我田引水」đọc là「がでんいんすい」(gaden-insui) — Nghĩa: Ngã điền dẫn thủy (vun vén cho bản thân).', 10, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[起死回生]」trong ngữ cảnh: (Khởi tử hồi sinh (vực dậy từ bờ vực))', '起死回生', 'きしかいせい', '["しこうさくご", "せつなてき", "きしかいせい", "りんきおうへん"]', '「起死回生」đọc là「きしかいせい」(kishikaisei) — Nghĩa: Khởi tử hồi sinh (vực dậy từ bờ vực).', 11, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[乾坤一擲]」trong ngữ cảnh: (Càn khôn nhất trịch (được ăn cả ngã về không))', '乾坤一擲', 'けんこんいってき', '["ひっすかもく", "けんこんいってき", "ひゃっぱつひゃくちゅう", "がでんいんすい"]', '「乾坤一擲」đọc là「けんこんいってき」(kenkon-itteki) — Nghĩa: Càn khôn nhất trịch (được ăn cả ngã về không).', 12, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[鎌で草を刈る]」trong ngữ cảnh: (cắt cỏ bằng liềm)', '鎌で草を刈る', 'かまでくさをかる', '["かまでくさをかる", "でんこうせっか", "きゅうす", "しゅぶそくとう"]', '「鎌で草を刈る」đọc là「かまでくさをかる」(kamadekusaokaru) — Nghĩa: cắt cỏ bằng liềm.', 13, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[干潟]」trong ngữ cảnh: (bãi cát nơi thủy triều lên xuống)', '干潟', 'ひがた', '["しちてんばっとう", "ふとうふくつ", "あくせんくとう", "ひがた"]', '「干潟」đọc là「ひがた」(higata) — Nghĩa: bãi cát nơi thủy triều lên xuống.', 14, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[新潟県]」trong ngữ cảnh: (tỉnh Niigata)', '新潟県', 'にいがたけん', '["きんきちほう", "ゆうおうまいしん", "にいがたけん", "あくせんくとう"]', '「新潟県」đọc là「にいがたけん」(niigataken) — Nghĩa: tỉnh Niigata.', 15, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LIÊM]」(cắt cỏ bằng liềm) — Mẹo nhớ: LIỀM làm từ Kim loại (金) và có dùng Kiêm (兼) cho nhiều công việc?', 'LIÊM', '鎌', '["潟", "畿", "滋", "鎌"]', 'Chữ「鎌」(LIÊM) — cắt cỏ bằng liềm. Ví dụ: 鎌で草を刈る（かまでくさをかる）.', 16, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TÍCH]」(bãi cát nơi thủy triều lên xuống, tỉnh Niigata) — Mẹo nhớ: TÍCH luỹ Cối (臼) đá làm đê Bao bọc (勹) Bãi Đất Ven Biển?', 'TÍCH', '潟', '["那", "須", "潟", "滋"]', 'Chữ「潟」(TÍCH) — bãi cát nơi thủy triều lên xuống, tỉnh Niigata. Ví dụ: 干潟（ひがた）.', 17, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[KÌ]」(Vùng Kinki là một khu vực nằm ở phía tây trung tâm của Honshu) — Mẹo nhớ: Chốn kinh KÌ, làm ruộng đồng (田) hoàn toàn bằng cơ khí (幾), máy móc!?', 'KÌ', '畿', '["那", "畿", "潟", "滋"]', 'Chữ「畿」(KÌ) — Vùng Kinki là một khu vực nằm ở phía tây trung tâm của Honshu. Ví dụ: 近畿地方（きんきちほう）.', 18, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TƯ]」(chất dinh dưỡng, tỉnh Siga) — Mẹo nhớ: trời mưa hai đôi yêu nhau uống sữa tâm TƯ riêng?', 'TƯ', '滋', '["滋", "鎌", "潟", "畿"]', 'Chữ「滋」(TƯ) — chất dinh dưỡng, tỉnh Siga. Ví dụ: 滋養（じよう）.', 19, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[NA]」(mang tính khoảnh khắc, chồng) — Mẹo nhớ: 印度支那 ấn độ chi NA ：đông dương?', 'NA', '那', '["畿", "滋", "須", "那"]', 'Chữ「那」(NA) — mang tính khoảnh khắc, chồng. Ví dụ: 刹那的（せつなてき）.', 20, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TU]」(bắt buộc, ấm trà nhỏ bằng gốm sứ) — Mẹo nhớ: Đi TU để Tóc (彡) trên Đầu (頁) Chắc là người vẫn nặng sầu tương tư?', 'TU', '須', '["畿", "滋", "須", "潟"]', 'Chữ「須」(TU) — bắt buộc, ấm trà nhỏ bằng gốm sứ. Ví dụ: 必須な（ひっすな）.', 21, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TẰNG]」(cụ ông cụ bà, trận động đất lớn chưa từng thấy) — Mẹo nhớ: Ngày (日) nào cũng làm Ruộng (田) mà Cỏ (艹) vẫn mọc lên TẰNG Tằng?', 'TẰNG', '曽', '["畿", "曽", "鎌", "潟"]', 'Chữ「曽」(TẰNG) — cụ ông cụ bà, trận động đất lớn chưa từng thấy. Ví dụ: 曽祖父母（そうそふはは）.', 22, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LIÊM]」(cắt cỏ bằng liềm) — Mẹo nhớ: LIỀM làm từ Kim loại (金) và có dùng Kiêm (兼) cho nhiều công việc?', 'LIÊM', '鎌', '["鎌", "滋", "那", "須"]', 'Chữ「鎌」(LIÊM) — cắt cỏ bằng liềm. Ví dụ: 鎌で草を刈る（かまでくさをかる）.', 23, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TÍCH]」(bãi cát nơi thủy triều lên xuống, tỉnh Niigata) — Mẹo nhớ: TÍCH luỹ Cối (臼) đá làm đê Bao bọc (勹) Bãi Đất Ven Biển?', 'TÍCH', '潟', '["畿", "滋", "那", "潟"]', 'Chữ「潟」(TÍCH) — bãi cát nơi thủy triều lên xuống, tỉnh Niigata. Ví dụ: 干潟（ひがた）.', 24, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[KÌ]」(Vùng Kinki là một khu vực nằm ở phía tây trung tâm của Honshu) — Mẹo nhớ: Chốn kinh KÌ, làm ruộng đồng (田) hoàn toàn bằng cơ khí (幾), máy móc!?', 'KÌ', '畿', '["潟", "滋", "畿", "鎌"]', 'Chữ「畿」(KÌ) — Vùng Kinki là một khu vực nằm ở phía tây trung tâm của Honshu. Ví dụ: 近畿地方（きんきちほう）.', 25, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 28;
    IF v_ch_id IS NOT NULL THEN
