        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[経路]」trong ngữ cảnh: (đường đi)', '経路', 'けいろ', '["けいろ", "ふわらいどう", "ちょうれいぼかい", "たりきほんがん"]', '「経路」đọc là「けいろ」(keiro) — Nghĩa: đường đi.', 1, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[瞑想]」trong ngữ cảnh: (ngồi thiền)', '瞑想', 'めいそう', '["たりきほんがん", "りんきおうへん", "しこうさくご", "めいそう"]', '「瞑想」đọc là「めいそう」(meisou) — Nghĩa: ngồi thiền.', 2, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[朝令暮改]」trong ngữ cảnh: (Triêu lệnh mộ cải (mệnh lệnh thay đổi liên tục))', '朝令暮改', 'ちょうれいぼかい', '["だいかんみんこく", "ひのえうま", "ちょうれいぼかい", "ごぶさたしております"]', '「朝令暮改」đọc là「ちょうれいぼかい」(choureobokai) — Nghĩa: Triêu lệnh mộ cải (mệnh lệnh thay đổi liên tục).', 3, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[因果応報]」trong ngữ cảnh: (Nhân quả ứng báo (gieo nhân nào gặt quả nấy))', '因果応報', 'いんがおうほう', '["ほんまつてんとう", "いんがおうほう", "ひのえうま", "ぜったいぜつめい"]', '「因果応報」đọc là「いんがおうほう」(ingaouhou) — Nghĩa: Nhân quả ứng báo (gieo nhân nào gặt quả nấy).', 4, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[一進一退]」trong ngữ cảnh: (Nhất tiến nhất thoái (lúc tiến lúc lùi))', '一進一退', 'いっしんいったい', '["いっしんいったい", "おもてざた", "ていしんしょう", "ひょうりいったい"]', '「一進一退」đọc là「いっしんいったい」(isshin-ittai) — Nghĩa: Nhất tiến nhất thoái (lúc tiến lúc lùi).', 5, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[右往左往]」trong ngữ cảnh: (Hữu vãng tả vãng (chạy ngược chạy xuôi hỗn loạn))', '右往左往', 'うおうさおう', '["しゅうちしんをもつ", "ごい", "わこうどうじん", "うおうさおう"]', '「右往左往」đọc là「うおうさおう」(uousaou) — Nghĩa: Hữu vãng tả vãng (chạy ngược chạy xuôi hỗn loạn).', 6, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[危機一髪]」trong ngữ cảnh: (Nguy cơ nhất phát (ngàn cân treo sợi tóc))', '危機一髪', 'ききいっぱつ', '["ぼうしょ", "いちるいベース", "ききいっぱつ", "あくせんくとう"]', '「危機一髪」đọc là「ききいっぱつ」(kikiippatsu) — Nghĩa: Nguy cơ nhất phát (ngàn cân treo sợi tóc).', 7, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[急転直下]」trong ngữ cảnh: (Cấp chuyển trực hạ (chuyển biến đột ngột))', '急転直下', 'きゅうてんちょっか', '["いっしんいったい", "きゅうてんちょっか", "ようしゃなくてりつけるたいよう", "にっしんげっぽ"]', '「急転直下」đọc là「きゅうてんちょっか」(kyuutenchokka) — Nghĩa: Cấp chuyển trực hạ (chuyển biến đột ngột).', 8, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[四面楚歌]」trong ngữ cảnh: (Tứ diện sở ca (bị cô lập bốn bề))', '四面楚歌', 'しめんそか', '["しめんそか", "りんもう", "おとさたない", "いっきょりょうとく"]', '「四面楚歌」đọc là「しめんそか」(shimensoka) — Nghĩa: Tứ diện sở ca (bị cô lập bốn bề).', 9, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[自業自得]」trong ngữ cảnh: (Tự nghiệp tự đắc (tự làm tự chịu))', '自業自得', 'じごうじとく', '["いっきょりょうとく", "かんこく", "はんようせい", "じごうじとく"]', '「自業自得」đọc là「じごうじとく」(jigoujitoku) — Nghĩa: Tự nghiệp tự đắc (tự làm tự chịu).', 10, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[千変万化]」trong ngữ cảnh: (Thiên biến vạn hóa (biến hóa khôn lường))', '千変万化', 'せんぺんばんか', '["うよきょくせつ", "いちぶいちりん", "せんぺんばんか", "いんがおうほう"]', '「千変万化」đọc là「せんぺんばんか」(senpenbanka) — Nghĩa: Thiên biến vạn hóa (biến hóa khôn lường).', 11, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[絶体絶命]」trong ngữ cảnh: (Tuyệt thể tuyệt mệnh (tình thế tuyệt vọng))', '絶体絶命', 'ぜったいぜつめい', '["ぼうしのはつげん", "ぜったいぜつめい", "ほにゅうるい", "めいそう"]', '「絶体絶命」đọc là「ぜったいぜつめい」(zettaizetsumei) — Nghĩa: Tuyệt thể tuyệt mệnh (tình thế tuyệt vọng).', 12, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[他力本願]」trong ngữ cảnh: (Tha lực bản nguyện (ỷ lại vào người khác))', '他力本願', 'たりきほんがん', '["たりきほんがん", "いちもうだじん", "ほにゅうびん", "さたをまつ"]', '「他力本願」đọc là「たりきほんがん」(tarikihongan) — Nghĩa: Tha lực bản nguyện (ỷ lại vào người khác).', 13, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[適材適所]」trong ngữ cảnh: (Thích tài thích sở (đúng người đúng việc))', '適材適所', 'てきざいてきしょ', '["さたをまつ", "おんしゃ", "きゅうてんちょっか", "てきざいてきしょ"]', '「適材適所」đọc là「てきざいてきしょ」(tekizaitekisho) — Nghĩa: Thích tài thích sở (đúng người đúng việc).', 14, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[日進月歩]」trong ngữ cảnh: (Nhật tiến nguyệt bộ (tiến bộ từng ngày))', '日進月歩', 'にっしんげっぽ', '["にるいだをはなつ", "いっしょくそくはつ", "にっしんげっぽ", "こうはん"]', '「日進月歩」đọc là「にっしんげっぽ」(nisshingeppo) — Nghĩa: Nhật tiến nguyệt bộ (tiến bộ từng ngày).', 15, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[PHIẾM]」(tính đa năng, phạm vi rộng) — Mẹo nhớ: Thủy (氵) nói chuyện Phàm (凡) PHIẾM?', 'PHIẾM', '汎', '["沙", "塁", "韓", "汎"]', 'Chữ「汎」(PHIẾM) — tính đa năng, phạm vi rộng. Ví dụ: 汎用性（はんようせい）.', 16, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[SA]」(chờ mệnh lệnh, bặt vô ấm tín) — Mẹo nhớ: SA mạc là nơi Thiếu (少 ) Nước ( 氵)?', 'SA', '沙', '["厘", "附", "沙", "韓"]', 'Chữ「沙」(SA) — chờ mệnh lệnh, bặt vô ấm tín. Ví dụ: 沙汰を待つ（さたをまつ）.', 17, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LŨY]」(điểm chạm bóng số 1(bóng chày), thực hiện cú đúp (bóng chày)) — Mẹo nhớ: Thành LŨY bao gồm Ruộng (田) Đất (土) vây quanh tứ phướng 4 hướng?', 'LŨY', '塁', '["逓", "塁", "附", "彙"]', 'Chữ「塁」(LŨY) — điểm chạm bóng số 1(bóng chày), thực hiện cú đúp (bóng chày). Ví dụ: 一塁ベース（いちるいベース）.', 18, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[HÀN]」(Hàn Quốc, Đại hàn dân quốc) — Mẹo nhớ: 20 ngày (十日十)  Vi (韋) hành của vua HÀN quốc?', 'HÀN', '韓', '["韓", "逓", "某", "羞"]', 'Chữ「韓」(HÀN) — Hàn Quốc, Đại hàn dân quốc. Ví dụ: 韓国（かんこく）.', 19, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LI]」(0, rất nhỏ) — Mẹo nhớ: Ông Lí ( 里) Chi LI từng Tí?', 'LI', '厘', '["羞", "赦", "丙", "厘"]', 'Chữ「厘」(LI) — 0, rất nhỏ. Ví dụ: 厘（りん）.', 20, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[PHỤ]」(ghi chú bổ sung) — Mẹo nhớ: giao Phó (付) cho miếng đất này coi như PHỤ giúp phần nào?', 'PHỤ', '附', '["沙", "塁", "附", "汎"]', 'Chữ「附」(PHỤ) — ghi chú bổ sung. Ví dụ: 附記する（ふきする）.', 21, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[VỊ]」(từ vựng) — Mẹo nhớ: Thử các loại VỊ khác nhau mặc kệ (彑) kết quả (果) trên đầu?', 'VỊ', '彙', '["厘", "彙", "塁", "韓"]', 'Chữ「彙」(VỊ) — từ vựng. Ví dụ: 語彙（ごい）.', 22, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[ĐỆ]」(bộ giao thông vận tải) — Mẹo nhớ: cầm 2 (二) cái khăn (巾) và búa đi ĐỆ trình trên con đường ( 辶) này?', 'ĐỆ', '逓', '["逓", "厘", "附", "彙"]', 'Chữ「逓」(ĐỆ) — bộ giao thông vận tải. Ví dụ: 逓信省（ていしんしょう）.', 23, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[MỖ]」(phát ngôn của ai đó, nơi nào đó) — Mẹo nhớ: cây (木) cam (甘) ngọt của Ông MỖ nào đó?', 'MỖ', '某', '["彙", "逓", "羞", "某"]', 'Chữ「某」(MỖ) — phát ngôn của ai đó, nơi nào đó. Ví dụ: 某氏の発言（ぼうしのはつげん）.', 24, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TU]」(cảm thấy xấu hổ) — Mẹo nhớ: Con dê（羊）đi TU gặp con trâu (丑) to nên thấy nhút nhát?', 'TU', '羞', '["赦", "丙", "羞", "某"]', 'Chữ「羞」(TU) — cảm thấy xấu hổ. Ví dụ: 羞恥心を持つ（しゅうちしんをもつ）.', 25, NOW());
    END IF;
