        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[戴冠式]」trong ngữ cảnh: (lễ đăng quang)', '戴冠式', 'たいかんしき', '["たいかんしき", "りんきおうへん", "らいひんあいさつ", "しこうさくご"]', '「戴冠式」đọc là「たいかんしき」(taikanshiki) — Nghĩa: lễ đăng quang.', 1, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[頂戴する]」trong ngữ cảnh: (nhận)', '頂戴する', 'ちょうだいする', '["しゃちょうのおんぞうし", "えっけんのあいだ", "ちゃくし", "ちょうだいする"]', '「頂戴する」đọc là「ちょうだいする」(choudaisuru) — Nghĩa: nhận.', 2, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[来賓挨拶]」trong ngữ cảnh: (lời chào của khách mời)', '来賓挨拶', 'らいひんあいさつ', '["こくおうにえっけんする", "そうすい", "らいひんあいさつ", "ちょくご"]', '「来賓挨拶」đọc là「らいひんあいさつ」(raihinaisatsu) — Nghĩa: lời chào của khách mời.', 3, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[賓客をもてなす]」trong ngữ cảnh: (tiếp đãi khách)', '賓客をもてなす', 'ひんきゃくをもてなす', '["こうていにはいえつする", "ひんきゃくをもてなす", "そうすい", "あくせんくとう"]', '「賓客をもてなす」đọc là「ひんきゃくをもてなす」(hinkyakuomotenasu) — Nghĩa: tiếp đãi khách.', 4, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[国賓]」trong ngữ cảnh: (quốc khách)', '国賓', 'こくひん', '["こくひん", "ちゃくちゃくとつづく", "ちょうだいする", "だんしゃくいも"]', '「国賓」đọc là「こくひん」(kokuhin) — Nghĩa: quốc khách.', 5, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[主賓]」trong ngữ cảnh: (khách quý)', '主賓', 'しゅひん', '["たいかんしき", "こうしゃく", "ろうおう", "しゅひん"]', '「主賓」đọc là「しゅひん」(shuhin) — Nghĩa: khách quý.', 6, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[総帥]」trong ngữ cảnh: (thống soái, người chỉ huy)', '総帥', 'そうすい', '["ひんきゃくをもてなす", "うよきょくせつ", "そうすい", "いっきょりょうとく"]', '「総帥」đọc là「そうすい」(sousui) — Nghĩa: thống soái, người chỉ huy.', 7, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[法曹]」trong ngữ cảnh: (nghề nghiệp liên quan tới pháp luật)', '法曹', 'ほうそう', '["いちもうだじん", "ほうそう", "じゅうそう", "しゅっけしてそうりょになる"]', '「法曹」đọc là「ほうそう」(housou) — Nghĩa: nghề nghiệp liên quan tới pháp luật.', 8, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[社長の御曹司]」trong ngữ cảnh: (công tử con trai của giám đốc)', '社長の御曹司', 'しゃちょうのおんぞうし', '["しゃちょうのおんぞうし", "あんちゅうもさく", "ちんはてんしのじしょう", "しょうい‐ちゅうい‐たいい"]', '「社長の御曹司」đọc là「しゃちょうのおんぞうし」(shachounoonzoushi) — Nghĩa: công tử con trai của giám đốc.', 9, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[重曹]」trong ngữ cảnh: (muối nở (baking soda))', '重曹', 'じゅうそう', '["ちょくし", "こくひん", "しょうしょ", "じゅうそう"]', '「重曹」đọc là「じゅうそう」(juusou) — Nghĩa: muối nở (baking soda).', 10, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[少尉‐中尉‐大尉]」trong ngữ cảnh: (thiếu úy- trung úy- đại úy)', '少尉‐中尉‐大尉', 'しょうい‐ちゅうい‐たいい', '["しこうさくご", "しゃちょうのおんぞうし", "しょうい‐ちゅうい‐たいい", "らいひんあいさつ"]', '「少尉‐中尉‐大尉」đọc là「しょうい‐ちゅうい‐たいい」(shouichuuitaii) — Nghĩa: thiếu úy- trung úy- đại úy.', 11, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[老翁]」trong ngữ cảnh: (ông lão)', '老翁', 'ろうおう', '["ほうそう", "ろうおう", "えっけんのあいだ", "ちゃくし"]', '「老翁」đọc là「ろうおう」(rouou) — Nghĩa: ông lão.', 12, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[嫡男]」trong ngữ cảnh: (con trai trưởng)', '嫡男', 'ちゃくなん', '["ちゃくなん", "ちょくご", "こくおうにえっけんする", "そうすい"]', '「嫡男」đọc là「ちゃくなん」(chakunan) — Nghĩa: con trai trưởng.', 13, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[嫡子]」trong ngữ cảnh: (con cả)', '嫡子', 'ちゃくし', '["こうていにはいえつする", "ちゃくちゃくとつづく", "ちょうだいする", "ちゃくし"]', '「嫡子」đọc là「ちゃくし」(chakushi) — Nghĩa: con cả.', 14, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[嫡嫡と続く]」trong ngữ cảnh: (đời này qua đời khác)', '嫡嫡と続く', 'ちゃくちゃくとつづく', '["たいかんしき", "こうしゃく", "ちゃくちゃくとつづく", "だんしゃくいも"]', '「嫡嫡と続く」đọc là「ちゃくちゃくとつづく」(chakuchakutotsuzuku) — Nghĩa: đời này qua đời khác.', 15, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LỮ]」(có được người bạn đời, xuất gia và trở thành tăng lữ) — Mẹo nhớ: Đơn giản có 18 LỮ khách . Nhìn giống số 18?', 'LỮ', '侶', '["戴", "賓", "帥", "侶"]', 'Chữ「侶」(LỮ) — có được người bạn đời, xuất gia và trở thành tăng lữ. Ví dụ: 人生の伴侶を得る（じんせいのはんりょをえる）.', 16, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[ĐÁI]」(lễ đăng quang, nhận) — Mẹo nhớ: đi Qua (戈) nghe tin ai bị ĐÁI đường thì không thể Nhận đc Đất (土) Cộng (共) vs Ruộng (田)?', 'ĐÁI', '戴', '["曹", "尉", "戴", "帥"]', 'Chữ「戴」(ĐÁI) — lễ đăng quang, nhận. Ví dụ: 戴冠式（たいかんしき）.', 17, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TÂN]」(lời chào của khách mời, tiếp đãi khách) — Mẹo nhớ: Người có Sò (貝) nhỏ (少) sẽ được đứng tiếp TÂN (tiếp khách)?', 'TÂN', '賓', '["嫡", "賓", "尉", "翁"]', 'Chữ「賓」(TÂN) — lời chào của khách mời, tiếp đãi khách. Ví dụ: 来賓挨拶（らいひんあいさつ）.', 18, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[SUẤT]」(thống soái) — Mẹo nhớ: Giáo Sư (師) bỏ mũ đi làm Tướng?', 'SUẤT', '帥', '["帥", "嫡", "爵", "侯"]', 'Chữ「帥」(SUẤT) — thống soái. Ví dụ: 総帥（そうすい）.', 19, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TÀO]」(nghề nghiệp liên quan tới pháp luật, công tử con trai của giám đốc) — Mẹo nhớ: mỗi một (ー) ca khúc (曲) của nam TÀO đều được cập nhật hàng ngày (日)?', 'TÀO', '曹', '["侯", "勅", "詔", "曹"]', 'Chữ「曹」(TÀO) — nghề nghiệp liên quan tới pháp luật, công tử con trai của giám đốc. Ví dụ: 法曹（ほうそう）.', 20, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[ÚY]」(thiếu úy- trung úy- đại úy) — Mẹo nhớ: Đại ÚY thốn (寸  ) khi ra chỉ thị (示 ) bắt ma (尸)?', 'ÚY', '尉', '["戴", "賓", "尉", "侶"]', 'Chữ「尉」(ÚY) — thiếu úy- trung úy- đại úy. Ví dụ: 少尉‐中尉‐大尉（しょうい‐ちゅうい‐たいい）.', 21, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[ÔNG]」(ông lão) — Mẹo nhớ: Vũ (羽)  công (公)  là 1 nghề không giành cho ÔNG già?', 'ÔNG', '翁', '["曹", "翁", "賓", "帥"]', 'Chữ「翁」(ÔNG) — ông lão. Ví dụ: 老翁（ろうおう）.', 22, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[ĐÍCH]」(con trai trưởng, con cả) — Mẹo nhớ: tìm 1 người phụ nữ (女) thích hợp là mục ĐÍCH hợp pháp của mỗi người đàn ông?', 'ĐÍCH', '嫡', '["嫡", "曹", "尉", "翁"]', 'Chữ「嫡」(ĐÍCH) — con trai trưởng, con cả. Ví dụ: 嫡男（ちゃくなん）.', 23, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TƯỚC]」(công tước, 1 loại khoai tây) — Mẹo nhớ: Có Chức TƯỚC mà thiếu Thốn (寸) Lương (艮) tâm thì không khác gì người mù Mắt?', 'TƯỚC', '爵', '["翁", "嫡", "侯", "爵"]', 'Chữ「爵」(TƯỚC) — công tước, 1 loại khoai tây. Ví dụ: 公爵（こうしゃく）.', 24, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[HẦU]」(hầu tước) — Mẹo nhớ: Hoàng Hậu (候) mất đi một người HẦU (侯)?', 'HẦU', '侯', '["勅", "詔", "侯", "爵"]', 'Chữ「侯」(HẦU) — hầu tước. Ví dụ: 侯爵（こうしゃく）.', 25, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 30;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_exercises WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[意気消沈]」trong ngữ cảnh: (Ý khí tiêu trầm (chán nản rầu rĩ))', '意気消沈', 'いきしょうちん', '["いきしょうちん", "れいせいちんちゃく", "うんめいにほんろうされる", "せんせんきょうきょう"]', '「意気消沈」đọc là「いきしょうちん」(ikishouchin) — Nghĩa: Ý khí tiêu trầm (chán nản rầu rĩ).', 1, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[意気投合]」trong ngữ cảnh: (Ý khí đầu hợp (tâm đầu ý hợp))', '意気投合', 'いきとうごう', '["じゃくしゃをぐろうする", "しゅぶそくとう", "いがた", "いきとうごう"]', '「意気投合」đọc là「いきとうごう」(ikitougou) — Nghĩa: Ý khí đầu hợp (tâm đầu ý hợp).', 2, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[感無量]」trong ngữ cảnh: (Cảm vô lượng (xúc động khôn nguôi))', '感無量', 'かんむりょう', '["ひょうりいったい", "あくせんくとう", "かんむりょう", "はたけのうねをつくる"]', '「感無量」đọc là「かんむりょう」(kanmuryou) — Nghĩa: Cảm vô lượng (xúc động khôn nguôi).', 3, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[切歯扼腕]」trong ngữ cảnh: (Thiết xỉ ách oãn (nghiến răng căm phẫn))', '切歯扼腕', 'せっしやくわん', '["きんこかたちにしょす", "せっしやくわん", "へいきへいぜん", "にっしんげっぽ"]', '「切歯扼腕」đọc là「せっしやくわん」(sesshiyakuwan) — Nghĩa: Thiết xỉ ách oãn (nghiến răng căm phẫn).', 4, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[戦々恐々]」trong ngữ cảnh: (Chiến chiến khủng khủng (nơm nớp lo sợ))', '戦々恐々', 'せんせんきょうきょう', '["せんせんきょうきょう", "はんしんはんぎ", "せんりつ", "ちょうれいぼかい"]', '「戦々恐々」đọc là「せんせんきょうきょう」(sensenkyoukyou) — Nghĩa: Chiến chiến khủng khủng (nơm nớp lo sợ).', 5, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[平気平然]」trong ngữ cảnh: (Bình khí bình nhiên (bình thản như không))', '平気平然', 'へいきへいぜん', '["たりきほんがん", "ひよくなとち", "むねんむそう", "へいきへいぜん"]', '「平気平然」đọc là「へいきへいぜん」(heikiheizen) — Nghĩa: Bình khí bình nhiên (bình thản như không).', 6, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[抱腹絶倒]」trong ngữ cảnh: (Bão phúc tuyệt đảo (cười ôm bụng lăn lộn))', '抱腹絶倒', 'ほうふくぜっとう', '["ねんどでつくられたそぞう", "ガスがすのじゅうてん", "ほうふくぜっとう", "むねんむそう"]', '「抱腹絶倒」đọc là「ほうふくぜっとう」(houfukuzettou) — Nghĩa: Bão phúc tuyệt đảo (cười ôm bụng lăn lộn).', 7, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[無念無想]」trong ngữ cảnh: (Vô niệm vô tưởng (tâm trí tĩnh lặng hoàn toàn))', '無念無想', 'むねんむそう', '["ぜったいぜつめい", "むねんむそう", "がでんいんすい", "あかじをほてんする"]', '「無念無想」đọc là「むねんむそう」(munenmusou) — Nghĩa: Vô niệm vô tưởng (tâm trí tĩnh lặng hoàn toàn).', 8, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[冷静沈着]」trong ngữ cảnh: (Lãnh tĩnh trầm착 (bình tĩnh điềm đạm))', '冷静沈着', 'れいせいちんちゃく', '["れいせいちんちゃく", "じんかくをとうやする", "しちてんばっとう", "ふとうふくつ"]', '「冷静沈着」đọc là「れいせいちんちゃく」(reiseichinchaku) — Nghĩa: Lãnh tĩnh trầm착 (bình tĩnh điềm đạm).', 9, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[和気藹々]」trong ngữ cảnh: (Hòa khí ái ái (bầu không khí đầm ấm hòa thuận))', '和気藹々', 'わきあいあい', '["ふとうふくつ", "じょうるり", "なきはらす", "わきあいあい"]', '「和気藹々」đọc là「わきあいあい」(wakiaiai) — Nghĩa: Hòa khí ái ái (bầu không khí đầm ấm hòa thuận).', 10, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[半信半疑]」trong ngữ cảnh: (Bán tín bán nghi (nửa tin nửa ngờ))', '半信半疑', 'はんしんはんぎ', '["いっしんいったい", "しめんそか", "はんしんはんぎ", "けんこんいってき"]', '「半信半疑」đọc là「はんしんはんぎ」(hanshinhangi) — Nghĩa: Bán tín bán nghi (nửa tin nửa ngờ).', 11, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[心機一転]」trong ngữ cảnh: (Tâm cơ nhất chuyển (đổi mới tâm thế))', '心機一転', 'しんきいってん', '["いもの", "しんきいってん", "しめんそか", "もうこはん"]', '「心機一転」đọc là「しんきいってん」(shinkiitten) — Nghĩa: Tâm cơ nhất chuyển (đổi mới tâm thế).', 12, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[灯篭に明かりをともす]」trong ngữ cảnh: (thắp đèn lồng)', '灯篭に明かりをともす', 'とうろうにあかりをともす', '["とうろうにあかりをともす", "ぐびじんそう", "うおうさおう", "めいよきそん"]', '「灯篭に明かりをともす」đọc là「とうろうにあかりをともす」(tourouniakariotomosu) — Nghĩa: thắp đèn lồng.', 13, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[魚を燻製にする]」trong ngữ cảnh: (làm món cá xông khói)', '魚を燻製にする', 'さかなをくんせいにする', '["かんむりょう", "せんぺんばんか", "はくせい", "さかなをくんせいにする"]', '「魚を燻製にする」đọc là「さかなをくんせいにする」(sakanaokunseinisuru) — Nghĩa: làm món cá xông khói.', 14, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[一挙両得]」trong ngữ cảnh: (Nhất cử lưỡng tiện (một công đôi việc))', '一挙両得', 'いっきょりょうとく', '["かへいをちゅうぞうする", "らつわんをふるう", "いっきょりょうとく", "じごうじとく"]', '「一挙両得」đọc là「いっきょりょうとく」(ikkyoryoutoku) — Nghĩa: Nhất cử lưỡng tiện (một công đôi việc).', 15, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[ĐIỀN]」(bù lỗ, bơm khí gas) — Mẹo nhớ: dùng đúng 10 (十) cái dụng cụ (具) để ĐIỀN đầy vào chỗ trống trên đất ( 土)?', 'ĐIỀN', '填', '["斑", "慄", "弄", "填"]', 'Chữ「填」(ĐIỀN) — bù lỗ, bơm khí gas. Ví dụ: 赤字を補填する（あかじをほてんする）.', 16, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[BAN]」(vết nám, vết bớt màu xanh ở trẻ sơ sinh) — Mẹo nhớ: 2 nhà Vua (王) ép làm Văn (文) sẽ bị sốt phát BAN?', 'BAN', '斑', '["憬", "毀", "斑", "弄"]', 'Chữ「斑」(BAN) — vết nám, vết bớt màu xanh ở trẻ sơ sinh. Ví dụ: 斑点（はんてん）.', 17, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LẬT]」(rùng mình) — Mẹo nhớ: LẬT em gái tây (西) dưới gốc (木) cây tim (忄) đập run rẩy?', 'LẬT', '慄', '["鬱", "慄", "毀", "蔽"]', 'Chữ「慄」(LẬT) — rùng mình. Ví dụ: 戦慄（せんりつ）.', 18, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LỘNG]」(đùa giỡn với cảm xúc của người khác, chế giễu người yếu đuối) — Mẹo nhớ: bó tay ( 廾 ) ông vua (王) LỘNG hành?', 'LỘNG', '弄', '["弄", "鬱", "沃", "辣"]', 'Chữ「弄」(LỘNG) — đùa giỡn với cảm xúc của người khác, chế giễu người yếu đuối. Ví dụ: 他人の気持ちを弄ぶ（たにんのきもちをもてあそぶ）.', 19, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[CẢNH]」(ấp ủ khát vọng) — Mẹo nhớ: CẢNH (景) tình xuất phái từ trái tim (忄)?', 'CẢNH', '憬', '["辣", "舷", "冶", "憬"]', 'Chữ「憬」(CẢNH) — ấp ủ khát vọng. Ví dụ: 憧憬を抱く（どうけいをだく）.', 20, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[HỦY]」(phỉ báng/ tổn hại danh dự) — Mẹo nhớ: dùng Vũ khí (殳)  phá HUỶ cái cối xay (臼)  bằng Đất (土)?', 'HỦY', '毀', '["瑠", "璃", "毀", "冶"]', 'Chữ「毀」(HỦY) — phỉ báng/ tổn hại danh dự. Ví dụ: 名誉毀損（めいよきそん）.', 21, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TẾ]」(che giấu bằng chứng) — Mẹo nhớ: dùng cỏ (艹) che lấp gạo  (米) 1 cách tinh TẾ?', 'TẾ', '蔽', '["璽", "蔽", "璃", "錮"]', 'Chữ「蔽」(TẾ) — che giấu bằng chứng. Ví dụ: 証拠隠蔽（しょうこいんぺい）.', 22, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[UẤT]」(khu rừng rậm rạp, buồn rầu) — Mẹo nhớ: Vào rừng (林) ném cái chai (缶) lung tung về nhà (冖) bị tên hung ác (凶) trên ngực 4 chấm cầm thìa (匕)  bạo hành đầu tóc (彡 ) bù xù cảm thấy UẤT ức?', 'UẤT', '鬱', '["鬱", "璽", "鋳", "塑"]', 'Chữ「鬱」(UẤT) — khu rừng rậm rạp, buồn rầu. Ví dụ: 憂鬱（ゆううつ）.', 23, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[ỐC]」(đất đai màu mỡ) — Mẹo nhớ: con ỐC (沃)  này sống dưới Thủy (氵) cung thịt rất mềm đc ng dân Yêu (夭)  mến?', 'ỐC', '沃', '["塑", "虞", "嗣", "沃"]', 'Chữ「沃」(ỐC) — đất đai màu mỡ. Ví dụ: 肥沃な土地（ひよくなとち）.', 24, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LẠT]」(ý kiến gay gắt, trở tài nhanh trí) — Mẹo nhớ: thằng Tân (辛) có vị sư Thúc (束)  ở dưới đà LẠT (辣)  rất gian ác?', 'LẠT', '辣', '["慄", "弄", "辣", "斑"]', 'Chữ「辣」(LẠT) — ý kiến gay gắt, trở tài nhanh trí. Ví dụ: 辛辣な意見（しんらつないけん）.', 25, NOW());
