END $$;

-- 5. SEED 30 MINIGAME クイズ GẮN ẢNH TRANG BÀI TẬP CHUẨN SÁCH GỐC
DO $$
DECLARE v_ch_id BIGINT; BEGIN
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 1;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_minigames WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES
        (v_ch_id, 'KANJI_CORRECTION', 'Minigame 1: 【1】 Chọn chữ Hán chuẩn xác & Điền cách đọc Hiragana (p.26)', 'Quan sát bài tập 【1】 trang 26 (1章・2章 クイズ). Trong mỗi câu dưới đây đang dùng chữ Hán gây nhiễu, hãy chọn chữ Hán đúng trong khung để sửa lại cho chuẩn ngữ cảnh:', 'https://bxqwarbeocbsfjieqbsq.supabase.co/storage/v1/object/public/kanji-assets/n1/quizzes/crops/ch01_g1.webp', '{"wordBank": ["磨", "排", "妨", "歓", "抹", "奮"], "questions": [{"id": 1, "sentence": "1. 毎日靴を { 摩 / 磨 } いてから、会社に出かける。（ みが ）いて", "wrongKanji": "摩", "correctKanji": "磨", "targetWord": "磨いて", "hiragana": "みがいて", "meaning": "Đánh bóng, chải (giày)", "explanation": "Đánh giày dùng chữ 磨 (MA - mài, đánh bóng): 靴を磨く（くつをみがく）。"}, {"id": 2, "sentence": "2. 大雨が降り、{ 排 / 拝 } 水溝から水があふれ出す。（ はい ）すいこう", "wrongKanji": "拝", "correctKanji": "排", "targetWord": "排水溝", "hiragana": "はいすいこう", "meaning": "Rãnh thoát nước", "explanation": "Thoát nước dùng chữ 排 (BÀI - bài tiết, đẩy ra): 排水溝（はいすいこう）。"}, {"id": 3, "sentence": "3. 観客が客席で大騒ぎをして試合を { 防 / 妨 } 害した。（ ぼう ）がい", "wrongKanji": "防", "correctKanji": "妨", "targetWord": "妨害", "hiragana": "ぼうがい", "meaning": "Cản trở, phá đám", "explanation": "Cản trở trận đấu dùng chữ 妨 (PHƯƠNG - cản trở): 妨害（ぼうがい）する。"}, {"id": 4, "sentence": "4. 新入社員の { 歓 / 観 } 迎会を企画する。（ かん ）げいかい", "wrongKanji": "観", "correctKanji": "歓", "targetWord": "歓迎会", "hiragana": "かんげいかい", "meaning": "Tiệc chào mừng", "explanation": "Tiệc chào mừng dùng chữ 歓 (HOAN - vui mừng): 歓迎会（かんげいかい）。"}, {"id": 5, "sentence": "5. けがで故障した選手を登録名簿から { 抹 / 挟 } 消する。（ まっ ）しょう", "wrongKanji": "挟", "correctKanji": "抹", "targetWord": "抹消", "hiragana": "まっしょう", "meaning": "Xóa bỏ tên khỏi danh sách", "explanation": "Xóa tên khỏi danh sách dùng chữ 抹 (MẠT - xóa bỏ): 抹消（まっしょう）する。"}, {"id": 6, "sentence": "6. 事故を目撃した男性が興 { 奮 / 奪 } した様子で、質問に答えた。こう（ ふん ）", "wrongKanji": "奪", "correctKanji": "奮", "targetWord": "興奮", "hiragana": "こうふん", "meaning": "Hưng phấn, kích động", "explanation": "Kích động/hưng phấn dùng chữ 奮 (PHẤN): 興奮（こうふん）する。"}]}', 1, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES
        (v_ch_id, 'SENTENCE_CLOZE', 'Minigame 2: 【2】 Ghép từ vựng 2 chữ Hán theo định nghĩa (p.26)', 'Quan sát bài tập 【2】 trang 26 (1章・2章 クイズ). Chọn chữ Hán thích hợp từ khung（貪・黙・駆・及・尽・遂）để hoàn thành từ ghép 2 chữ khớp với định nghĩa:', 'https://bxqwarbeocbsfjieqbsq.supabase.co/storage/v1/object/public/kanji-assets/n1/quizzes/crops/ch01_g2.webp', '{"wordBank": ["駆", "黙", "尽", "遂", "及", "貪"], "questions": [{"id": 1, "sentence": "1. 自由に使いこなすこと ── パソコンを [blank] 使する。（くし）", "answer": "駆", "targetWord": "駆使", "hiragana": "くし", "meaning": "Sử dụng thành thạo, vận dụng tối đa", "explanation": "駆使（くし）＝ 自由に使いこなすこと (Sử dụng thành thạo máy tính)."}, {"id": 2, "sentence": "2. 何も言わず、誰とも口をきかないこと ── 沈 [blank] を守る。（ちんもく）", "answer": "黙", "targetWord": "沈黙", "hiragana": "ちんもく", "meaning": "Sự im lặng, trầm mặc", "explanation": "沈黙（ちんもく）＝ 何も言わず、誰とも口をきかないこと (Giữ im lặng)."}, {"id": 3, "sentence": "3. あることの実現や人のために、力を惜しまず動くこと ── [blank] 力する。（じんりょく）", "answer": "尽", "targetWord": "尽力", "hiragana": "じんりょく", "meaning": "Tận lực, dốc hết sức lực", "explanation": "尽力（じんりょく）＝ 力を惜しまず動くこと (Dốc hết sức vì người khác)."}, {"id": 4, "sentence": "4. 任務や仕事を最後までやり通すこと ── [blank] 行する。（すいこう）", "answer": "遂", "targetWord": "遂行", "hiragana": "すいこう", "meaning": "Thực thi, hoàn thành nhiệm vụ đến cùng", "explanation": "遂行（すいこう）＝ 任務や仕事を最後までやり通すこと."}, {"id": 5, "sentence": "5. どこまでも追いつめること ── 責任を追 [blank] する。（ついきゅう）", "answer": "及", "targetWord": "追及", "hiragana": "ついきゅう", "meaning": "Truy cứu trách nhiệm đến cùng", "explanation": "追及（ついきゅう）＝ どこまでも追いつめること (Truy cứu trách nhiệm)."}, {"id": 6, "sentence": "6. 非常に欲の深いこと ── [blank] 欲に知識を吸収する。（どんよく）", "answer": "貪", "targetWord": "貪欲", "hiragana": "どんよく", "meaning": "Tham lam, khao khát mãnh liệt", "explanation": "貪欲（どんよく）＝ 非常に欲の深いこと (Khao khát tiếp thu kiến thức)."}]}', 2, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 2;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_minigames WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES
        (v_ch_id, 'RADICAL_COMBINE', 'Minigame 1: 【3】 Ghép bộ thủ Ⓐ (扌・足・忄) + Ⓑ tạo chữ Hán (p.27)', 'Quan sát bài tập 【3】 trang 27 (1章・2章 クイズ). Chọn một bộ thủ ở khung Ⓐ kết hợp với phần chữ ở khung Ⓑ để tạo thành chữ Hán điền vào chỗ trống:', 'https://bxqwarbeocbsfjieqbsq.supabase.co/storage/v1/object/public/kanji-assets/n1/quizzes/crops/ch02_g1.webp', '{"colA": ["扌", "足", "忄"], "colB": ["荒", "及", "沓", "空", "氏", "兆", "式", "真", "末"], "wordBank": ["慌", "抵", "扱", "控", "慎", "抹", "踏", "拭"], "questions": [{"id": 1, "sentence": "1. お金を落としたことに気づいて、（ [blank] ）てた。", "combine": "忄 + 荒", "answer": "慌", "targetWord": "慌てた", "hiragana": "あわてた", "meaning": "Hoảng hốt, cuống cuồng", "explanation": "Ghép bộ Tâm đứng (忄) + 荒 ＝ 慌（あわてる - hoảng hốt khi phát hiện rơi tiền）."}, {"id": 2, "sentence": "2. 仕事は大（ [blank] ）6時には終わる。", "combine": "扌 + 氏", "answer": "抵", "targetWord": "大抵", "hiragana": "たいてい", "meaning": "Thông thường, đại đa số", "explanation": "Ghép bộ Tài gảy (扌) + 氏 ＝ 抵 trong 大抵（たいてい - thường kết thúc lúc 6 giờ）."}, {"id": 3, "sentence": "3. その商品は当店では取り（ [blank] ）っておりません。", "combine": "扌 + 及", "answer": "扱", "targetWord": "取り扱って", "hiragana": "とりあつかって", "meaning": "Kinh doanh, xử lý mặt hàng", "explanation": "Ghép 扌 + 及 ＝ 扱 trong 取り扱う（とりあつかう - cửa hàng có/không bán sản phẩm）."}, {"id": 4, "sentence": "4. 会長の側に（ [blank] ）えて待つ。", "combine": "扌 + 空", "answer": "控", "targetWord": "控えて", "hiragana": "ひかえて", "meaning": "Túc trực, đứng chờ bên cạnh", "explanation": "Ghép 扌 + 空 ＝ 控 trong 控える（ひかえる - đứng túc trực chờ bên cạnh chủ tịch）."}, {"id": 5, "sentence": "5. この議題は（ [blank] ）重に検討を重ねる必要がある。", "combine": "忄 + 真", "answer": "慎", "targetWord": "慎重", "hiragana": "しんちょう", "meaning": "Thận trọng, kỹ lưỡng", "explanation": "Ghép 忄 + 真 ＝ 慎 trong 慎重（しんちょう - xem xét thận trọng）."}, {"id": 6, "sentence": "6. 茶室で（ [blank] ）茶をいただく。", "combine": "扌 + 末", "answer": "抹", "targetWord": "抹茶", "hiragana": "まっちゃ", "meaning": "Trà xanh Matcha", "explanation": "Ghép 扌 + 末 ＝ 抹 trong 抹茶（まっちゃ - thưởng thức trà Matcha trong phòng trà）."}, {"id": 7, "sentence": "7. 今年、生まれて初めてヨーロッパの土を（ [blank] ）んだ。", "combine": "足 + 沓", "answer": "踏", "targetWord": "踏んだ", "hiragana": "ふんだ", "meaning": "Đặt chân lên, giẫm lên", "explanation": "Ghép 足 + 沓 ＝ 踏 trong 足を踏み入れる / 土を踏む（つちをふむ - đặt chân tới châu Âu）."}, {"id": 8, "sentence": "8. テーブルの上が汚いね。台ふきんで（ [blank] ）こう。", "combine": "扌 + 式", "answer": "拭", "targetWord": "拭こう", "hiragana": "ふこう", "meaning": "Lau chùi", "explanation": "Ghép 扌 + 式 ＝ 拭 trong 拭く（ふく - lấy khăn lau bàn）."}]}', 1, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES
        (v_ch_id, 'SENTENCE_CLOZE', 'Minigame 2: 【4】 Chọn chữ Hán biểu đạt đúng tâm trạng & tình huống (p.27)', 'Quan sát bài tập 【4】 trang 27 (1章・2章 クイズ). Chọn chữ Hán phù hợp nhất với từng tình huống từ khung（耐・惑・驚・粘・免・慰・惜・焦・嘆）:', 'https://bxqwarbeocbsfjieqbsq.supabase.co/storage/v1/object/public/kanji-assets/n1/quizzes/crops/ch02_g2.webp', '{"wordBank": ["惜", "焦", "驚", "嘆", "慰", "耐", "粘", "惑", "免"], "questions": [{"id": 1, "sentence": "1. たった一点の差で、相手チームに負けてしまった。 ➔ [blank]", "answer": "惜", "targetWord": "惜しい", "hiragana": "おしい", "meaning": "Đáng tiếc (thua sát nút chỉ 1 điểm)", "explanation": "Thua chỉ 1 điểm duy nhất là tình huống vô cùng đáng tiếc: 惜（おしい / 惜敗）."}, {"id": 2, "sentence": "2. 提出期限が迫っているのに、全く課題に手をつけていない。 ➔ [blank]", "answer": "焦", "targetWord": "焦る", "hiragana": "あせる", "meaning": "Sốt ruột,焦 (tiêu) nôn nóng vì sát hạn nộp bài", "explanation": "Sát hạn nộp bài mà chưa làm gì cả gây tâm lý sốt ruột: 焦（あせる）."}, {"id": 3, "sentence": "3. クラスのマドンナだった彼女が問題児だった彼と結婚するなんて。 ➔ [blank]", "answer": "驚", "targetWord": "驚く", "hiragana": "おどろく", "meaning": "Kinh ngạc, bất ngờ", "explanation": "Hoa khôi của lớp lại kết hôn với cậu học trò cá biệt khiến ai nấy đều kinh ngạc: 驚（おどろく）."}, {"id": 4, "sentence": "4. バスや電車の中で、お年寄りに席を譲る人が少なくなったなあ。 ➔ [blank]", "answer": "嘆", "targetWord": "嘆く", "hiragana": "なげく", "meaning": "Than thở, buồn lòng trước thực trạng", "explanation": "Cảm thán, than thở vì ít người nhường ghế cho người già: 嘆（なげく / 嘆かわしい）."}, {"id": 5, "sentence": "5. 大丈夫。一生懸命やってもうまくいかないときだってあるよ。 ➔ [blank]", "answer": "慰", "targetWord": "慰める", "hiragana": "なぐさめる", "meaning": "An ủi, động viên", "explanation": "Lời động viên an ủi người khác khi thất bại: 慰（なぐさめる）."}, {"id": 6, "sentence": "6. 部屋が暑くてたまらないが、エアコンがないので、がまんするしかない。 ➔ [blank]", "answer": "耐", "targetWord": "耐える", "hiragana": "たえる", "meaning": "Chịu đựng (cái nóng)", "explanation": "Cố gắng chịu đựng phòng nóng không có điều hòa: 耐（たえる / 忍耐）."}, {"id": 7, "sentence": "7. お金がなく、コーヒー一杯だけで3時間も彼女を待った。 ➔ [blank]", "answer": "粘", "targetWord": "粘る", "hiragana": "ねばる", "meaning": "Kiên trì bám trụ, ngồi lì chờ đợi", "explanation": "Ngồi lì 3 tiếng chỉ với 1 cốc cà phê để chờ bạn gái: 粘（ねばる）."}, {"id": 8, "sentence": "8. 部署が異動になり仕事の内容が変わったが、まだよくわからないことが多い。 ➔ [blank]", "answer": "惑", "targetWord": "戸惑う", "hiragana": "とまどう", "meaning": "Bối rối, lúng túng", "explanation": "Chuyển bộ phận mới còn nhiều bỡ ngỡ lúng túng: 惑（とまどう / 困惑）."}, {"id": 9, "sentence": "9. もう少しで大事故になるところだったが、車同士の軽い接触で済んだ。 ➔ [blank]", "answer": "免", "targetWord": "免れる", "hiragana": "まぬがれる", "meaning": "Thoát khỏi (tai nạn lớn)", "explanation": "May mắn thoát khỏi vụ tai nạn nghiêm trọng: 免（まぬがれる）."}]}', 2, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 3;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_minigames WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES
        (v_ch_id, 'SENTENCE_CLOZE', 'Minigame 1: 【1】 Đọc thực đơn nhà hàng Nhật あずま亭 ～秋の季節料理～ (p.42)', 'Quan sát thực đơn nhà hàng Nhật truyền thống ở bài 【1】 trang 42 (3章・4章 クイズ). Chọn cách đọc Hiragana chính xác cho các từ gạch chân ① ～ ⑩:', 'https://bxqwarbeocbsfjieqbsq.supabase.co/storage/v1/object/public/kanji-assets/n1/quizzes/crops/ch03_g1.webp', '{"wordBank": ["てい", "もも", "こんぶ", "とうふ", "いため", "むし", "たきこみ", "くり", "つけもの", "かき"], "questions": [{"id": 1, "sentence": "① あずま亭（あずま [blank] ） ～秋の季節料理～", "answer": "てい", "targetWord": "あずま亭", "hiragana": "あずまてい", "meaning": "Nhà hàng Azuma-tei (Đình/Quán ăn truyền thống)", "explanation": "Chữ 亭 (ĐÌNH) trong tên nhà hàng đọc là てい (料亭・あずま亭)."}, {"id": 2, "sentence": "② 桃（ [blank] ）の食前酒", "answer": "もも", "targetWord": "桃", "hiragana": "もも", "meaning": "Rượu khai vị hương đào", "explanation": "Chữ 桃 (ĐÀO) đọc Kun-yomi là もも."}, {"id": 3, "sentence": "③ きのこのマリネ・昆布（ [blank] ）巻き", "answer": "こんぶ", "targetWord": "昆布", "hiragana": "こんぶ", "meaning": "Tảo bẹ Kombu cuộn", "explanation": "昆布（こんぶ）là tảo bẹ Nhật Bản."}, {"id": 4, "sentence": "④ ごま豆腐（ [blank] ）", "answer": "とうふ", "targetWord": "豆腐", "hiragana": "とうふ", "meaning": "Đậu phụ vừng (có thể đọc とうふ / どうふ)", "explanation": "豆腐 đọc là とうふ (khi ghép thành ごま豆腐 cũng đọc là ごまどうふ / ごまとうふ)."}, {"id": 5, "sentence": "⑤ 和牛と野菜のゆず胡椒炒め（ [blank] ）", "answer": "いため", "targetWord": "炒め", "hiragana": "いため", "meaning": "Bò Wagyu và rau củ xào tương ớt thanh yên Yuzu", "explanation": "Chữ 炒 (SAO - xào) đọc là いため（炒め）."}, {"id": 6, "sentence": "⑥ 茶碗蒸し（ちゃわん [blank] ）", "answer": "むし", "targetWord": "茶碗蒸し", "hiragana": "ちゃわんむし", "meaning": "Trứng hấp Chawanmushi", "explanation": "Chữ 蒸 (CHƯNG - hấp) trong 茶碗蒸し đọc là むし."}, {"id": 7, "sentence": "⑦ 炊き込み（ [blank] ）御飯", "answer": "たきこみ", "targetWord": "炊き込み", "hiragana": "たきこみ", "meaning": "Cơm nấu thập cẩm Takikomi-gohan", "explanation": "炊き込み御飯（たきこみごはん）dùng chữ 炊 (XUY - nấu cơm)."}, {"id": 8, "sentence": "⑧ 栗（ [blank] ）御飯", "answer": "くり", "targetWord": "栗", "hiragana": "くり", "meaning": "Cơm hạt dẻ mùa thu", "explanation": "Chữ 栗 (LẬT - hạt dẻ) đọc là くり."}, {"id": 9, "sentence": "⑨ 京野菜の漬け物（ [blank] ）", "answer": "つけもの", "targetWord": "漬け物", "hiragana": "つけもの", "meaning": "Dưa muối rau củ Kyoto", "explanation": "漬け物（つけもの）dùng chữ 漬 (TÍCH - ngâm, muối chua)."}, {"id": 10, "sentence": "⑩ 季節の果物（柿：[blank]）", "answer": "かき", "targetWord": "柿", "hiragana": "かき", "meaning": "Quả hồng (trái cây theo mùa)", "explanation": "Chữ 柿 (THỊ - quả hồng) đọc là かき."}]}', 1, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES
        (v_ch_id, 'RADICAL_COMBINE', 'Minigame 2: 【2】 Ghép chữ Hán khung Ⓐ + Ⓑ tạo từ ghép 2 chữ (p.42)', 'Quan sát bài tập 【2】 trang 42 (3章・4章 クイズ). Chọn một chữ Hán ở khung Ⓐ ghép với một chữ Hán ở khung Ⓑ để hoàn thành 8 câu văn:', 'https://bxqwarbeocbsfjieqbsq.supabase.co/storage/v1/object/public/kanji-assets/n1/quizzes/crops/ch03_g2.webp', '{"colA": ["孝", "校", "故", "縁", "匿", "婚", "遺", "沸"], "colB": ["姻", "騰", "人", "行", "起", "舎", "跡", "名"], "wordBank": ["婚姻", "匿名", "故人", "遺跡", "縁起", "校舎", "孝行", "沸騰"], "questions": [{"id": 1, "sentence": "1. 市役所に、[blank] 届を出す。", "combine": "婚 + 姻", "answer": "婚姻", "targetWord": "婚姻届", "hiragana": "こんいんとどけ", "meaning": "Giấy đăng ký kết hôn", "explanation": "Ghép 婚 + 姻 ＝ 婚姻（こんいん - nộp giấy đăng ký kết hôn tại tòa thị chính）."}, {"id": 2, "sentence": "2. [blank] で、新聞に投書する。", "combine": "匿 + 名", "answer": "匿名", "targetWord": "匿名", "hiragana": "とくめい", "meaning": "Nặc danh, ẩn danh", "explanation": "Ghép 匿 + 名 ＝ 匿名（とくめい - gửi bài đóng góp cho tòa soạn báo dưới tên ẩn danh）."}, {"id": 3, "sentence": "3. 思い出話をしながら、[blank] をしのぶ。", "combine": "故 + 人", "answer": "故人", "targetWord": "故人", "hiragana": "こじん", "meaning": "Người quá cố", "explanation": "Ghép 故 + 人 ＝ 故人（こじん - tưởng nhớ người đã khuất）."}, {"id": 4, "sentence": "4. [blank] 調査団が仏像三体を新たに発見した。", "combine": "遺 + 跡", "answer": "遺跡", "targetWord": "遺跡", "hiragana": "いせき", "meaning": "Di tích lịch sử, khảo cổ", "explanation": "Ghép 遺 + 跡 ＝ 遺跡（いせき - đoàn khảo sát di tích phát hiện thêm 3 pho tượng Phật）."}, {"id": 5, "sentence": "5. 茶柱が立つとは朝から [blank] がいい。", "combine": "縁 + 起", "answer": "縁起", "targetWord": "縁起", "hiragana": "えんぎ", "meaning": "Điềm lành, vận may", "explanation": "Ghép 縁 + 起 ＝ 縁起（えんぎがいい - cọng trà dựng đứng là điềm may từ sáng sớm）."}, {"id": 6, "sentence": "6. 中学校で、[blank] の改修工事が行われている。", "combine": "校 + 舎", "answer": "校舎", "targetWord": "校舎", "hiragana": "こうしゃ", "meaning": "Tòa nhà trường học", "explanation": "Ghép 校 + 舎 ＝ 校舎（こうしゃ - công trình tu sửa tòa nhà trường THCS）."}, {"id": 7, "sentence": "7. 親が元気なうちに、[blank] したいと思っている。", "combine": "孝 + 行", "answer": "孝行", "targetWord": "親孝行", "hiragana": "おやこうこう", "meaning": "Báo hiếu cha mẹ", "explanation": "Ghép 孝 + 行 ＝ 孝行（こうこう - báo hiếu khi cha mẹ còn khỏe mạnh）."}, {"id": 8, "sentence": "8. 人気 [blank] 中のアイドルのコンサートは観客数もすごい。", "combine": "沸 + 騰", "answer": "沸騰", "targetWord": "人気沸騰", "hiragana": "にんきふっとう", "meaning": "Nổi tiếng sôi sục, độ hot tăng vọt", "explanation": "Ghép 沸 + 騰 ＝ 沸騰（ふっとう - độ nổi tiếng đang sôi sục）."}]}', 2, NOW());
    END IF;
