        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES
        (v_ch_id, 'SENTENCE_CLOZE', 'Minigame 1: 【3】 Hội thoại đám cưới — Chuyển từ Hiragana sang chữ Hán (p.43)', 'Quan sát đoạn hội thoại giữa anh Wakita và anh Sato ở bài 【3】 trang 43 (3章・4章 クイズ). Chọn từ chữ Hán đúng cho các ô trống ① ～ ⑥（しんせき・おんし・えん・れいじょう・はなよめ・しんろう）:', 'https://bxqwarbeocbsfjieqbsq.supabase.co/storage/v1/object/public/kanji-assets/n1/quizzes/crops/ch04_g1.webp', '{"wordBank": ["花嫁", "令嬢", "親戚", "新郎", "恩師", "縁"], "questions": [{"id": 1, "sentence": "佐藤：「わあ、さなえさん、きれいですね。①（ [blank] ）衣装も豪華！」", "answer": "花嫁", "targetWord": "花嫁衣装", "hiragana": "はなよめいしょう", "meaning": "Trang phục cô dâu", "explanation": "はなよめ viết chữ Hán là 花嫁（花嫁衣装 - váy cưới cô dâu lộng lẫy）."}, {"id": 2, "sentence": "湧田：「ほら、彼女は建設会社の社長②（ [blank] ）だから…」", "answer": "令嬢", "targetWord": "社長令嬢", "hiragana": "しゃちょうれいじょう", "meaning": "Ái nữ / Tiểu thư con gái giám đốc", "explanation": "れいじょう viết chữ Hán là 令嬢（cách gọi trang trọng con gái người khác）."}, {"id": 3, "sentence": "湧田：「…③（ [blank] ）の他にもお父様の会社関係の方がたくさん来て、盛大でしたよ。」", "answer": "親戚", "targetWord": "親戚", "hiragana": "しんせき", "meaning": "Họ hàng thân thích", "explanation": "しんせき viết chữ Hán là 親戚（ngoài họ hàng còn có rất nhiều đối tác công ty của bố cô dâu）."}, {"id": 4, "sentence": "佐藤：「へえ。ああ、この人は④（ [blank] ）の…明さんでしたっけ。すてきですね。」", "answer": "新郎", "targetWord": "新郎", "hiragana": "しんろう", "meaning": "Chú rể", "explanation": "しんろう viết chữ Hán là 新郎（chú rể Akira）."}, {"id": 5, "sentence": "湧田：「高校の⑤（ [blank] ）のスピーチで感極まって泣いていましたし。」", "answer": "恩師", "targetWord": "恩師", "hiragana": "おんし", "meaning": "Thầy cô giáo cũ (ân sư)", "explanation": "おんし viết chữ Hán là 恩師（xúc động bật khóc trước bài phát biểu của thầy giáo cấp 3）."}, {"id": 6, "sentence": "佐藤：「へえ、そういう⑥（ [blank] ）があったんですね。」", "answer": "縁", "targetWord": "縁", "hiragana": "えん", "meaning": "Nhân duyên, mối duyên", "explanation": "えん viết chữ Hán là 縁（mối nhân duyên gặp gỡ giữa hai người）."}]}', 1, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES
        (v_ch_id, 'SENTENCE_CLOZE', 'Minigame 2: 【4】 Lời nhắn của mẹ để lại trên bàn (置き手紙) (p.43)', 'Quan sát bức thư nhắn của mẹ ở bài 【4】 trang 43 (3章・4章 クイズ). Chọn chữ Hán thích hợp từ khung（盆・栓・鉢・縁・房・墓）điền vào chỗ trống:', 'https://bxqwarbeocbsfjieqbsq.supabase.co/storage/v1/object/public/kanji-assets/n1/quizzes/crops/ch04_g2.webp', '{"wordBank": ["墓", "縁", "鉢", "栓", "盆", "房"], "questions": [{"id": 1, "sentence": "1. おばあちゃんのお [blank]（はか）参りに行ってきます。", "answer": "墓", "targetWord": "お墓参り", "hiragana": "おはかまいり", "meaning": "Đi viếng mộ bà", "explanation": "お墓参り（おはかまいり）dùng chữ 墓 (MỘ) đọc là はか."}, {"id": 2, "sentence": "2. 4時を過ぎたら、[blank] 側（えんがわ）にある…", "answer": "縁", "targetWord": "縁側", "hiragana": "えんがわ", "meaning": "Hiên nhà kiểu Nhật", "explanation": "縁側（えんがわ）dùng chữ 縁 (DUYÊN) đọc là えん."}, {"id": 3, "sentence": "3. …縁側にある [blank] 植え（はちうえ）を室内に入れてください。", "answer": "鉢", "targetWord": "鉢植え", "hiragana": "はちうえ", "meaning": "Chậu cây cảnh", "explanation": "鉢植え（はちうえ）dùng chữ 鉢 (BÁT - chậu cây) đọc là はち."}, {"id": 4, "sentence": "4. 水を入れるときはお風呂の [blank]（せん）をするのを忘れずに。", "answer": "栓", "targetWord": "栓", "hiragana": "せん", "meaning": "Nút chặn bồn tắm", "explanation": "お風呂の栓（せん）dùng chữ 栓 (XUYÊN - nút đóng/vòi)."}, {"id": 5, "sentence": "5. 晩御飯はカレーです。お [blank]（ぼん）の上に置いてあるお皿を電子レンジで温めてください。", "answer": "盆", "targetWord": "お盆", "hiragana": "おぼん", "meaning": "Cái khay, cái mâm", "explanation": "お盆（おぼん）dùng chữ 盆 (BỒN - cái khay đựng bát đĩa)."}, {"id": 6, "sentence": "6. 寒かったら、床暖 [blank]（ゆかだんぼう）をつけてね。", "answer": "房", "targetWord": "床暖房", "hiragana": "ゆかだんぼう", "meaning": "Hệ thống sưởi sàn nhà", "explanation": "床暖房（ゆかだんぼう）dùng chữ 房 (PHÒNG) đọc là ぼう."}]}', 2, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 5;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_minigames WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES
        (v_ch_id, 'SENTENCE_CLOZE', 'Minigame 1: 【1】 Ghép thành ngữ / từ ghép 4 chữ Hán theo định nghĩa (p.58)', 'Quan sát bài tập 【1】 trang 58 (5章・6章 クイズ). Chọn các chữ Hán trong khung để hoàn thành từ ghép 4 chữ（四字熟語・複合語）khớp với định nghĩa:', 'https://bxqwarbeocbsfjieqbsq.supabase.co/storage/v1/object/public/kanji-assets/n1/quizzes/crops/ch05_g1.webp', '{"wordBank": ["自信過剰", "徐行運転", "喜怒哀楽", "明朗活発", "一目瞭然"], "questions": [{"id": 1, "sentence": "1. 必要以上に自分の能力が高いと思うこと ➔ 【 自 】[blank]（じしんかじょう）", "answer": "自信過剰", "targetWord": "自信過剰", "hiragana": "じしんかじょう", "meaning": "Tự tin thái quá (đánh giá năng lực bản thân cao hơn thực tế)", "explanation": "Ghép 自 + 信 + 過 + 剰 ＝ 自信過剰（じしんかじょう）."}, {"id": 2, "sentence": "2. 速度を落としてゆっくり運転すること ➔ [blank]（【 行 】）（じょこううんてん）", "answer": "徐行運転", "targetWord": "徐行運転", "hiragana": "じょこううんてん", "meaning": "Lái xe giảm tốc độ từ từ (Từ hành vận chuyển)", "explanation": "Ghép 徐 + 行 + 運 + 転 ＝ 徐行運転（じょこううんてん）."}, {"id": 3, "sentence": "3. 人間のさまざまな感情 ➔ [blank]（【 楽 】）（きどあいらく）", "answer": "喜怒哀楽", "targetWord": "喜怒哀楽", "hiragana": "きどあいらく", "meaning": "Hỷ nộ ái lạc (Vui, giận, buồn, sướng — đủ mọi cung bậc cảm xúc)", "explanation": "Ghép 喜 + 怒 + 哀 + 楽 ＝ 喜怒哀楽（きどあいらく）."}, {"id": 4, "sentence": "4. 性格が明るく朗らかで元気なこと ➔ [blank]（【 活 】）（めいろうかっぱつ）", "answer": "明朗活発", "targetWord": "明朗活発", "hiragana": "めいろうかっぱつ", "meaning": "Tính cách tươi sáng, cởi mở và hoạt bát năng động", "explanation": "Ghép 明 + 朗 + 活 + 発 ＝ 明朗活発（めいろうかっぱつ）."}, {"id": 5, "sentence": "5. ひと目見ただけではっきりわかること ➔ [blank]（【 目 】）（いちもくりょうぜん）", "answer": "一目瞭然", "targetWord": "一目瞭然", "hiragana": "いちもくりょうぜん", "meaning": "Nhìn qua một cái là hiểu rõ mồn một (Nhất mục liễu nhiên)", "explanation": "Ghép 一 + 目 + 瞭 + 然 ＝ 一目瞭然（いちもくりょうぜん）."}]}', 1, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES
        (v_ch_id, 'SENTENCE_CLOZE', 'Minigame 2: 【2】 Tìm từ có cách đọc chữ Hán gạch chân khác biệt (p.58)', 'Quan sát bài tập 【2】 trang 58 (5章・6章 クイズ). Trong mỗi nhóm 4 từ ①～④, hãy chọn duy nhất 1 từ có cách đọc của chữ Hán gạch chân khác với 3 từ còn lại:', 'https://bxqwarbeocbsfjieqbsq.supabase.co/storage/v1/object/public/kanji-assets/n1/quizzes/crops/ch05_g2.webp', '{"wordBank": ["③ 凡例 (はんれい)", "① 背丈 (せたけ)", "④ 旬の野菜 (しゅん)", "② 陰気 (いんき)", "① 悲惨 (ひさん)"], "questions": [{"id": 1, "sentence": "1. Chữ【凡】：①平凡　②非凡　③凡例　④凡人 ➔ Từ đọc khác là [blank]", "answer": "③ 凡例 (はんれい)", "targetWord": "凡例", "hiragana": "はんれい", "meaning": "Phàm lệ / Quy ước trình bày đầu sách (đọc là はん, còn lại đọc là ぼん)", "explanation": "①平凡(へいぼん)、②非凡(ひぼん)、④凡人(ぼんじん) đều đọc là「ぼん」; riêng ③凡例 đọc là「はんれい」."}, {"id": 2, "sentence": "2. Chữ【丈】：①背丈　②丈夫　③頑丈　④大丈夫 ➔ Từ đọc khác là [blank]", "answer": "① 背丈 (せたけ)", "targetWord": "背丈", "hiragana": "せたけ", "meaning": "Chiều cao cơ thể (đọc Kun là たけ, còn lại đọc On là じょう)", "explanation": "①背丈 đọc là「せたけ」; còn ②丈夫(じょうぶ)、③頑丈(がんじょう)、④大丈夫(だいじょうぶ) đều đọc là「じょう」."}, {"id": 3, "sentence": "3. Chữ【旬】：①上旬　②下旬　③初旬　④旬の野菜 ➔ Từ đọc khác là [blank]", "answer": "④ 旬の野菜 (しゅん)", "targetWord": "旬の野菜", "hiragana": "しゅんのやさい", "meaning": "Rau củ đúng mùa (đọc là しゅん, còn lại biến âm thành じゅん)", "explanation": "①上旬(じょうじゅん)、②下旬(げじゅん)、③初旬(しょじゅん) đều đọc là「じゅん」; riêng ④旬の野菜 đọc là「しゅん」."}, {"id": 4, "sentence": "4. Chữ【陰】：①陰口　②陰気　③日陰　④木陰 ➔ Từ đọc khác là [blank]", "answer": "② 陰気 (いんき)", "targetWord": "陰気", "hiragana": "いんき", "meaning": "U ám, ảm đạm (đọc On là いん, còn lại đọc Kun là かげ)", "explanation": "①陰口(かげぐち)、③日陰(ひかげ)、④木陰(こかげ) đều đọc là「かげ」; riêng ②陰気 đọc là「いんき」."}, {"id": 5, "sentence": "5. Chữ【惨】：①悲惨　②惨敗　③無惨　④惨殺 ➔ Từ đọc khác là [blank]", "answer": "① 悲惨 (ひさん)", "targetWord": "悲惨", "hiragana": "ひさん", "meaning": "Bi thảm (đọc là さん, còn lại đọc là ざん)", "explanation": "①悲惨 đọc là「ひさん」; còn ②惨敗(ざんぱい)、③無惨(むざん)、④惨殺(ざんさつ) đều đọc là「ざん」."}]}', 2, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 6;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_minigames WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES
        (v_ch_id, 'KANJI_CROSS', 'Minigame 1: 【3】 Ô chữ chữ thập Kanji 4 hướng tâm điểm (p.59)', 'Quan sát bài tập 【3】 trang 59 (5章・6章 クイズ). Chọn chữ Hán tâm điểm từ khung（徴・穏・微・壮・裕・奇）để tạo thành các từ ghép có nghĩa:', 'https://bxqwarbeocbsfjieqbsq.supabase.co/storage/v1/object/public/kanji-assets/n1/quizzes/crops/ch06_g1.webp', '{"wordBank": ["穏", "徴", "奇", "裕", "壮", "微"], "puzzles": [{"id": 1, "top": "不", "bottom": "便", "left": "平", "right": "和", "answer": "穏", "words": ["不穏 (ふおん - Bất ổn)", "平穏 (へいおん - Bình ổn)", "穏便 (おんびん - Ôn hòa, êm thấm)"], "hint": "Chữ 穏 (ỔN): 不穏・平穏・穏便"}, {"id": 2, "top": "特", "bottom": "兵", "left": "象", "right": "収", "answer": "徴", "words": ["特徴 (とくちょう - Đặc trưng)", "象徴 (しょうちょう - Biểu tượng)", "徴収 (ちょうしゅう - Thu phí/thuế)"], "hint": "Chữ 徴 (TRƯNG): 特徴・象徴・徴収"}, {"id": 3, "top": "怪", "bottom": "抜", "left": "珍", "right": "跡", "answer": "奇", "words": ["奇怪 (きかい - Kỳ quái)", "奇抜 (きばつ - Độc lạ)", "奇跡 (きせき - Kỳ tích)"], "hint": "Chữ 奇 (KỲ): 奇怪・奇抜・奇跡"}, {"id": 4, "top": "余", "bottom": "度", "left": "富", "right": "福", "answer": "裕", "words": ["余裕 (よゆう - Dư dả)", "富裕 (ふゆう - Phú quý giàu có)", "裕福 (ゆうふく - Sung túc)"], "hint": "Chữ 裕 (DỤ): 余裕・富裕・裕福"}, {"id": 5, "top": "悲", "bottom": "年", "left": "勇", "right": "大", "answer": "壮", "words": ["勇壮 (ゆうそう - Hùng dũng)", "壮大 (そうだい - Hùng vĩ, tráng lệ)", "壮年 (そうねん - Tráng niên)"], "hint": "Chữ 壮 (TRÁNG): 勇壮・壮大・壮年"}, {"id": 6, "top": "軽", "bottom": "力", "left": "機", "right": "笑", "answer": "微", "words": ["機微 (きび - Sự tinh tế sâu kín)", "微笑 (びしょう - Mỉm cười)", "微力 (びりょく - Sức mọn)"], "hint": "Chữ 微 (VI): 機微・微笑・微力"}]}', 1, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES
        (v_ch_id, 'KANJI_CORRECTION', 'Minigame 2: 【4】 Chọn chữ Hán chuẩn xác & Điền cách đọc Hiragana (p.59)', 'Quan sát bài tập 【4】 trang 59 (5章・6章 クイズ). Chọn chữ Hán đúng để sửa lỗi từ vựng trong mỗi câu và kiểm tra cách đọc Hiragana:', 'https://bxqwarbeocbsfjieqbsq.supabase.co/storage/v1/object/public/kanji-assets/n1/quizzes/crops/ch06_g2.webp', '{"wordBank": ["穏やか", "滑降", "余裕", "微力"], "questions": [{"id": 1, "sentence": "1. 彼女は何があってもいつも { 穏やか / 隠やか } だ。（ おだやか ）", "wrongKanji": "隠やか", "correctKanji": "穏やか", "targetWord": "穏やか", "hiragana": "おだやか", "meaning": "Điềm đạm, ôn hòa", "explanation": "Điềm đạm ôn hòa dùng chữ 穏 (ỔN): 穏やか（おだやか）。"}, {"id": 2, "sentence": "2. 父は大学生の時、{ 滑降 / 骨降 } 競技の選手だった。（ かっこう ）", "wrongKanji": "骨降", "correctKanji": "滑降", "targetWord": "滑降", "hiragana": "かっこう", "meaning": "Môn trượt tuyết đổ đèo (Downhill skiing)", "explanation": "Trượt tuyết đổ đèo dùng chữ 滑 (HOẠT - trượt): 滑降（かっこう）。"}, {"id": 3, "sentence": "3. スピーチの時は周りを見る { 余祐 / 余裕 } は全然なかった。（ よゆう ）", "wrongKanji": "余祐", "correctKanji": "余裕", "targetWord": "余裕", "hiragana": "よゆう", "meaning": "Sự bình tĩnh, dư dả (thời gian/tâm trí)", "explanation": "Dư dả/bình tĩnh dùng chữ 裕 (DỤ - bộ Y 衤): 余裕（よゆう）。"}, {"id": 4, "sentence": "4. { 微力 / 徴力 } ながら、精一杯務めさせていただきます。（ びりょく ）", "wrongKanji": "徴力", "correctKanji": "微力", "targetWord": "微力", "hiragana": "びりょく", "meaning": "Sức mọn, chút sức lực nhỏ bé", "explanation": "Khiêm nhường nói về sức lực nhỏ bé của mình dùng chữ 微 (VI): 微力（びりょく）ながら。"}]}', 2, NOW());
    END IF;
