        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES
        (v_ch_id, 'SENTENCE_CLOZE', 'Minigame 1: 【1-A】 Tục ngữ động vật Nhật Bản — Điền chữ Hán loài vật (p.74)', 'Quan sát bài tập 【1】 trang 74 (7章・8章 クイズ). Chọn chữ Hán chỉ loài động vật thích hợp từ khung（鳩・雀・猿・虎・蛇・馬・犬・鶴・鴨）để hoàn thành 9 câu tục ngữ:', 'https://bxqwarbeocbsfjieqbsq.supabase.co/storage/v1/object/public/kanji-assets/n1/quizzes/crops/ch07_g1.webp', '{"wordBank": ["猿", "鳩", "雀", "虎", "蛇", "馬", "鴨", "犬", "鶴"], "questions": [{"id": 1, "sentence": "1. [blank] も木から落ちる（さるもきからおちる）", "answer": "猿", "targetWord": "猿も木から落ちる", "hiragana": "さるもきからおちる", "meaning": "Khỉ cũng có lúc ngã cây (Nghĩa A: Chuyên gia giỏi đến mấy đôi khi cũng mắc sai lầm)", "explanation": "猿（さる - Khỉ）＋ 意味 A: その道にすぐれた者でも、時には失敗することがあるということ。"}, {"id": 2, "sentence": "2. [blank] が豆鉄砲を食ったよう（はとがまめでっぽうをくったよう）", "answer": "鳩", "targetWord": "鳩が豆鉄砲を食ったよう", "hiragana": "はとがまめでっぽうをくったよう", "meaning": "Ngơ ngác như chim bồ câu trúng đạn đậu (Nghĩa F: Sững sờ kinh ngạc vì chuyện bất ngờ)", "explanation": "鳩（はと - Chim bồ câu）＋ 意味 F: 突然の事にびっくりしている様子。"}, {"id": 3, "sentence": "3. [blank] の涙（すずめのなみだ）", "answer": "雀", "targetWord": "雀の涙", "hiragana": "すずめのなみだ", "meaning": "Nước mắt chim sẻ (Nghĩa C: Vô cùng ít ỏi, chẳng đáng là bao)", "explanation": "雀（すずめ - Chim sẻ）＋ 意味 C: ごくわずかなもの。"}, {"id": 4, "sentence": "4. [blank] 口を脱する（ここうをだっする）", "answer": "虎", "targetWord": "虎口を脱する", "hiragana": "ここうをだっする", "meaning": "Thoát khỏi miệng hổ (Nghĩa H: Thoát chết khỏi nơi hoặc tình thế cực kỳ nguy hiểm)", "explanation": "虎（とら／こ - Hổ）＋ 意味 H: 危険な場所や状態からやっとのがれること。"}, {"id": 5, "sentence": "5. [blank] の道は蛇（じゃのみちはへび）", "answer": "蛇", "targetWord": "蛇の道は蛇", "hiragana": "じゃのみちはへび", "meaning": "Đường đi của rắn thì rắn biết (Nghĩa E: Người cùng nghề mới hiểu rõ mánh khóe của nhau)", "explanation": "蛇（じゃ／へび - Rắn）＋ 意味 E: 同類のすることは、その方面の者にはすぐわかること。"}, {"id": 6, "sentence": "6. [blank] が合う（うまがあう）", "answer": "馬", "targetWord": "馬が合う", "hiragana": "うまがあう", "meaning": "Tâm đầu ý hợp (Nghĩa B: Tính tình rất hợp nhau)", "explanation": "馬（うま - Ngựa）＋ 意味 B: 気がよく合うこと。"}, {"id": 7, "sentence": "7. [blank] が葱を背負って来る（かもがねぎをしょってくる）", "answer": "鴨", "targetWord": "鴨が葱を背負って来る", "hiragana": "かもがねぎをしょってくる", "meaning": "Vịt trời lại cõng thêm hành bước tới (Nghĩa D: Chuyện tốt lành/món hời bất ngờ trùng hợp kéo đến)", "explanation": "鴨（かも - Vịt trời）＋ 意味 D: うまい話が思いがけず、重なってやってくること。"}, {"id": 8, "sentence": "8. [blank] 猿の仲（けんえんのなか）", "answer": "犬", "targetWord": "犬猿の仲", "hiragana": "けんえんのなか", "meaning": "Quan hệ chó với khỉ / Ghét nhau như chó với mèo (Nghĩa I: Quan hệ vô cùng bất hòa)", "explanation": "犬（いぬ／けん - Chó）＋ 意味 I: 仲の悪いもの。"}, {"id": 9, "sentence": "9. [blank] の一声（つるのひとこえ）", "answer": "鶴", "targetWord": "鶴の一声", "hiragana": "つるのひとこえ", "meaning": "Một tiếng kêu của chim hạc (Nghĩa G: Lời phán quyết của người có quyền uy dẹp yên mọi tranh luận)", "explanation": "鶴（つる - Chim hạc）＋ 意味 G: 多くの人の議論や意見をおさえつける、有力者・権威者の一言。"}]}', 1, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES
        (v_ch_id, 'SENTENCE_CLOZE', 'Minigame 2: 【1-B】 Giải nghĩa 9 câu tục ngữ động vật A ～ I (p.74)', 'Quan sát khung giải nghĩa A ～ I ở bài 【1】 trang 74 (7章・8章 クイズ). Chọn ký hiệu ý nghĩa（A ～ I）tương ứng với từng câu tục ngữ:', 'https://bxqwarbeocbsfjieqbsq.supabase.co/storage/v1/object/public/kanji-assets/n1/quizzes/crops/ch07_g2.webp', '{"wordBank": ["A", "F", "C", "H", "E", "B", "D", "I", "G"], "questions": [{"id": 1, "sentence": "1. 猿も木から落ちる ── 意味（ [blank] ）：その道にすぐれた者でも、時には失敗することがある", "answer": "A", "targetWord": "猿も木から落ちる", "hiragana": "さるもきからおちる", "meaning": "A: Người tài giỏi chuyên môn đến mấy cũng có lúc thất bại", "explanation": "Đáp án chuẩn p.241: 1. 猿、A."}, {"id": 2, "sentence": "2. 鳩が豆鉄砲を食ったよう ── 意味（ [blank] ）：突然の事にびっくりしている様子", "answer": "F", "targetWord": "鳩が豆鉄砲を食ったよう", "hiragana": "はとがまめでっぽうをくったよう", "meaning": "F: Bộ dạng ngạc nhiên sững sờ trước sự việc đột ngột", "explanation": "Đáp án chuẩn p.241: 2. 鳩、F."}, {"id": 3, "sentence": "3. 雀の涙 ── 意味（ [blank] ）：ごくわずかなもの", "answer": "C", "targetWord": "雀の涙", "hiragana": "すずめのなみだ", "meaning": "C: Thứ vô cùng ít ỏi, nhỏ bé", "explanation": "Đáp án chuẩn p.241: 3. 雀、C."}, {"id": 4, "sentence": "4. 虎口を脱する ── 意味（ [blank] ）：危険な場所や状態からやっとのがれること", "answer": "H", "targetWord": "虎口を脱する", "hiragana": "ここうをだっする", "meaning": "H: Thoát khỏi nơi hoặc tình trạng cực kỳ nguy hiểm", "explanation": "Đáp án chuẩn p.241: 4. 虎、H."}, {"id": 5, "sentence": "5. 蛇の道は蛇 ── 意味（ [blank] ）：同類のすることは、その方面の者にはすぐわかること", "answer": "E", "targetWord": "蛇の道は蛇", "hiragana": "じゃのみちはへび", "meaning": "E: Việc của người cùng giới thì người trong ngành nhìn là hiểu ngay", "explanation": "Đáp án chuẩn p.241: 5. 蛇、E."}, {"id": 6, "sentence": "6. 馬が合う ── 意味（ [blank] ）：気がよく合うこと", "answer": "B", "targetWord": "馬が合う", "hiragana": "うまがあう", "meaning": "B: Tâm đầu ý hợp", "explanation": "Đáp án chuẩn p.241: 6. 馬、B."}, {"id": 7, "sentence": "7. 鴨が葱を背負って来る ── 意味（ [blank] ）：うまい話が思いがけず、重なってやってくること", "answer": "D", "targetWord": "鴨が葱を背負って来る", "hiragana": "かもがねぎをしょってくる", "meaning": "D: Chuyện tốt lành/thuận lợi bất ngờ nối tiếp nhau kéo đến", "explanation": "Đáp án chuẩn p.241: 7. 鴨、D."}, {"id": 8, "sentence": "8. 犬猿の仲 ── 意味（ [blank] ）：仲の悪いもの", "answer": "I", "targetWord": "犬猿の仲", "hiragana": "けんえんのなか", "meaning": "I: Mối quan hệ vô cùng bất hòa, xung khắc", "explanation": "Đáp án chuẩn p.241: 8. 犬、I."}, {"id": 9, "sentence": "9. 鶴の一声 ── 意味（ [blank] ）：多くの人の議論や意見をおさえつける、有力者・権威者の一言", "answer": "G", "targetWord": "鶴の一声", "hiragana": "つるのひとこえ", "meaning": "G: Lời nói quyết định của người có uy quyền chốt lại mọi tranh cãi", "explanation": "Đáp án chuẩn p.241: 9. 鶴、G."}]}', 2, NOW());
    END IF;
