        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES
        (v_ch_id, 'SENTENCE_CLOZE', 'Minigame 1: 【2-A】 Thông báo từ Sở thú ARC — Khu thú dữ, Đồi khỉ & Nhà gấu ①～⑧ (p.75)', 'Quan sát tờ thông báo「ARC動物園からのお知らせ — 今月の動物達」trang 75 (7章・8章 クイズ). Chọn cách đọc Hiragana chính xác cho các từ gạch chân từ ① đến ⑧:', 'https://bxqwarbeocbsfjieqbsq.supabase.co/storage/v1/object/public/kanji-assets/n1/quizzes/crops/ch08_g1.webp', '{"wordBank": ["もうじゅう", "とら", "きば", "えさ", "さる", "じゅもく", "くま", "おす"], "questions": [{"id": 1, "sentence": "① 【猛獣エリア】（ [blank] エリア）", "answer": "もうじゅう", "targetWord": "猛獣", "hiragana": "もうじゅう", "meaning": "Khu vực thú dữ (Mãnh thú)", "explanation": "猛獣 đọc là もうじゅう."}, {"id": 2, "sentence": "② 虎（ [blank] ）のミーコが…", "answer": "とら", "targetWord": "虎", "hiragana": "とら", "meaning": "Chú hổ Miiko", "explanation": "Chữ 虎 đọc Kun-yomi là とら."}, {"id": 3, "sentence": "③ …牙（ [blank] ）をむいて…", "answer": "きば", "targetWord": "牙", "hiragana": "きば", "meaning": "Nhe răng nanh", "explanation": "牙をむく（きばをむく - nhe nanh）."}, {"id": 4, "sentence": "④ …餌（ [blank] ）を食べる姿は迫力満点です。", "answer": "えさ", "targetWord": "餌", "hiragana": "えさ", "meaning": "Thức ăn cho thú / Mồi ăn", "explanation": "Chữ 餌 đọc là えさ."}, {"id": 5, "sentence": "⑤ 【猿山】（ [blank] やま）・猿達が元気に遊ぶ姿を見ていただけます。", "answer": "さる", "targetWord": "猿", "hiragana": "さる", "meaning": "Đồi khỉ / Đàn khỉ", "explanation": "Chữ 猿 đọc Kun-yomi là さる."}, {"id": 6, "sentence": "⑥ 樹木（ [blank] ）を植え、ロープなども増やしました。", "answer": "じゅもく", "targetWord": "樹木", "hiragana": "じゅもく", "meaning": "Cây cối thân gỗ (Thụ mộc)", "explanation": "樹木 đọc là じゅもく."}, {"id": 7, "sentence": "⑦ 【熊の家】熊（ [blank] ）は…", "answer": "くま", "targetWord": "熊", "hiragana": "くま", "meaning": "Con gấu", "explanation": "Chữ 熊 đọc Kun-yomi là くま."}, {"id": 8, "sentence": "⑧ …雄（ [blank] ）のタロウしかいませんでしたが、この度お嫁さんが来ることになりました。", "answer": "おす", "targetWord": "雄", "hiragana": "おす", "meaning": "Con đực (chú gấu đực Taro)", "explanation": "Chữ 雄 (HÙNG - con đực) đọc Kun-yomi là おす."}]}', 1, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES
        (v_ch_id, 'SENTENCE_CLOZE', 'Minigame 2: 【2-B】 Thông báo từ Sở thú ARC — Nông trại trẻ em & Quầy lưu niệm ⑨～⑮ (p.75)', 'Tiếp tục quan sát tờ thông báo「ARC動物園からのお知らせ」trang 75 (7章・8章 クイズ). Chọn cách đọc Hiragana chính xác cho các từ gạch chân từ ⑨ đến ⑮:', 'https://bxqwarbeocbsfjieqbsq.supabase.co/storage/v1/object/public/kanji-assets/n1/quizzes/crops/ch08_g2.webp', '{"wordBank": ["めす", "へび", "かめ", "かいこ", "まゆだま", "くき", "はちみつ"], "questions": [{"id": 9, "sentence": "⑨ 雌（ [blank] ）のハナコがやってきます。来年赤ちゃんが見られるか…。", "answer": "めす", "targetWord": "雌", "hiragana": "めす", "meaning": "Con cái (cô gấu cái Hanako)", "explanation": "Chữ 雌 (THƯ - con cái) đọc Kun-yomi là めす."}, {"id": 10, "sentence": "⑩ 蛇（ [blank] ）をマフラーのように巻く体験もできます。", "answer": "へび", "targetWord": "蛇", "hiragana": "へび", "meaning": "Con rắn (trải nghiệm quấn rắn quanh cổ như khăn choàng)", "explanation": "Chữ 蛇 đọc Kun-yomi là へび."}, {"id": 11, "sentence": "⑪ 今月は亀（ [blank] ）のレースが行われます。", "answer": "かめ", "targetWord": "亀", "hiragana": "かめ", "meaning": "Con rùa (cuộc đua rùa)", "explanation": "Chữ 亀 (QUY - con rùa) đọc Kun-yomi là かめ."}, {"id": 12, "sentence": "⑫ シルクのスカーフ：園内で飼育している蚕（ [blank] ）の…", "answer": "かいこ", "targetWord": "蚕", "hiragana": "かいこ", "meaning": "Con tằm", "explanation": "Chữ 蚕 (TÀM - con tằm) đọc Kun-yomi là かいこ."}, {"id": 13, "sentence": "⑬ …蚕の繭玉（ [blank] ）から作りました。", "answer": "まゆだま", "targetWord": "繭玉", "hiragana": "まゆだま", "meaning": "Kén tằm tròn", "explanation": "繭玉 đọc là まゆだま (chữ 繭 - KIỂN đọc là まゆ)."}, {"id": 14, "sentence": "⑭ 草の茎（ [blank] ）から染料を作って染め、自然な風合いになっています。", "answer": "くき", "targetWord": "茎", "hiragana": "くき", "meaning": "Thân/cuống cây cỏ", "explanation": "Chữ 茎 (HÀNH - thân cây) đứng độc lập đọc là くき."}, {"id": 15, "sentence": "⑮ 蜂蜜（ [blank] ）：癖がない味なので、パンに塗ったり、ヨーグルトに入れたりと、いろいろ楽しめます。", "answer": "はちみつ", "targetWord": "蜂蜜", "hiragana": "はちみつ", "meaning": "Mật ong", "explanation": "蜂蜜 đọc là はちみつ."}]}', 2, NOW());
    END IF;
